  window.STUDY_DATA.questions.push({"id":"ee01","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"某电阻两端电压 12 V，电流 2 A，则电阻与功率分别为（　）","options":["6 Ω，24 W","24 Ω，12 W","6 Ω，12 W","0.5 Ω，24 W"],"answer":"6 Ω，24 W","pitfalls":["R=U/I别算反；P=UI=24W"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】6 Ω，24 W 【考点】电路基本概念 【一步步怎么算】 ① 题目：某电阻两端电压 12 V，电流 2 A，则电阻与功率分别为（ ）。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ","analysis":"【审题】已知电阻两端电压 U=12 V、电流 I=2 A，求电阻 R 与功率 P，属于欧姆定律与功率公式的直接计算题。注意是“分别”求 R 和 P，不是只求一个量。【定律/公式】欧姆定律：R=U/I；电功率：P=UI=I²R=U²/R。【步骤】① 因为已知 U 和 I，所以用电阻定义式 R=U/I，代入得 R=12/2=6 Ω；② 因为已知 U 和 I，所以用功率式 P=UI，代入得 P=12×2=24 W；③ 因为也可用 P=I²R 验算，所以 P=2²×6=24 W，与 UI 结果一致，说明计算正确。【答案】6 Ω，24 W。【易错】×1 把 R=U/I 算反成 I/U=0.5 Ω（对应选项 D 前半）；×2 功率只算 U 或只算 I 得 12 W（选项 C 后半），漏乘另一个量；×3 单位搞混，把 Ω 与 W 对调，或把电压电流代成同一量。【口诀】欧姆电阻压除流，功率电压乘电流；验算平方再一回，单位伏安欧瓦齐。","steps":["【秒懂考点】欧姆定律 R=U/I，功率 P=UI","【第一步：求电阻】U=12V，I=2A，R=U/I=12/2=6Ω","【第二步：求功率】P=UI=12×2=24W","【第三步】也可用 P=I²R=4×6=24W，结果一致","【第四步：排除】24Ω是把U/I算反；12W漏乘；0.5Ω是I/U","【答案】选6Ω，24W"]});
  window.STUDY_DATA.questions.push({"id":"ee02","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"理想电压源的特点是（　）","options":["端电压恒定，电流由外电路决定","电流恒定，电压由外电路决定","电压电流都恒定","内阻无穷大"],"answer":"端电压恒定，电流由外电路决定","pitfalls":["电压源定电压，电流源定电流"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】端电压恒定，电流由外电路决定 【考点】电路基本概念 【一步步怎么算】 ① 题目：理想电压源的特点是（ ）。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注","analysis":"【审题】问理想电压源的外特性：端电压与输出电流各自由谁决定。这是电源模型的核心概念题，要区分“谁被源钳住、谁由外电路定”。【定律/公式】理想电压源定义：u(t)=Us(t)，与外电路无关；输出电流 i 由外电路决定，内阻 rs=0。理想电流源则相反：i=Is 恒定，端电压由外电路决定。【步骤】① 因为理想电压源对外保持端电压恒定，所以无论接什么负载，端电压都等于源电压；② 因为电流要满足外电路的伏安关系（如 I=U/R外），所以电流大小由外电路决定，源只负责“给够”；③ 因为“电流恒定、电压由外电路决定”是理想电流源的特点，“电压电流都恒定”违背外电路约束，“内阻无穷大”是理想电流源内阻特征，所以 A 正确，其余错误。【答案】端电压恒定，电流由外电路决定。【易错】×1 把电压源与电流源的特点对调；×2 认为理想电压源内阻无穷大（实际为 0，无穷大对应理想电流源）；×3 认为电压电流都恒定，忽略外电路对电流的制约。【口诀】压源定压流外定，流源定流压外定；压源内阻等于零，流源内阻无穷大。","steps":["【秒懂考点】理想电压源：端电压恒定","【第一步】电压源的任务是维持两端电压不变","【第二步】提供多大电流由外接电阻决定（I=U/R外）","【第三步】电流恒定是电流源的特点","【答案】选端电压恒定，电流由外电路决定"]});
  window.STUDY_DATA.questions.push({"id":"ee03","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"电功率 P 与电压 U、电流 I 的关系是（　）","options":["P= (frac{U}{I})","P=UI","P=U+I","P= (frac{I}{U})"],"answer":"P=UI","pitfalls":["P=UI是基本公式"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】P=UI 【考点】电路基本概念 【一步步怎么算】 ① 题目：电功率 P 与电压 U、电流 I 的关系是（ ）。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④","analysis":"【审题】考查电功率 P 与电压 U、电流 I 的基本关系式，属于公式识记题，注意选项里有 U/I、I/U 等干扰项。【定律/公式】电功率定义式：P=UI；结合欧姆定律还有 P=I²R=U²/R。U/I 是电阻 R，I/U 是电导 G，都不是功率。【步骤】① 因为功率是电压与电流的乘积，所以 P=UI，单位为瓦特 W；② 因为 A 选项 U/I 的量纲是电阻 Ω，所以不是功率公式；③ 因为 C 选项 U+I 量纲不同不能相加，D 选项 I/U 是电导 S，所以只有 B 正确。【答案】P=UI。【易错】×1 记成 P=U/I，与电阻公式混淆；×2 记成 P=U+I，不理解量纲必须一致才能运算；×3 把 P=I²R 当成“P 与 U、I 的关系”而漏掉最简定义式 UI。【口诀】功率等于压乘流，欧姆变形平方走；压除电流是电阻，电流除压是电导。","steps":["【秒懂考点】功率公式 P=UI","【第一步】电功率=电压×电流，单位瓦W","【第二步】U/I是电阻，I/U是电导，U+I无意义","【答案】选P=UI"]});
  window.STUDY_DATA.questions.push({"id":"ee04","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"使用万用表测直流电流时，应将表笔（　）接入电路。","options":["并联","串联","随意并联","只接一端"],"answer":"串联","pitfalls":["电流串联，电压并联"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】串联 【考点】电路基本概念 【一步步怎么算】 ① 题目：使用万用表测直流电流时，应将表笔（ ）接入电路。。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注","analysis":"【审题】问用万用表测直流电流时表笔的接入方式，属于电工测量操作规范题，关键在电流表内阻极小、必须串入被测支路。【定律/公式】电流表内阻 RA≈0，应串联在被测支路中使支路电流全部流过表头；电压表内阻 RV→∞，才并联。误并联会近似短路。【步骤】① 因为电流表要测支路电流，所以必须与被测元件串联，让同一电流流过表头；② 因为电流表内阻极小，所以若并联在元件两端会把元件短路，可能烧表或烧电路；③ 因为“随意并联”“只接一端”都无法形成电流通路或测量失真，所以只能串联。【答案】串联。【易错】×1 与电压表测电压的并联接法混淆；×2 忘记先选量程、红表笔接高电位端（正接线柱）；×3 带电改接或在大电流回路直接并联，造成短路打火。【口诀】电流表串电压并，电流串入支路中；红笔高电黑笔低，量程先选再接通。","steps":["【秒懂考点】测电流必须串联","【第一步】电流表要让被测电流流过它，所以串进电路","【第二步】并联测电压（电压表），不能接反","【答案】选串联"]});
  window.STUDY_DATA.questions.push({"id":"ee26","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"电流的单位是（　）","options":["伏特","安培","欧姆","瓦特"],"answer":"安培","pitfalls":["安培"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】安培 【考点】电路基本概念 【一步步怎么算】 ① 题目：电流的单位是（ ）。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符号。 ","analysis":"【审题】问电流的国际单位，属于物理量单位识记题，四个选项都是电学常用单位，要按“物理量—单位”一一对应。【定律/公式】电流 I 的单位是安培（A）；电压 U 的单位是伏特（V）；电阻 R 的单位是欧姆（Ω）；功率 P 的单位是瓦特（W）。【步骤】① 因为电流表示单位时间通过导体截面的电荷量（I=q/t），所以其单位定义为安培 A；② 因为伏特是电压单位、欧姆是电阻单位、瓦特是功率单位，所以 A、C、D 都不对；③ 因为 1 A=1 C/s，1 kA=1000 A，1 mA=10⁻³ A，所以安培是电流的主单位。【答案】安培。【易错】×1 把伏特误当电流单位（电压才是伏特）；×2 把瓦特误当电流单位（功率才是瓦特）；×3 单位换算时 mA 与 A 进率记成 100 而不是 1000。【口诀】电流安培压伏特，电阻欧姆功瓦特；毫安一千等于安，单位对应别记错。","steps":["【秒懂考点】电流单位安培（A）","【第一步】伏特是电压，欧姆是电阻，瓦特是功率","【答案】选安培"]});
  window.STUDY_DATA.questions.push({"id":"ee27","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"电阻的单位是（　）","options":["欧姆","法拉","亨利","赫兹"],"answer":"欧姆","pitfalls":["欧姆"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】欧姆 【考点】电路基本概念 【一步步怎么算】 ① 题目：电阻的单位是（ ）。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符号。 ","analysis":"【审题】问电阻的国际单位，与电流单位题同属单位识记，但本题专考电阻，选项给出法拉、亨利、赫兹等易混单位。【定律/公式】电阻 R 的单位是欧姆（Ω）；电容 C 的单位是法拉（F）；电感 L 的单位是亨利（H）；频率 f 的单位是赫兹（Hz）。欧姆定义：1 Ω=1 V/A。【步骤】① 因为电阻反映导体对电流的阻碍作用，R=U/I，单位为伏/安，所以命名为欧姆 Ω；② 因为法拉是电容单位、亨利是电感单位、赫兹是频率单位，所以 B、C、D 均错；③ 因为 1 kΩ=1000 Ω，1 MΩ=10⁶ Ω，所以欧姆是电阻主单位。【答案】欧姆。【易错】×1 把法拉误当电阻单位（电容才是法拉）；×2 把亨利误当电阻单位（电感才是亨利）；×3 大电阻换算时把 MΩ 与 kΩ 进率搞混（1 MΩ=1000 kΩ）。【口诀】电阻欧姆容法拉，电感亨利频赫兹；伏特每安是一欧，换算千进要记牢。","steps":["【秒懂考点】电阻单位欧姆（Ω）","【第一步】法拉是电容，亨利是电感，赫兹是频率","【答案】选欧姆"]});
  window.STUDY_DATA.questions.push({"id":"ee28","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"理想电流源的特点是（　）","options":["输出电流恒定","输出电压恒定","功率恒定","内阻为 0"],"answer":"输出电流恒定","pitfalls":["输出电流恒定"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】输出电流恒定 【考点】电路基本概念 【一步步怎么算】 ① 题目：理想电流源的特点是（ ）。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/","analysis":"【审题】问理想电流源的特点，与理想电压源题成对出现，核心是“电流被源钳住、电压由外电路决定”。【定律/公式】理想电流源定义：i(t)=Is(t)，与外电路无关；端电压 u 由外电路决定，内阻 rs→∞。【步骤】① 因为理想电流源对外保持输出电流恒定，所以无论负载如何变化，电流都等于 Is；② 因为端电压要满足外电路伏安关系（如 U=IR外），所以电压由外电路决定，源可升可降甚至反向；③ 因为“输出电压恒定”是电压源特点，“功率恒定”不成立（P=UI 会随 U 变），“内阻为 0”是理想电压源特征，所以只有 A 正确。【答案】输出电流恒定。【易错】×1 与理想电压源“端电压恒定”记混；×2 认为理想电流源内阻为 0（实际为无穷大）；×3 认为功率恒定，忽略端电压会随负载变化。【口诀】流源定流压外定，内阻无穷是特征；压源定压流外定，内阻为零记得清。","steps":["【秒懂考点】理想电流源：输出电流恒定","【第一步】端电压由外电路决定，与电压源对偶","【答案】选输出电流恒定"]});
  window.STUDY_DATA.questions.push({"id":"ee29","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"U=12V，I=3A，则 R=（　）","options":["4 Ω","36 Ω","9 Ω","0.25 Ω"],"answer":"4 Ω","pitfalls":["4Ω"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】4 Ω 【考点】电路基本概念 【一步步怎么算】 ① 题目：U=12V，I=3A，则 R=（ ）。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（12）计算。 ④ 注意","analysis":"【审题】已知电压 U=12 V、电流 I=3 A，求电阻 R，是欧姆定律的一步计算，注意选项里有 36（乘了）和 0.25（除反了）。【定律/公式】欧姆定律：R=U/I。【步骤】① 因为电阻等于电压与电流之比，所以 R=U/I=12/3=4 Ω；② 因为 12×3=36 是乘法误用，对应选项 B，所以排除；③ 因为 3/12=0.25 是 U、I 位置颠倒，对应选项 D，9 Ω 与 12、3 无合理关系，所以只有 4 Ω 正确。【答案】4 Ω。【易错】×1 把 U/I 做成 U×I=36 Ω（选项 B）；×2 把分子分母写反得 0.25 Ω（选项 D）；×3 单位写成 V 或 A 而不是 Ω。【口诀】电阻压除电流算，十二除三是四欧；乘法除法别弄反，单位欧姆要写全。","steps":["【秒懂考点】R=U/I","【第一步】R=12/3=4Ω","【第二步】36Ω是U×I，0.25Ω是I/U","【答案】选4Ω"]});
  window.STUDY_DATA.questions.push({"id":"ee30","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"P=UI，若 U=6V，I=2A，则 P=（　）","options":["3 W","12 W","8 W","4 W"],"answer":"12 W","pitfalls":["12W"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】12 W 【考点】电路基本概念 【一步步怎么算】 ① 题目：P=UI，若 U=6V，I=2A，则 P=（ ）。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（6）计算","analysis":"【审题】已知 U=6 V、I=2 A，用 P=UI 求功率，是一步乘法计算，干扰项来自 6+2、6/2、6-2 等错误运算。【定律/公式】电功率：P=UI（亦可 P=I²R=U²/R）。【步骤】① 因为功率等于电压乘电流，所以 P=UI=6×2=12 W；② 因为 6+2=8 对应选项 C，是误用加法，量纲也不允许电压加电流，所以排除；③ 因为 6/2=3 对应选项 A、6-2=4 对应选项 D，都不是功率公式，所以只有 12 W 正确。【答案】12 W。【易错】×1 把 P=UI 做成 U/I=3 W；×2 做成 U+I=8 W，忽略量纲；×3 忘记写单位 W，或把 12 写成 12 V/A 之类错误单位。【口诀】功率就是压乘流，六伏两安十二瓦；加减除法都不对，单位瓦特记住它。","steps":["【秒懂考点】P=UI","【第一步】P=6×2=12W","【第二步】3W是U/I","【答案】选12W"]});
  window.STUDY_DATA.questions.push({"id":"ee51","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"万用表测电阻前应（　）","options":["带电测","断电并调零","短接电源","并联进电路"],"answer":"断电并调零","pitfalls":["断电并调零"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】断电并调零 【考点】电路基本概念 【一步步怎么算】 ① 题目：万用表测电阻前应（ ）。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）","analysis":"【审题】问万用表测电阻前的准备操作，属于仪表使用规范：测电阻必须断电，并且要欧姆调零。【定律/公式】欧姆档内部有电池，被测电路必须不带电；每换一次量程都要将两表笔短接进行欧姆调零，以保证读数准确。【步骤】① 因为带电测电阻会损坏欧姆表头并造成误读，所以必须先切断被测电路电源；② 因为欧姆档量程改变后内阻与电池电压影响零点，所以要短接表笔、调节欧姆调零旋钮使指针指 0 Ω；③ 因为“短接电源”会烧电路、“并联进电路”是电压表接法，所以只有“断电并调零”正确。【答案】断电并调零。【易错】×1 带电测电阻，损坏仪表且读数无意义；×2 换量程后不重新欧姆调零，读数偏差大；×3 把测电阻误当成测电压去并联，或测完电阻忘把档位离开欧姆档。【口诀】测阻先断电，短接再调零；换档必重调，档位莫停欧。","steps":["【秒懂考点】测电阻先断电并调零","【第一步】带电测会烧坏表头；欧姆档要先短接表笔调零","【答案】选断电并调零"]});
  window.STUDY_DATA.questions.push({"id":"ee52","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"电阻串联总电阻（　）各分电阻","options":["大于","小于","等于","不确定"],"answer":"大于","pitfalls":["大于"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】大于 【考点】电路基本概念 【一步步怎么算】 ① 题目：电阻串联总电阻（ ）各分电阻。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）","analysis":"【审题】问电阻串联后总电阻与各分电阻的大小关系，属于串并联性质题，不需具体数值，只需定性判断。【定律/公式】电阻串联：R总=R1+R2+…+Rn。因各电阻为正值，故 R总>Ri（任一分电阻）。【步骤】① 因为串联时电流处处相等、各电阻电压按阻值分配，等效电阻等于各电阻之和；② 因为 R1、R2 均大于 0，所以 R总=R1+R2 必然大于其中任何一个分电阻；③ 因为“小于”是并联特点（并联总电阻小于任一分电阻），“等于”只在只有一个电阻时成立，所以选“大于”。【答案】大于。【易错】×1 与并联规律记反，并联总电阻才小于任一分电阻；×2 以为串联是“分压所以总阻变小”，概念颠倒；×3 把“总电阻大于各分电阻”误说成“大于各分电阻之和”（总阻等于之和，不是大于之和）。【口诀】串阻相加总更大，并联倒数总更小；串大并小要记牢，两个电阻最明了。","steps":["【秒懂考点】串联总电阻大于任一分电阻","【第一步】R=R1+R2+...，越串越大","【答案】选大于"]});
  window.STUDY_DATA.questions.push({"id":"ee53","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"电能的单位是（　）","options":["J","W","V","A"],"answer":"J","pitfalls":["J"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】J 【考点】电路基本概念 【一步步怎么算】 ① 题目：电能的单位是（ ）。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符号。 ⑤","analysis":"【审题】问电能（电功）的国际单位，选项给出 J、W、V、A，要区分能量单位与功率单位。【定律/公式】电能（电功）W=UIt=Pt，单位是焦耳 J；功率 P 的单位是瓦特 W；电压 V；电流 A。实用中 1 度=1 kW·h=3.6×10⁶ J。【步骤】① 因为电能是功率对时间的积累（W=Pt），能量单位与机械能一样用焦耳 J，所以电能单位是 J；② 因为 W（瓦特）是功率单位，表示能量变化的快慢，不是能量本身，所以排除 B；③ 因为 V 是电压单位、A 是电流单位，都不是能量单位，所以选 J。【答案】J。【易错】×1 把电能单位写成 W，混淆电能与电功率；×2 把“度”当成焦耳（1 度=3.6×10⁶ J）；×3 用 kW·h 当国际单位（那是常用单位，国际单位是 J）。【口诀】电能焦耳功瓦特，千瓦时是常用说；一度等于三六百万焦，功率时间乘出来。","steps":["【秒懂考点】电能单位焦耳J","【第一步】W是功率单位；工程上也用kWh（度）","【答案】选J"]});
  window.STUDY_DATA.questions.push({"id":"ee54","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"single","stem":"R=20Ω，I=0.2A，电压 U=（　）","options":["4 V","100 V","10 V","2 V"],"answer":"4 V","pitfalls":["4V"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】4 V 【考点】电路基本概念 【一步步怎么算】 ① 题目：R=20Ω，I=0.2A，电压 U=（ ）。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（20）计算。 ④","analysis":"【审题】已知 R=20 Ω、I=0.2 A，求电压 U，是欧姆定律 U=IR 的一步计算，注意选项有 100（除反）和 10、2 等干扰。【定律/公式】欧姆定律：U=IR。【步骤】① 因为电压等于电流乘电阻，所以 U=IR=0.2×20=4 V；② 因为 20/0.2=100 对应选项 B，是把公式做成 R/I，量纲也不对，所以排除；③ 因为 10 V、2 V 与 20、0.2 无正确运算关系，所以只有 4 V 正确。【答案】4 V。【易错】×1 做成 R/I=100 V（选项 B）；×2 把 0.2 当成 2，得 40 V 或 4 Ω；×3 单位写成 A 或 Ω 而不是 V。【口诀】电压电流乘电阻，零点二安二十欧；相乘正好是四伏，除法乘法别搞混。","steps":["【秒懂考点】U=IR","【第一步】U=0.2×20=4V","【第二步】100V是I×R算反成除错","【答案】选4V"]});
  window.STUDY_DATA.questions.push({"id":"exam-ee-2026-01","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"欧姆定律","type":"single","typeLabel":"单选","stem":"已知电阻R=10Ω，电压U=20V，电流I=（　）","options":["2A","0.5A","200A","10A"],"answer":"2A","difficulty":1,"difficultyLabel":"基础","source":"school","tags":["真题","2026"],"analysis":"【审题】已知电阻 R=10 Ω、电压 U=20 V，求电流 I，属于欧姆定律 I=U/R 的直接计算，是专升本高频【定律/公式】欧姆定律：I=U/R。【步骤】① 因为电流等于电压除以电阻，所以 I=U/R=20/10=2 A；② 因为 10/20=0.5 对应选项 B，是分子分母颠倒，所以排除；③ 因为 20×10=200 对应选项 C、20/10 之外的 10 A 无依据，所以只有 2 A 正确。【答案】2A。【易错】×1 把 I=U/R 做成 R/U=0.5 A；×2 把 U/R 做成 U×R=200 A；×3 单位漏写 A，或把 2 A 误写成 2 V。【口诀】电流压除电阻算，二十除十是两安；分子分母要认清，乘法结果不能安。","steps":["【秒懂考点】20/10=2","【第一步】U/R","【答案】2A"],"pitfalls":["20÷10=2"]});
  window.STUDY_DATA.questions.push({"id":"exam25-ee-s01","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"欧姆定律","type":"single","typeLabel":"单选","stem":"已知R=20Ω，U=10V，电流I=（　）","options":["0.5A","2A","200A","10A"],"answer":"0.5A","difficulty":1,"difficultyLabel":"基础","source":"school","tags":["2025真题","电工"],"analysis":"【审题】已知 R=20 Ω、U=10 V，求电流 I，同样是 I=U/R，数值与上题互换，防止背答案。【定律/公式】欧姆定律：I=U/R。【步骤】① 因为 I=U/R，所以 I=10/20=0.5 A；② 因为 20/10=2 对应选项 B，是 U、R 位置颠倒，所以排除；③ 因为 10×20=200 对应选项 C，误用乘法，10 A 也与公式不符，所以只有 0.5 A 正确。【答案】0.5A。【易错】×1 做成 R/U=2 A；×2 做成 U×R=200 A；×3 小数点丢失写成 5 A 或 0.05 A。【口诀】十伏除以二十欧，电流正好零点五；压在上阻在下，颠倒立刻差四倍。","steps":["【秒懂考点】10/20=0.5","【第一步】U/R","【答案】0.5A"],"pitfalls":["10÷20=0.5"]});
  window.STUDY_DATA.questions.push({"id":"exam25-ee-s02","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"功率","type":"single","typeLabel":"单选","stem":"一个电阻两端电压10V，电流2A，功率是（　）","options":["20W","5W","12W","8W"],"answer":"20W","difficulty":1,"difficultyLabel":"基础","source":"school","tags":["2025真题","电工"],"analysis":"【审题】已知电阻两端电压 10 V、电流 2 A，求功率，一步乘法，注意不要用 U/I 或 U+I。【定律/公式】电功率：P=UI。【步骤】① 因为 P=UI，所以 P=10×2=20 W；② 因为 10/2=5 对应选项 B，是误用电阻公式 U/I，所以排除；③ 因为 10+2=12 对应选项 C、10-2=8 对应选项 D，都不是功率运算，所以只有 20 W 正确。【答案】20W。【易错】×1 做成 U/I=5 W（那是求电阻 5 Ω）；×2 做成 U+I=12 W，量纲错误；×3 忘记单位 W，或写成 20 V·A 不化简。【口诀】功率电压乘电流，十伏两安二十瓦；若求电阻才相除，加减不能出功率。","steps":["【秒懂考点】10×2=20","【第一步】P=UI","【答案】20W"],"pitfalls":["10×2=20"]});
  window.STUDY_DATA.questions.push({"id":"ne1001","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电流与电压","type":"single","typeLabel":"单选","stem":"在电路中，参考方向是指（　）","options":["实际方向","假定的正方向","电子流动方向","电源正极方向"],"answer":"假定的正方向","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","参考方向"],"analysis":"【审题】问电路中“参考方向”的含义，是电路分析的基本概念：参考方向是分析前假定的正方向，与实际方向可能一致也可能相反。【定律/公式】参考方向（正方向）是人为假定的电流/电压正方向；实际方向与参考方向一致时数值为正，相反时为负。关联参考方向下 U=IR 取正号。【步骤】① 因为实际方向在求解前往往未知，所以必须先假定一个正方向作为计算基准，这就是参考方向；② 因为参考方向是“假定”的，并非电子流动方向（电子流与电流方向相反），也不是电源正极方向，所以 B 正确；③ 因为算出的电流/电压为负只表示实际方向与假定相反，不表示错误，所以参考方向是分析工具而非实际方向。【答案】假定的正方向。【易错】×1 把参考方向当成实际方向；×2 把电流方向当成电子流动方向（电子流反向）；×3 认为参考方向必须与电源正极一致，实际上可任意假定。【口诀】参考方向是假定，算正同向算负反；电子流向反电流，先定正向再计算。","steps":["【秒懂考点】参考方向假定","【第一步】非实际","【答案】假定的正方向"],"pitfalls":["假定正方向"]});
  window.STUDY_DATA.questions.push({"id":"ne1003","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电位计算","type":"single","typeLabel":"单选","stem":"电路中a点电位为10V，b点电位为-5V，则Uab为（　）","options":["5V","-5V","15V","-15V"],"answer":"15V","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","电位"],"analysis":"【审题】已知 a 点电位 Va=10 V、b 点电位 Vb=-5 V，求电压 Uab，考查电位差定义 Uab=Va−Vb。【定律/公式】两点间电压等于两点电位之差：Uab=Va−Vb。注意 Vb 为负值时是减去负数。【步骤】① 因为 Uab 表示 a 到 b 的电位降落，所以 Uab=Va−Vb；② 因为 Va=10 V、Vb=-5 V，所以 Uab=10−(−5)=10+5=15 V；③ 因为 10+(−5)=5 是把 Vb 当 +5，10−5 再变号错成 -5 或 -15 都是符号错误，所以正确值为 15 V。【答案】15V。【易错】×1 忘记 Vb 本身是负值，算成 10−5=5 V；×2 符号弄反算成 Vb−Va=-15 V（那是 Uba）；×3 把 -5 V 当成 5 V 代入，得 5 V 或 -5 V。【口诀】电压电位差一减，Uab 等于 Va 减 Vb；减去负值等于加，十五伏特是正答。","steps":["【秒懂考点】10-(-5)=15","【第一步】减负加","【答案】15V"],"pitfalls":["减负=加，15"]});
  window.STUDY_DATA.questions.push({"id":"ne1101","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"欧姆定律","type":"single","typeLabel":"单选","stem":"欧姆定律适用于（　）","options":["线性电阻","非线性电阻","任何电路","金属和半导体"],"answer":"线性电阻","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","欧姆定律"],"analysis":"【审题】问欧姆定律的适用范围，考查“线性电阻”与“非线性元件”的区别，不能答“任何电路”。【定律/公式】欧姆定律 U=IR（或 I=U/R）只适用于线性电阻元件（伏安特性为过原点直线、R 为常数）。非线性电阻（二极管、热敏电阻等）R 随电压电流变化，不能直接用。含源支路、电感电容的交流电路需用相量或更一般形式。【步骤】① 因为欧姆定律描述的是线性电阻上电压与电流成正比，比例系数 R 恒定，所以只适用于线性电阻；② 因为非线性电阻的 R 不是常数，二极管等不满足 U=IR，所以排除 B、D；③ 因为“任何电路”太宽，含源网络、动态元件不能直接套用欧姆定律，所以只有“线性电阻”正确。【答案】线性电阻。【易错】×1 认为任何导电元件都满足欧姆定律；×2 把半导体、二极管也当成线性电阻；×3 忽略“线性、时不变、R 为常数”的前提，把欧姆定律用到电容电感的暂态过程。【口诀】欧姆只对线性阻，正比关系是前提；二极管热敏非线性，任何电路不成立。","steps":["【秒懂考点】欧姆定律适用线性电阻","【第一步】非线性不适用","【答案】线性电阻"],"pitfalls":["仅线性电阻"]});
  window.STUDY_DATA.questions.push({"id":"ne1103","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电能单位","type":"single","typeLabel":"单选","stem":"日常生活中说的1度电等于（　）","options":["1焦耳","1瓦秒","1千瓦时","1千瓦"],"answer":"1千瓦时","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","电能"],"analysis":"【审题】问日常“1 度电”等于多少，是电能单位换算常识题，度是千瓦时的俗称。【定律/公式】1 度=1 kW·h=1000 W×3600 s=3.6×10⁶ J。功率单位 kW 乘时间单位 h 才是能量。【步骤】① 因为“度”是电能的常用单位，1 度定义为 1 千瓦功率工作 1 小时，所以 1 度=1 kW·h；② 因为 1 J=1 W·s，1 W·s 远小于 1 度（差 3.6×10⁶ 倍），所以排除 A、B；③ 因为 1 kW 是功率不是能量，所以排除 D，正确【答案】1千瓦时。【易错】×1 把度当成焦耳（1 度=3.6×10⁶ J）；×2 把度当成瓦秒（那是焦耳）；×3 把度当成千瓦（千瓦是功率）。【口诀】一度就是千瓦时，一千瓦用一小时；换算焦耳三六百万，千瓦是功不是能。","steps":["【秒懂考点】1度=1千瓦时","【第一步】3.6×10⁶J","【答案】1千瓦时"],"pitfalls":["度=千瓦时"]});
  window.STUDY_DATA.questions.push({"id":"ne1301","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电流方向","type":"single","typeLabel":"单选","stem":"电流的正方向规定为（　）","options":["正电荷移动方向","负电荷移动方向","电子移动方向","任意方向"],"answer":"正电荷移动方向","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","电流"],"analysis":"【审题】问电流正方向的规定，是物理学约定：规定正电荷定向移动的方向为电流方向，与电子（负电荷）移动方向相反。【定律/公式】电流方向的国际规定：正电荷运动方向为电流正方向；金属导体中自由电子定向移动方向与电流方向相反。I=q/t 中 q 取正电荷。【步骤】① 因为历史上规定正电荷移动方向为电流方向，所以 A 正确；② 因为负电荷（电子）移动方向与电流方向相反，所以 B、C 错误；③ 因为“任意方向”不成立，电流方向有明确物理规定（参考方向才是人为假定的），所以 D 错误。【答案】正电荷移动方向。【易错】×1 把电子移动方向当成电流方向（金属导体中二者相反）；×2 把电流方向与电压方向规定混为一谈（电压是高电位指向低电位）；×3 把“规定的电流正方向”与“参考方向”混淆（前者是物理约定，后者是解题假定）。【口诀】电流方向正电荷，电子移动正相反；参考方向可假定，物理规定不能乱。","steps":["【秒懂考点】正电荷方向","【第一步】电子反","【答案】正电荷移动方向"],"pitfalls":["与电子相反"]});
  window.STUDY_DATA.questions.push({"id":"ne1302","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电压单位","type":"single","typeLabel":"单选","stem":"电压的国际单位是（　）","options":["安培(A)","伏特(V)","欧姆(Ω)","瓦特(W)"],"answer":"伏特(V)","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","单位"],"analysis":"【审题】问电压的国际单位，单位识记题，与电流、电阻、功率单位对照记忆。【定律/公式】电压 U 的单位是伏特（V）；电流 A；电阻 Ω；功率 W。1 V=1 J/C，即移动 1 C 电荷做功 1 J。【步骤】① 因为电压是电位差，表示单位正电荷的电场力做功，单位命名为伏特 V，所以 B 正确；② 因为安培是电流单位、欧姆是电阻单位、瓦特是功率单位，所以 A、C、D 均错；③ 因为 1 kV=1000 V，1 mV=10⁻³ V，所以伏特是电压主单位。【答案】伏特(V)。【易错】×1 把安培误当电压单位；×2 把瓦特误当电压单位（瓦是功率）；×3 电压与电动势单位相同都是 V，但概念不同，答题时张冠李戴。【口诀】电压伏特流安培，电阻欧姆功瓦特；单位四对要记清，伏特每库也是一。","steps":["【秒懂考点】电压伏特","【第一步】电流A、电阻Ω、功率W","【答案】伏特(V)"],"pitfalls":["V电压A电流Ω电阻W功率"]});
  window.STUDY_DATA.questions.push({"id":"ne1303","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"功率计算","type":"single","typeLabel":"单选","stem":"一个电阻两端电压12V，流过电流2A，消耗功率是（　）","options":["6W","24W","14W","10W"],"answer":"24W","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","功率"],"analysis":"【审题】已知电阻电压 12 V、电流 2 A，求消耗功率，与前面 P=UI 题同型，强调“消耗”即电阻吸收功率。【定律/公式】电阻消耗功率：P=UI=I²R=U²/R。【步骤】① 因为 P=UI，所以 P=12×2=24 W；② 因为 12/2=6 对应选项 A，那是求电阻 6 Ω 不是功率，所以排除；③ 因为 12+2=14 对应选项 C、12-2=10 对应选项 D，运算无物理意义，所以只有 24 W 正确。【答案】24W。【易错】×1 做成 U/I=6 W（混淆电阻与功率）；×2 做成 U+I=14 W，量纲错误；×3 用 P=I²R 时把 R 当 12 Ω 而不是 6 Ω，算出 48 W。【口诀】消耗功率压乘流，十二两安二十四；六欧若是电阻值，平方公式也一致。","steps":["【秒懂考点】P=12×2=24","【第一步】不是除","【答案】24W"],"pitfalls":["12×2=24"]});
  window.STUDY_DATA.questions.push({"id":"ne1304","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路组成","type":"single","typeLabel":"单选","stem":"完整电路最基本的组成部分不包括（　）","options":["电源","负载","导线","开关电源"],"answer":"开关电源","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","组成"],"analysis":"【审题】问完整电路最基本的组成部分“不包括”哪一项，注意选非题。基本组成是电源、负载、导线（及开关），而“开关电源”是一种电源设备，不是电路基本组成要素。【定律/公式】电路基本组成四要素：电源（提供电能）、负载（消耗电能）、导线（连接传输）、开关（控制通断）。【步骤】① 因为电路要工作必须有电源提供能量、负载消耗能量、导线构成通路，所以 A、B、C 都是基本组成；② 因为“开关电源”是一种把交流转直流的电源装置名称，不是“开关+电源”两个要素，也不是电路基本组成的规范表述，所以 D 不属于最基本组成部分；③ 因为题目问“不包括”，所以选 D。【答案】开关电源。【易错】×1 看成选“包括”而选了电源；×2 把“开关电源”误读成“开关、电源”两个要素；×3 漏掉导线也是基本组成，或把导线当成可有可无。【口诀】电路组成源负载，导线开关四件套；开关电源是设备，不是组成别乱猜。","steps":["【秒懂考点】开关电源是具体器件","【第一步】基本组成为电源负载导线","【答案】开关电源"],"pitfalls":["区分组成与具体器件"]});
  window.STUDY_DATA.questions.push({"id":"ne1305","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"开路","type":"single","typeLabel":"单选","stem":"电路开路时，电流等于（　）","options":["0","无穷大","额定电流","短路电流"],"answer":"0","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","开路"],"analysis":"【审题】问电路开路时电流等于多少，考查开路（断路）状态：回路不通，电流为零。【定律/公式】开路时回路电阻→∞（或断开），由 I=U/R，当 R→∞ 时 I=0；开路电压等于电源电动势（空载）。【步骤】① 因为开路是电路某处断开，电荷无法形成定向移动，所以电流 I=0；② 因为“无穷大”是开路电阻的特点，不是电流，“额定电流”是正常工作电流，“短路电流”是短路时的很大电流，所以 B、C、D 都错；③ 因为开路时电源端电压可不为零（等于电动势），但电流一定为零，所以选 A。【答案】0。【易错】×1 把开路电流与短路电流混淆（短路电流很大）；×2 认为开路时电压也为零（电压可为电源电压）；×3 把“电阻无穷大”与“电流无穷大”记反。【口诀】开路断开电流零，短路电流大无比；开路电压等电势，电阻无穷记心里。","steps":["【秒懂考点】开路I=0","【第一步】无闭合回路","【答案】0"],"pitfalls":["开路0短路大"]});
  window.STUDY_DATA.questions.push({"id":"ne1401","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电源","type":"single","typeLabel":"单选","stem":"电源的作用是（　）","options":["把其他形式能量转换成电能","把电能转换成其他形式能量","储存电能","消耗电能"],"answer":"把其他形式能量转换成电能","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","电源"],"analysis":"【审题】问电源的作用，能量转换角度：电源把其他形式能量转换为电能，供给电路。【定律/公式】电源是将非电能（化学能、机械能、光能等）转化为电能的装置，如电池（化学能→电能）、发电机（机械能→电能）。负载则相反：电能→其他形式能量。【步骤】① 因为电源在电路中提供电能，其本质是能量转换器，把其他形式能量变成电能，所以 A 正确；② 因为“把电能转换成其他形式能量”是负载的作用，所以 B 错误；③ 因为“储存电能”是电容器/电池储能的描述、“消耗电能”是负载行为，所以 C、D 均不符合电源的定义。【答案】把其他形式能量转换成电能。【易错】×1 与负载的能量转换方向记反；×2 认为电源“产生”电能（是转换不是凭空产生，能量守恒）；×3 把电源的作用说成“提供电流”而忽略能量转换本质。【口诀】电源转电为供给，负载耗电转出去；电池化学变电能，发电机械变电力。","steps":["【秒懂考点】电源其他能量转电能","【第一步】负载相反","【答案】把其他形式能量转换成电能"],"pitfalls":["电源转电能，负载转其他"]});
  window.STUDY_DATA.questions.push({"id":"ne1402","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电压方向","type":"single","typeLabel":"单选","stem":"电压的方向规定为（　）","options":["高电位指向低电位","低电位指向高电位","正电荷方向","负电荷方向"],"answer":"高电位指向低电位","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","电压"],"analysis":"【审题】问电压方向的规定，与电流方向规定对照：电压方向是高电位指向低电位（电位降低方向）。【定律/公式】电压（电位差）的正方向规定为从高电位指向低电位，即电位降落方向；Uab>0 表示 a 点电位高于 b 点。【步骤】① 因为电压表示电位差，方向规定为电位降低的方向，所以从高电位指向低电位，A 正确；② 因为低到高是电位升高方向，与电压方向规定相反，所以 B 错误；③ 因为正电荷方向是电流方向规定、负电荷方向更不是电压方向，所以 C、D 均错。【答案】高电位指向低电位。【易错】×1 与电流方向（正电荷移动方向）混淆；×2 记成低电位指向高电位；×3 把电动势方向（低到高，在电源内部）与电压方向（高到低）混为一谈。【口诀】电压方向高到低，电位降落是正向；电流正荷移动向，电动势内低到高。","steps":["【秒懂考点】电压高→低","【第一步】电动势低→高","【答案】高电位指向低电位"],"pitfalls":["高到低"]});
  window.STUDY_DATA.questions.push({"id":"ne1501","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路工作状态","type":"single","typeLabel":"单选","stem":"电源两端被导线直接连接叫（　）","options":["短路","开路","通路","回路"],"answer":"短路","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","短路"],"analysis":"【审题】问电源两端被导线直接连接叫什么状态，属于电路工作状态识别：短路。【定律/公式】短路：电源两端（或某元件两端）被电阻近似为 0 的导线直接连通，电流 I=E/r 很大，可能烧毁电源。开路：断开；通路：正常闭合。【步骤】① 因为导线电阻近似为 0，直接接电源两端会使电流极大，这种状态定义为短路，所以 A 正确；② 因为开路是断开不通、“通路”是正常工作状态、“回路”是闭合路径的统称，所以 B、C、D 均不符合；③ 因为短路时 U=IR≈0（端电压几乎为零）、电流很大，所以短路是危险状态，必须避免。【答案】短路。【易错】×1 把短路与开路概念对调；×2 把“回路”当成短路（回路只是闭合路径，可以正常工作）；×3 忽略短路电流极大可能烧电源，认为只是“接了一下”。【口诀】导线直连是短路，电流猛增压归零；开路断开无电流，通路正常才可行。","steps":["【秒懂考点】导线直连=短路","【第一步】无负载电流大","【答案】短路"],"pitfalls":["短路危险"]});
  window.STUDY_DATA.questions.push({"id":"ne1502","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"参考方向","type":"single","typeLabel":"单选","stem":"计算出电流值为负，说明（　）","options":["实际方向与参考方向相反","实际方向与参考方向相同","算错了","电流为0"],"answer":"实际方向与参考方向相反","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","参考方向"],"analysis":"【审题】问计算出电流为负说明什么，考查参考方向与实际方向的关系：负值只表示实际方向与假定的参考方向相反。【定律/公式】电路分析中先假定电流参考方向，列方程求解；若 i<0，则实际方向与参考方向相反；若 i>0，则相同。负号不是错误。【步骤】① 因为参考方向是假定的正方向，求解结果的正负表示实际方向与参考方向的关系，所以为负说明二者相反，A 正确；② 因为为正才是“实际与参考相同”，所以 B 错误；③ 因为负值是合法解（只需把箭头掉转），不代表算错，更不代表电流为 0，所以 C、D 均错。【答案】实际方向与参考方向相反。【易错】×1 认为算出负值就是算错了，盲目改符号凑正；×2 把参考方向当成实际方向，负号无法解释；×3 认为负电流等于没有电流。【口诀】算正同向算负反，参考方向只是担；负号不是错误号，掉转箭头就圆满。","steps":["【秒懂考点】负=实际相反","【第一步】非算错","【答案】实际方向与参考方向相反"],"pitfalls":["负号非算错"]});
  window.STUDY_DATA.questions.push({"id":"ne1601","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"负载","type":"single","typeLabel":"单选","stem":"负载的作用是（　）","options":["把电能转换成其他形式能量","把其他形式能量转换成电能","产生电能","提供电压"],"answer":"把电能转换成其他形式能量","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","负载"],"analysis":"【审题】问负载的作用，与电源作用成对：负载把电能转换成其他形式能量（热、光、机械等）。【定律/公式】负载是消耗电能的装置，实现电能→其他形式能量的转换，如电阻（电能→热能）、电动机（电能→机械能）、灯泡（电能→光能+热能）。【步骤】① 因为负载在电路中吸收电能并转化为所需能量形式，所以 A 正确；② 因为“把其他形式能量转换成电能”是电源的作用，所以 B 错误；③ 因为“产生电能”是电源功能、“提供电压”也是电源（或信号源）的作用，所以 C、D 均错。【答案】把电能转换成其他形式能量。【易错】×1 与电源能量转换方向记反；×2 认为负载提供电压（是电源提供）；×3 把负载说成“消耗电流”（消耗的是能量/功率，不是电流本身）。【口诀】负载耗电转热光，电源供电转电能；方向相反要记牢，一个给来一个用。","steps":["【秒懂考点】负载电能转其他","【第一步】电源相反","【答案】把电能转换成其他形式能量"],"pitfalls":["负载转其他，电源转电能"]});
  window.STUDY_DATA.questions.push({"id":"ne1602","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电流单位换算","type":"single","typeLabel":"单选","stem":"1mA等于多少A？（　）","options":["0.001A","0.01A","1000A","0.1A"],"answer":"0.001A","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","单位"],"analysis":"【审题】问电流单位换算：1 mA 等于多少 A，考查毫安与安培的进率。【定律/公式】1 A=1000 mA，1 mA=10⁻³ A=0.001 A。词头 m（毫）表示 10⁻³。【步骤】① 因为毫是 10⁻³ 的词头，所以 1 mA=1×10⁻³ A=0.001 A，A 正确；② 因为 0.01 A 是 10 mA、0.1 A 是 100 mA，进率用错，所以 B、D 错误；③ 因为 1000 A 是把方向弄反（1 A=1000 mA），所以 C 错误。【答案】0.001A。【易错】×1 把进率记成 100（应为 1000）；×2 把毫当成 10⁻²，得 0.01 A；×3 方向弄反写成 1000 A。【口诀】毫安千分是一安，三零后退小数点；微安又是毫安千，方向千万别搞反。","steps":["【秒懂考点】1mA=0.001","【第一步】毫是千分之一","【答案】0.001A"],"pitfalls":["1mA=0.001"]});
  window.STUDY_DATA.questions.push({"id":"ne1604","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电位","type":"single","typeLabel":"单选","stem":"参考点电位是（　）","options":["0V","1V","5V","不确定"],"answer":"0V","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","电位"],"analysis":"【审题】问参考点（零电位点）的电位是多少，考查电位的相对性：参考点电位人为规定为 0。【定律/公式】电位是相对量，必须选参考点（接地符号或公共端），规定参考点电位 φ=0；其他点电位等于该点到参考点的电压。【步骤】① 因为电位是相对参考点定义的，参考点本身电位规定为零，所以 A 正确；② 因为 1 V、5 V 是其他点的电位取值可能值，不是参考点的定义值，所以 B、C 错误；③ 因为参考点电位是“人为规定为 0”，不是“不确定”，所以 D 错误。【答案】0V。【易错】×1 认为参考点电位不确定或可以随便不为 0；×2 把电位与电压混淆（电压是两点电位之差）；×3 换参考点后仍用旧电位数值，忘记所有电位都要重新算。【口诀】参考电位规定零，电位相对才有名；换点要重标电位，两点之差才是压。","steps":["【秒懂考点】参考点0","【第一步】地电位","【答案】0V"],"pitfalls":["0V"]});
  window.STUDY_DATA.questions.push({"id":"nee10","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"并联电阻","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"两个 10Ω 电阻并联，等效电阻是（　）","options":["5Ω","10Ω","20Ω","40Ω"],"answer":"5Ω","analysis":"【审题】两个 10 Ω 电阻并联，求等效电阻，是并联公式基本计算。【定律/公式】并联电阻：1/R=1/R1+1/R2；两电阻并联特例 R=R1R2/(R1+R2)；n 个相同电阻 R0 并联为 R0/n。【步骤】① 因为两电阻并联，用特例公式 R=10×10/(10+10)=100/20=5 Ω；② 因为相同电阻并联总阻等于单个除以个数，10/2=5 Ω，结果一致；③ 因为 10 Ω 是没算并联、20 Ω 是误当串联相加、40 Ω 无依据，所以只有 5 Ω 正确。【答案】5Ω。【易错】×1 误用串联相加得 20 Ω；×2 忘记并联总阻变小，仍填 10 Ω；×3 用 1/R1+1/R2=0.2 后忘记再取倒数，答 0.2 Ω。【口诀】并联倒数再倒回，两同相并除以二；十欧并联得五欧，串大并小反着背。","source":"2027考纲补充","tags":["并联电阻","考纲补充"],"steps":["【秒懂考点】两10并=5","【第一步】减半","【答案】5Ω"],"pitfalls":["并联5"]});
  window.STUDY_DATA.questions.push({"id":"nee18","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电能","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"1 度电 =（　）","options":["1 瓦·时","1 千瓦·时","1 焦耳","1 瓦·秒"],"answer":"1 千瓦·时","analysis":"【审题】问 1 度电等于什么，与前面“1 度”题同考点，选项设瓦时、千瓦时、焦耳、瓦秒干扰。【定律/公式】1 度=1 kW·h（千瓦时）=3.6×10⁶ J。1 瓦·时=3600 J，1 瓦·秒=1 J，都远小于 1 度。【步骤】① 因为“度”是千瓦时的俗称，表示 1 kW 用 1 h 消耗的电能，所以 B 正确；② 因为 1 瓦·时只是 3600 J，不是 1 度，所以 A 错误；③ 因为 1 焦耳=1 瓦·秒，能量极小，所以 C、D 错误。【答案】1 千瓦·时。【易错】×1 把度当成瓦时（差 1000 倍）；×2 把度当成焦耳或瓦秒；×3 把千瓦时当成功率单位（它是能量）。【口诀】一度就是千瓦时，不是瓦时差千倍；焦耳瓦秒太渺小，电能常用千瓦时。","source":"2027考纲补充","tags":["电能","考纲补充"],"steps":["【秒懂考点】1度=1千瓦时","【第一步】3.6×10⁶J","【答案】1 千瓦·时"],"pitfalls":["1kWh=3.6×10⁶J"]});
  window.STUDY_DATA.questions.push({"id":"nee2","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电压","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"电压的单位是（　）","options":["伏特","安培","欧姆","瓦特"],"answer":"伏特","analysis":"【审题】问电压的单位，单位识记题，与安培、欧姆、瓦特区分。【定律/公式】电压单位伏特 V；电流安培 A；电阻欧姆 Ω；功率瓦特 W。【步骤】① 因为电压（电位差）的国际单位是伏特，所以 A 正确；② 因为安培是电流单位，所以 B 错误；③ 因为欧姆是电阻单位、瓦特是功率单位，所以 C、D 错误。【答案】伏特。【易错】×1 把安培误当电压单位；×2 把瓦特误当电压单位；×3 与电位单位混淆（电位单位也是 V，但电位是相对量）。【口诀】电压单位是伏特，安培欧姆瓦特错；压流阻功四单位，V A Ω W 要记着。","source":"2027考纲补充","tags":["电压","考纲补充"],"steps":["【秒懂考点】电压伏特","【第一步】V","【答案】伏特"],"pitfalls":["电压V"]});
  window.STUDY_DATA.questions.push({"id":"nee201","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电流方向","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"电路中电流的实际方向规定为（　）","options":["正电荷运动方向","负电荷运动方向","电子运动方向","任意方向"],"answer":"正电荷运动方向","analysis":"【审题】问电流“实际方向”的规定，与参考方向题对照：实际方向规定为正电荷运动方向。【定律/公式】电流实际方向的物理规定：正电荷定向移动的方向；金属导体中与自由电子运动方向相反。【步骤】① 因为物理学规定正电荷运动方向为电流方向，所以 A 正确；② 因为负电荷、电子运动方向与电流方向相反，所以 B、C 错误；③ 因为电流方向有客观规定，“任意方向”只是参考方向可假定，所以 D 错误。【答案】正电荷运动方向。【易错】×1 把电子运动方向当成电流实际方向；×2 把参考方向（可假定）与实际方向（物理规定）混淆；×3 把电压方向规定套到电流上。【口诀】电流实际正电荷，电子相反要记得；参考方向可假定，实际方向定死的。","source":"2027考纲补充","tags":["电流方向","考纲补充"],"steps":["【秒懂考点】电流方向=正电荷运动","【第一步】电子反向移动","【答案】正电荷运动方向"],"pitfalls":["电流方向与电子运动相反"]});
  window.STUDY_DATA.questions.push({"id":"nee202","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电压方向","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"电压的实际方向是（　）","options":["高电位指向低电位","低电位指向高电位","任意","与电流无关"],"answer":"高电位指向低电位","analysis":"【审题】问电压的实际方向，与电流实际方向成对考查：电压方向是高电位指向低电位。【定律/公式】电压实际方向规定为电位降低方向，即从高电位指向低电位；Uab>0 时 a 高 b 低。【步骤】① 因为电压是电位差，方向为电位降落方向，所以 A 正确；② 因为低到高是电位升高，不是电压方向，所以 B 错误；③ 因为电压方向有明确规定，不是任意，且与电流在关联方向下有约束关系，所以 C、D 错误。【答案】高电位指向低电位。【易错】×1 记成低指向高；×2 与电动势方向（电源内部低到高）混淆；×3 认为电压方向可以任意（参考方向可假定，但实际方向是高到低）。【口诀】电压实际高到低，电位降落是真意；电源内部电动势，低到高来要牢记。","source":"2027考纲补充","tags":["电压方向","考纲补充"],"steps":["【秒懂考点】电压高→低","【第一步】电位降方向","【第二步】低到高是电动势","【答案】高电位指向低电位"],"pitfalls":["外电路电压高到低"]});
  window.STUDY_DATA.questions.push({"id":"nee213","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电池串联","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"两节 1.5V 电池串联总电压是（　）","options":["1.5V","3V","0.75V","6V"],"answer":"3V","analysis":"【审题】两节 1.5 V 电池串联，求总电压，考查电池串联电压相加。【定律/公式】电池串联：U总=U1+U2+…+Un（同向串联）。两节 1.5 V 串联得 3 V。【步骤】① 因为串联电池电动势相加，所以 U=1.5+1.5=3 V；② 因为 1.5 V 是单节电压、0.75 V 是误除以 2，所以 A、C 错误；③ 因为 6 V 是 4 节 1.5 V 或误乘，两节串联不会到 6 V，所以 D 错误，正确为 3 V。【答案】3V。【易错】×1 与并联混淆（并联同压不变）；×2 误除 2 得 0.75 V；×3 电池反向串联时电压相减，但本题默认同向相加。【口诀】电池串联压相加，两节一点五变三；并联同压不改变，方向相反要相减。","source":"2027考纲补充","tags":["电池串联","考纲补充"],"steps":["【秒懂考点】串联电池相加","【第一步】1.5+1.5=3V","【第二步】并联才不变","【答案】3V"],"pitfalls":["串联增压、并联增容"]});
  window.STUDY_DATA.questions.push({"id":"nee214","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电池并联","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"两节 1.5V 同电压电池并联总电压是（　）","options":["1.5V","3V","0.75V","6V"],"answer":"1.5V","analysis":"【审题】两节 1.5 V 同电压电池并联，求总电压，与串联题对照：并联电压不变。【定律/公式】同电压电池并联：U总=U1=U2=1.5 V（容量增加，电压不变）。前提是电压相等且同极性并联。【步骤】① 因为并联各支路电压相等，同压电池并联后端电压仍等于单节电压，所以 U=1.5 V；② 因为 3 V 是串联结果，所以 B 错误；③ 因为 0.75 V、6 V 都不是并联规律，所以 C、D 错误，选 A。【答案】1.5V。【易错】×1 与串联相加混淆得 3 V；×2 误除 2 得 0.75 V；×3 不同电压电池直接并联会环流，题目默认同压才成立。【口诀】同压并联压不变，串联才把电压翻；容量增加是好处，不同电压不能连。","source":"2027考纲补充","tags":["电池并联","考纲补充"],"steps":["【秒懂考点】同电压并联不变","【第一步】电压1.5V、容量增","【第二步】3V是串联","【答案】1.5V"],"pitfalls":["并联电压不变、串联相加"]});
  window.STUDY_DATA.questions.push({"id":"nee215","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"交流电","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"我国民用照明电压有效值是（　）","options":["110V","220V","380V","36V"],"answer":"220V","analysis":"【审题】问我国民用照明电压有效值，属于交流电常识：单相 220 V、三相线电压 380 V。【定律/公式】我国民用单相交流电：相电压有效值 220 V、频率 50 Hz；三相线电压 380 V=220×√3。安全电压一般不超 36 V。【步骤】① 因为我国家用照明采用单相 220 V 交流有效值，所以 B 正确；② 因为 110 V 是部分国家（如日本、美国部分）民用电压，所以 A 错误；③ 因为 380 V 是三相线电压、36 V 是安全电压上限，所以 C、D 错误。【答案】220V。【易错】×1 与三相线电压 380 V 混淆；×2 与安全电压 36 V 混淆；×3 把有效值与峰值搞混（220 V 有效值峰值约 311 V）。【口诀】民用电压二百二，三相线压三百八；安全不超三十六，有效峰值差根二。","source":"2027考纲补充","tags":["交流电","考纲补充"],"steps":["【秒懂考点】照明220V","【第一步】220V 50Hz","【第二步】380三相、110他国","【答案】220V"],"pitfalls":["220照明380动力36安全"]});
  window.STUDY_DATA.questions.push({"id":"nee216","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"安全电压","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"我国规定安全电压上限是（　）","options":["12V","24V","36V","220V"],"answer":"36V","analysis":"【审题】问我国规定的安全电压上限，属于安全用电常识，常见等级 36 V、24 V、12 V、6 V，上限是 36 V。【定律/公式】我国安全电压额定值等级：42 V、36 V、24 V、12 V、6 V；一般环境安全电压上限为 36 V（潮湿/金属容器内更低，12 V 或 6 V）。【步骤】① 因为国家标准规定安全电压上限（一般场所）为 36 V，所以 C 正确；② 因为 12 V、24 V 是更严格环境下的安全电压等级，不是上限，所以 A、B 错误；③ 因为 220 V 是民用相电压，远超安全电压，所以 D 错误。【答案】36V。【易错】×1 把 12 V 或 24 V 当成上限（那是特殊场所等级）；×2 把 220 V 当安全电压；×3 把安全电压与“对人体无害”绝对化，湿手、大电流时 36 V 仍有风险。【口诀】安全电压三十六，潮湿金属十二伏；等级四二三六廿，十二六伏更严处。","source":"2027考纲补充","tags":["安全电压","考纲补充"],"steps":["【秒懂考点】安全电压上限36","【第一步】额定值42/36/24/12/6","【第二步】潮湿用更低","【答案】36V"],"pitfalls":["潮湿用12或24更低"]});
  window.STUDY_DATA.questions.push({"id":"nee240","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"数字电路","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"二进制 1010 转十进制是（　）","options":["10","12","8","14"],"answer":"10","analysis":"【审题】二进制 1010 转十进制，按权展开求和。【定律/公式】二转十：按位权展开，(1010)₂=1×2³+0×2²+1×2¹+0×2⁰。【步骤】① 因为从右到左位权是 2⁰、2¹、2²、2³，所以 1010=1×8+0×4+1×2+0×1；② 因为 8+0+2+0=10，所以十进制为 10；③ 因为 12 是误加 4、8 是漏算 2¹ 位、14 是位权用错，所以 A 正确。【答案】10。【易错】×1 位权从左到右当 2⁰ 起算；×2 中间 0 位漏处理或误加 4；×3 与十进制数字直接对照（1010 不是“一千零一十”）。【口诀】二转十按权展开，八四二一挨个乘；一零一零得一十，位权顺序右到左。","source":"2027考纲补充","tags":["数字电路","考纲补充"],"steps":["【秒懂考点】1010按权展开","【第一步】8+2=10","【答案】10"],"pitfalls":["最左最高位"]});
  window.STUDY_DATA.questions.push({"id":"nee241","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"数字电路","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"十进制 13 转二进制是（　）","options":["1101","1011","1110","1001"],"answer":"1101","analysis":"【审题】十进制 13 转二进制，用除 2 取余逆序，或凑 8+4+1。【定律/公式】十转二：除 2 取余、逆序排列。13=8+4+1=2³+2²+2⁰，对应 1101。【步骤】① 因为 13÷2 余 1、6÷2 余 0、3÷2 余 1、1÷2 余 1，余数逆序 1101；② 因为 13=1101B（8+4+1），验证正确；③ 因为 1011=11、1110=14、1001=9，都不等于 13，所以 A 正确。【答案】1101。【易错】×1 余数顺序写反得 1011；×2 漏掉 2⁰ 位写成 1100；×3 用除 2 取商而不是余数。【口诀】十转二除二取余，余数倒序拼起来；十三就是幺幺零幺，八四一凑最痛快。","source":"2027考纲补充","tags":["数字电路","考纲补充"],"steps":["【秒懂考点】13=8+4+1=1101","【第一步】验证1101=13","【答案】1101"],"pitfalls":["13是1101不是1011"]});
  window.STUDY_DATA.questions.push({"id":"nee242","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"数字电路","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"十六进制 A 对应十进制（　）","options":["10","11","15","9"],"answer":"10","analysis":"【审题】十六进制 A 对应十进制多少，考查十六进制数码 A~F 的含义。【定律/公式】十六进制数码：0-9 对应 0-9，A=10，B=11，C=12，D=13，E=14，F=15。【步骤】① 因为十六进制用 A 表示 10，所以 A=10，A 正确；② 因为 B=11、F=15，所以 B、C 对应的是其他字母；③ 因为 9 就是数码 9，不是 A，所以 D 错误。【答案】10。【易错】×1 把 A 当成 11 或 15；×2 与字母序号从 0 数（A 若是第 11 个易误判）；×3 与二进制 1010 混淆（1010₂=10=A₁₆）。【口诀】十六进制 A 是十，B 十一 C 十二；D 十三 E 十四，F 十五要记齐。","source":"2027考纲补充","tags":["数字电路","考纲补充"],"steps":["【秒懂考点】A=10","【第一步】A-F表10-15","【答案】10"],"pitfalls":["A=10 F=15"]});
  window.STUDY_DATA.questions.push({"id":"nee257","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"正弦量","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"正弦量的三要素不包括（　）","options":["有效值","最大值","角频率","初相位"],"answer":"有效值","analysis":"【审题】问正弦量三要素“不包括”哪一项，三要素是最大值、角频率、初相位，有效值是由最大值导出的量，不在三要素内。【定律/公式】正弦量 u=Um sin(ωt+ψ)：三要素为最大值 Um、角频率 ω（或频率 f）、初相位 ψ。有效值 U=Um/√2，是派生量。【步骤】① 因为三要素完整描述正弦波形，是 Um、ω、ψ，所以 B、C、D 都是三要素；② 因为有效值 U=Um/√2，可由最大值算出，不是独立要素，所以 A 不包括；③ 因为题目问“不包括”，所以选 A。【答案】有效值。【易错】×1 把有效值当成三要素（把最大值漏掉）；×2 把初相位漏掉，把频率与角频率重复计两个要素；×3 看成选“包括”而答错。【口诀】三要素压最大值，角频初相要记齐；有效压除根号二，派生量来不是一。","source":"2027考纲补充","tags":["正弦量","考纲补充"],"steps":["【秒懂考点】三要素不含有效值","【第一步】最大值、角频率、初相","【第二步】有效值可换算","【答案】有效值"],"pitfalls":["三要素幅值、角频率、初相"]});
  window.STUDY_DATA.questions.push({"id":"nee265","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"二极管","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"硅二极管正向导通时正向压降约（　）","options":["0.7V","0.3V","1V","0V"],"answer":"0.7V","analysis":"【审题】问硅二极管正向导通压降约为多少，器件参数识记：硅约 0.7 V，锗约 0.3 V。【定律/公式】硅 PN 结正向导通压降约 0.6~0.8 V，取 0.7 V；锗管约 0.2~0.3 V。死区电压硅约 0.5 V。【步骤】① 因为硅材料 PN 结导通后正向压降典型值 0.7 V，所以 A 正确；② 因为 0.3 V 是锗管压降，所以 B 错误；③ 因为 1 V 偏大、0 V 是理想二极管模型（导通短路），所以 C、D 错误。【答案】0.7V。【易错】×1 与锗管 0.3 V 记混；×2 用理想模型 0 V 当实际压降；×3 把死区电压 0.5 V 当成导通压降。【口诀】硅管压降约七伏，锗管三伏要记住；理想二极管当零伏，死区硅管五伏处。","source":"2027考纲补充","tags":["二极管","考纲补充"],"steps":["【秒懂考点】硅管0.7V","【第一步】锗0.3","【答案】0.7V"],"pitfalls":["硅0.7锗0.3"]});
  window.STUDY_DATA.questions.push({"id":"nee271","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"逻辑代数","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"A·A=（　）","options":["A","0","1","2A"],"answer":"A","analysis":"【审题】逻辑代数运算 A·A=？考查逻辑与的重叠律（吸收/幂等）。【定律/公式】逻辑与：A·A=A（幂等律）；A·0=0；A·1=A；A·Ā=0。注意不是算术 2A。【步骤】① 因为逻辑与表示“全 1 出 1”，A 与 A 是同一变量，结果仍是 A，所以 A·A=A；② 因为 0 是 A·Ā 或 A·0 的结果，1 是 A+Ā 或 A·1 不对应，所以 B、C 错误；③ 因为 2A 是算术乘法思维，逻辑变量取值只有 0/1，没有 2A，所以 D 错误。【答案】A。【易错】×1 按算术算成 2A 或 A²；×2 与 A·Ā=0 混淆；×3 与 A+A 混淆（结果也是 A，但原理是或）。【口诀】逻辑与乘幂等律，A 乘 A 还是 A；不是算术得 A 方，A 乘非 A 才是零。","source":"2027考纲补充","tags":["逻辑代数","考纲补充"],"steps":["【秒懂考点】A·A=A","【第一步】重叠律","【答案】A"],"pitfalls":["A·A=A"]});
  window.STUDY_DATA.questions.push({"id":"nee272","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"逻辑代数","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"A+A=（　）","options":["A","0","1","2A"],"answer":"A","analysis":"【审题】逻辑代数 A+A=？考查逻辑或的幂等律。【定律/公式】逻辑或：A+A=A（幂等律）；A+0=A；A+1=1；A+Ā=1。注意不是算术 2A。【步骤】① 因为逻辑或表示“有 1 出 1”，A 或 A 仍是 A，所以 A+A=A；② 因为 0 是 A·Ā 或 A·0，1 是 A+Ā 或 A+1，所以 B、C 不对应该式；③ 因为 2A 是算术加法，逻辑或不产生系数，所以 D 错误。【答案】A。【易错】×1 算术思维写成 2A；×2 与 A+Ā=1 混淆；×3 与 A·A 混淆（结果同为 A，但一个是或、一个是与）。【口诀】逻辑或加幂等律，A 加 A 还是 A；A 加非 A 才得一，算术二 A 不成立。","source":"2027考纲补充","tags":["逻辑代数","考纲补充"],"steps":["【秒懂考点】A+A=A","【第一步】不进位","【答案】A"],"pitfalls":["A+A=A不进位"]});
  window.STUDY_DATA.questions.push({"id":"nee282","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"串联电池","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"3 节 1.5V 电池串联电压？","options":["1.5V","3V","4.5V","0.5V"],"answer":"4.5V","analysis":"【审题】3 节 1.5 V 电池串联求总电压，串联电压相加。【定律/公式】串联电池 U总=n×U单（同向），3×1.5=4.5 V。【步骤】① 因为串联电动势相加，所以 U=1.5+1.5+1.5=4.5 V；② 因为 1.5 V 是单节、3 V 是两节、0.5 V 是误除，所以 A、B、D 错误；③ 因为 3 节串联应为 4.5 V，所以 C 正确。【答案】4.5V。【易错】×1 按并联算电压不变 1.5 V；×2 只加两节得 3 V；×3 误除以节数得 0.5 V。【口诀】三节一点五串联，四点五伏是总压；串联相加并联同，方向同向才可加。","source":"2027考纲补充","tags":["串联电池","考纲补充"],"steps":["【秒懂考点】1.5×3=4.5","【第一步】串联增压","【答案】4.5V"],"pitfalls":["串联增压"]});
  window.STUDY_DATA.questions.push({"id":"nee288","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"逻辑门","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"与门输入全 1，输出（　）","options":["0","1","不确定","高阻"],"answer":"1","analysis":"【审题】与门输入全 1 时输出是多少，考查与门真值表：全 1 出 1，有 0 出 0。【定律/公式】与运算 Y=A·B（多输入类似）：输入全为 1 时 Y=1；任一输入为 0 则 Y=0。【步骤】① 因为与门逻辑是“全 1 出 1”，输入全 1 满足条件，所以输出 1；② 因为 0 是“有 0 出 0”的情况，所以 A 错误；③ 因为与门输出确定，不高阻、不不确定，所以 C、D 错误。【答案】1。【易错】×1 与或门“有 1 出 1”混淆后仍答对，但原理不清；×2 与非门输出记反（全 1 时与非出 0）；×3 把高阻态当成与门输出（那是三态门）。【口诀】与门全一方出一，有零出零要牢记；或门有 1 就出 1，非门取反最省事。","source":"2027考纲补充","tags":["逻辑门","考纲补充"],"steps":["【秒懂考点】与全1出1","【第一步】有0则0","【答案】1"],"pitfalls":["与门全1才1"]});
  window.STUDY_DATA.questions.push({"id":"nee289","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"逻辑门","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"或门输入全 0，输出（　）","options":["0","1","不确定","高阻"],"answer":"0","analysis":"【审题】或门输入全 0 时输出多少，考查或门真值表：全 0 出 0，有 1 出 1。【定律/公式】或运算 Y=A+B：输入全 0 时 Y=0；任一输入为 1 则 Y=1。【步骤】① 因为或门“全 0 出 0”，输入全 0 满足，所以输出 0；② 因为 1 是“有 1 出 1”的情况，所以 B 错误；③ 因为或门输出确定，不是高阻或不确定，所以 C、D 错误。【答案】0。【易错】×1 与与门“全 1 出 1”记混后误答 1；×2 与或非门混淆（全 0 时或非出 1）；×3 把高阻态当成或门输出。【口诀】或门全零才出零，有 1 就出 1 记清；与门全一方出一，两表对照最分明。","source":"2027考纲补充","tags":["逻辑门","考纲补充"],"steps":["【秒懂考点】或全0出0","【第一步】有1则1","【答案】0"],"pitfalls":["或门有1才1"]});
  window.STUDY_DATA.questions.push({"id":"nee312","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"二极管","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"二极管反向偏置时（　）","options":["截止","导通","击穿","放大"],"answer":"截止","analysis":"【审题】二极管反向偏置时处于什么状态，考查单向导电性：反偏截止（未击穿时）。【定律/公式】二极管正偏导通（硅约 0.7 V），反偏截止（反向电流很小）；反向电压超击穿电压才击穿。放大是三极管状态。【步骤】① 因为反向偏置时 PN 结内电场增强，多子扩散被阻挡，只有微小漂移电流，所以截止；② 因为导通是正偏状态，所以 B 错误；③ 因为击穿需反向电压超击穿电压、放大是三极管在放大区的状态，所以 C、D 不是反偏的一般状态。【答案】截止。【易错】×1 认为反偏就击穿（需超过击穿电压）；×2 与正偏导通记反；×3 把三极管“放大”概念套到二极管上。【口诀】正偏导通反偏截，击穿要超反向压；二极管不放大，单向导电是根本。","source":"2027考纲补充","tags":["二极管","考纲补充"],"steps":["【秒懂考点】反偏截止","【第一步】正偏导通","【答案】截止"],"pitfalls":["正偏导通反偏截止"]});
  window.STUDY_DATA.questions.push({"id":"nee318","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"逻辑门","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"与门 1·0=？","options":["0","1","10","01"],"answer":"0","analysis":"【审题】与门 1·0=？逻辑与运算基本真值。【定律/公式】与运算：1·0=0（有 0 出 0）。【步骤】① 因为与运算要求全 1 才出 1，1 与 0 中有 0，所以结果为 0；② 因为 1 是全 1 才成立，所以 B 错误；③ 因为 10、01 是把两输入拼起来当数，逻辑运算只取 0/1 单值，所以 C、D 错误。【答案】0。【易错】×1 按算术乘法其实 1×0 也=0，但原理要记逻辑“有 0 出 0”；×2 与或运算 1+0=1 混淆；×3 把输入拼成 10 或 01 当结果。【口诀】与门有零就出零，一与零来是零；全 1 出 1 要记准，算术巧合莫当真。","source":"2027考纲补充","tags":["逻辑门","考纲补充"],"steps":["【秒懂考点】1·0=0","【第一步】有0出0","【答案】0"],"pitfalls":["全1才1"]});
  window.STUDY_DATA.questions.push({"id":"nee319","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"逻辑门","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"或门 1+0=？","options":["0","1","10","01"],"answer":"1","analysis":"【审题】或门 1+0=？逻辑或运算基本真值。【定律/公式】或运算：1+0=1（有 1 出 1）。【步骤】① 因为或运算有 1 出 1，1 或 0 含有 1，所以结果为 1；② 因为 0 是全 0 才成立，所以 A 错误；③ 因为 10、01 不是逻辑结果，所以 C、D 错误。【答案】1。【易错】×1 与与运算 1·0=0 混淆；×2 按算术想成 1（结果虽同但逻辑是“有 1 出 1”）；×3 把或非门结果当或门（或非 1+0=0）。【口诀】或门有 1 就出 1，一或零来是一；全零出零要记清，或非取反记在心。","source":"2027考纲补充","tags":["逻辑门","考纲补充"],"steps":["【秒懂考点】1+0=1","【第一步】有1出1","【答案】1"],"pitfalls":["全0才0"]});
  window.STUDY_DATA.questions.push({"id":"nee32","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"功率","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"一个 100W 灯泡正常工作 10 小时耗电（　）","options":["1 度","10 度","0.1 度","100 度"],"answer":"1 度","analysis":"【审题】100 W 灯泡工作 10 小时耗电多少度，电能计算 W=Pt，再换算千瓦时。【定律/公式】W=Pt；100 W=0.1 kW；t=10 h；W=0.1×10=1 kW·h=1 度。【步骤】① 因为 W=Pt，先把功率化成千瓦 100 W=0.1 kW；② 因为时间 10 h，所以 W=0.1 kW×10 h=1 kW·h=1 度；③ 因为 10 度是忘了把 W 化 kW、0.1 度是时间或功率弄错、100 度数值无依据，所以 A 正确。【答案】1 度。【易错】×1 功率不化千瓦，算成 100×10=1000（度）；×2 把 10 小时当成 1 小时得 0.1 度；×3 把 W 与 kW 进率弄反。【口诀】百度十时算电能，化成千瓦零点一；乘十正好一度电，千瓦乘时是度能。","source":"2027考纲补充","tags":["功率","考纲补充"],"steps":["【秒懂考点】0.1×10=1","【第一步】100W=0.1kW","【答案】1 度"],"pitfalls":["1度"]});
  window.STUDY_DATA.questions.push({"id":"nee331","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"逻辑代数","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"A+1=？","options":["0","1","A","A̅"],"answer":"1","analysis":"【审题】逻辑代数 A+1=？考查或运算的支配律（0-1 律）。【定律/公式】A+1=1（有 1 出 1，结果恒 1）；A+0=A；A·0=0；A·1=A。【步骤】① 因为或运算有 1 出 1，A 与 1 相或必有 1，所以结果恒为 1；② 因为 0 不可能、A 是 A+0 的结果，所以 A、C 错误；③ 因为 Ā 是非运算结果，不是 A+1，所以 D 错误。【答案】1。【易错】×1 与 A+0=A 混淆；×2 与 A·1=A 混淆；×3 按算术想成 A+1。【口诀】A 加一来恒为一，有 1 出 1 不必疑；A 加零来才是 A，与乘一来也是 A。","source":"2027考纲补充","tags":["逻辑代数","考纲补充"],"steps":["【秒懂考点】A+1=1","【第一步】有1出1","【答案】1"],"pitfalls":["A+1=1"]});
  window.STUDY_DATA.questions.push({"id":"nee332","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"逻辑代数","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"A·1=？","options":["0","1","A","A̅"],"answer":"A","analysis":"【审题】逻辑代数 A·1=？考查与运算的单位元性质。【定律/公式】A·1=A（全 1 才出，1 不改变 A）；A·0=0；A+A=A；A+Ā=1。【步骤】① 因为与运算全 1 出 1、有 0 出 0，A 与 1 相与时结果跟 A 走，所以 A·1=A；② 因为 0 是 A·0 的结果，所以 A 错误；③ 因为 1 是 A+1 或 A+Ā 的结果，Ā 是非，所以 B、D 错误。【答案】A。【易错】×1 与 A·0=0 混淆；×2 与 A+1=1 混淆；×3 按算术想成 A。【口诀】A 乘一来仍是 A，与一相与不变它；A 乘零来才是零，混淆口诀易出岔。","source":"2027考纲补充","tags":["逻辑代数","考纲补充"],"steps":["【秒懂考点】A·1=A","【第一步】乘1不变","【答案】A"],"pitfalls":["A·1=A"]});
  window.STUDY_DATA.questions.push({"id":"nee34","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"万用表","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"用万用表测电压时，表笔应（　）在被测电路中。","options":["串联","并联","混联","短接"],"answer":"并联","analysis":"【审题】万用表测电压时表笔接法，与测电流对照：电压表并联在被测两端。【定律/公式】电压表内阻很大，应与被测元件并联，测两点电位差；电流表才串联。【步骤】① 因为电压表测两点间电压，必须并联在被测电路两端，所以 B 正确；② 因为串联是电流表接法，所以 A 错误；③ 因为混联、短接都不是电压测量接法（短接会造成短路），所以 C、D 错误。【答案】并联。【易错】×1 与电流表串联接法混淆；×2 测电压时误把表串入电路，读数不准且影响电路；×3 量程选错或直流档位极性接反。【口诀】测压并联测流串，表笔跨接两端点；红高黑低极性正，量程先大再减小。","source":"2027考纲补充","tags":["万用表","考纲补充"],"steps":["【秒懂考点】测电压并联","【第一步】测电流串","【答案】并联"],"pitfalls":["电压并电流串"]});
  window.STUDY_DATA.questions.push({"id":"ne10001","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-10","knowledgePoint":"触发器","type":"single","typeLabel":"单选","stem":"需要时钟触发的触发器是（　）","options":["同步RS触发器","基本RS触发器","以上都是","都不是"],"answer":"同步RS触发器","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["时序逻辑","触发器"],"analysis":"【审题】问“需要时钟触发”的触发器是哪一个，区分同步 RS 触发器与基本 RS 触发器。【定律/公式】基本 RS 触发器：由 R、S 直接置位复位，无时钟；同步（钟控）RS 触发器：在 CP 有效时才动作，需要时钟。【步骤】① 因为同步 RS 触发器增加了时钟控制端 CP，只有时钟有效沿/电平才接受 R、S，所以 A 正确；② 因为基本 RS 触发器无时钟、随时响应 R、S，所以 B 不需要时钟；③ 因为“以上都是”不成立（基本 RS 不需要），“都不是”也错，所以选 A。【答案】同步RS触发器。【易错】×1 把基本 RS 当成也有时钟；×2 把“同步”理解成其他意思，忽略钟控含义；×3 与主从/边沿触发器的时钟要求混淆。【口诀】同步 RS 带时钟，CP 有效才动作；基本 RS 无钟控，置位复位随时通。","steps":["【秒懂考点】同步RS需时钟","【第一步】基本RS不需","【答案】同步RS触发器"],"pitfalls":["同步需时钟"]});
  window.STUDY_DATA.questions.push({"id":"ne10301","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-10","knowledgePoint":"时序电路特点","type":"single","typeLabel":"单选","stem":"时序逻辑电路的输出取决于（　）","options":["当前输入","原来状态","当前输入和原来状态","电源电压"],"answer":"当前输入和原来状态","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["时序逻辑","特点"],"analysis":"【审题】问时序逻辑电路的输出取决于什么，与组合逻辑对比：时序输出=当前输入+原来状态。【定律/公式】组合逻辑：输出只取决于当前输入；时序逻辑：输出取决于当前输入和电路原来状态（记忆性），状态存于触发器。【步骤】① 因为时序电路含存储元件（触发器），状态会保留到下一时刻，所以输出由当前输入和原状态共同决定；② 因为只说“当前输入”是组合逻辑特点，所以 A 不完整；③ 因为只说“原来状态”漏了输入影响，“电源电压”不是逻辑决定因素，所以 B、D 错误。【答案】当前输入和原来状态。【易错】×1 与组合逻辑“只取决于当前输入”混淆；×2 认为时序只由原状态决定；×3 忽略记忆元件，把时序当组合分析。【口诀】时序输出两来源，当前输入加原态；组合只看输入现，触发器里把态带。","steps":["【秒懂考点】时序看输入+状态","【第一步】组合只当前","【答案】当前输入和原来状态"],"pitfalls":["输入+状态"]});
  window.STUDY_DATA.questions.push({"id":"ne10302","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-10","knowledgePoint":"寄存器","type":"single","typeLabel":"单选","stem":"寄存器的主要功能是（　）","options":["存储二进制代码","计数","译码","加法"],"answer":"存储二进制代码","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["时序逻辑","寄存器"],"analysis":"【审题】问寄存器的主要功能，属于数字电路部件功能识记：寄存器用于存放/存储二进制代码。【定律/公式】寄存器由触发器组成，n 位寄存器可存 n 位二进制数；主要功能是暂存数据/指令，不是计数、译码或运算。【步骤】① 因为寄存器的基本单元是触发器，每级存 1 位二进制，所以主要功能是存储二进制代码，A 正确；② 因为计数是计数器功能、译码是译码器功能，所以 B、C 错误；③ 因为加法是加法器/ALU 功能，所以 D 错误。【答案】存储二进制代码。【易错】×1 与计数器功能混淆（计数器也能存数但主要功能是计数）；×2 与译码器混淆；×3 认为寄存器能做算术运算（那是运算器）。【口诀】寄存器来存代码，触发器把位来包；计数译码加法器，各自功能别混淆。","steps":["【秒懂考点】寄存器存代码","【第一步】计数器计数","【答案】存储二进制代码"],"pitfalls":["存代码"]});
  window.STUDY_DATA.questions.push({"id":"ne10601","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-10","knowledgePoint":"寄存器分类","type":"single","typeLabel":"单选","stem":"移位寄存器可以（　）","options":["存放数据","移位","计数","译码"],"answer":"移位","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["时序逻辑","移位寄存器"],"analysis":"【审题】问移位寄存器“可以”做什么，选项有存放数据、移位、计数、译码，最特征的功能是移位（当然也能存数，但“可以”强调其特殊能力）。【定律/公式】移位寄存器：在时钟作用下数据可左移/右移，实现串并转换、移位运算；普通寄存器只能存放。【步骤】① 因为移位寄存器在普通寄存功能基础上增加移位能力，时钟脉冲使数据逐位移动，所以 B“移位”是其最特有功能；② 因为存放数据是所有寄存器共性，不是“移位”寄存器的区分点，所以 A 虽对但不特异；③ 因为计数、译码分别是计数器、译码器功能，所以 C、D 不选。【答案】移位。【易错】×1 只答存放数据，忽略“移位”关键词；×2 与计数器混淆（环形移位可构成计数器但功能不同）；×3 以为移位寄存器不能存数（它既能存又能移）。【口诀】移位寄存能左右，时钟一到数据走；普通只存不能移，串并转换靠它有。","steps":["【秒懂考点】移位寄存器移位","【第一步】串并转换","【答案】移位"],"pitfalls":["移位"]});
  window.STUDY_DATA.questions.push({"id":"ee06","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"节点 A 汇合三支路：I₁=3A 流入，I₂=2A 流入，I₃ 流出，则 I₃=（　）","options":["1 A","5 A","−1 A","6 A"],"answer":"5 A","pitfalls":["流入总和=流出总和"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】5 A 【考点】直流电路分析 【一步步怎么算】 ① 题目：节点 A 汇合三支路：I₁=3A 流入，I₂=2A 流入，I₃ 流出，则 I₃=（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KV","analysis":"【审题】节点 A 三支路：I₁=3 A 流入、I₂=2 A 流入、I₃ 流出，求 I₃，用基尔霍夫电流定律（KCL）。【定律/公式】KCL：任一节点，流入电流之和=流出电流之和；即 ΣI入=ΣI出，或 ΣI=0（流出取正）。【步骤】① 因为 KCL 规定节点电流守恒（电荷守恒），流入总和等于流出总和；② 因为 I₁、I₂ 流入，I₃ 流出，所以 I₃=I₁+I₂=3+2=5 A；③ 因为 1 A 是做了 3−2、−1 A 是符号约定混乱、6 A 是误乘，所以 B 正确。【答案】5 A。【易错】×1 做成流入相减 3−2=1 A；×2 把 I₃ 也当流入，方程列错得 −1 A 或符号反；×3 忘记“流入=流出”而直接加所有带符号电流。【口诀】KCL 节点流进等，流出等于入之和；三加二来等于五，电荷守恒不能破。","steps":["【秒懂考点】KCL：流入=流出","【第一步】流入 I₁+I₂=3+2=5A","【第二步】流出只有I₃，所以I₃=5A","【第三步】节点电流代数和为0：3+2-I₃=0","【答案】选5A"]});
  window.STUDY_DATA.questions.push({"id":"ee07","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"两电阻 R₁=4Ω、R₂=12Ω 并联，总电阻为（　）","options":["16 Ω","3 Ω","8 Ω","1.5 Ω"],"answer":"3 Ω","pitfalls":["乘积除以和；并联变小"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】3 Ω 【考点】直流电路分析 【一步步怎么算】 ① 题目：两电阻 R₁=4Ω、R₂=12Ω 并联，总电阻为（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（4）","analysis":"【审题】R₁=4 Ω、R₂=12 Ω 并联求总电阻，用并联公式计算。【定律/公式】并联：R=R₁R₂/(R₁+R₂)=4×12/(4+12)=48/16=3 Ω。【步骤】① 因为两电阻并联用积除以和，R=4×12/16=3 Ω；② 因为 16 Ω 是误用串联相加，所以 A 错误；③ 因为 8 Ω 是算术平均、1.5 Ω 是倒数和未取倒或算错，所以 C、D 错误。【答案】3 Ω。【易错】×1 误用串联 R₁+R₂=16 Ω；×2 用 (R₁+R₂)/2=8 Ω 当并联；×3 1/R=1/4+1/12=1/3 后忘记取倒数答 1/3 或弄成 1.5。【口诀】并联积除以和，四乘十二除十六；三欧正好是","steps":["【秒懂考点】并联电阻 R=R₁R₂/(R₁+R₂)","【第一步】R=4×12/(4+12)=48/16=3Ω","【第二步】并联总电阻比最小的还小（3<4）","【第三步】16Ω是串联结果，8Ω是并联公式错用","【答案】选3Ω"]});
  window.STUDY_DATA.questions.push({"id":"ee08","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"两电阻 R₁=4Ω、R₂=6Ω 串联接 10V 电源，R₁ 两端电压为（　）","options":["4 V","6 V","2.5 V","10 V"],"answer":"4 V","pitfalls":["串联电流相同；电阻大分压多"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】4 V 【考点】直流电路分析 【一步步怎么算】 ① 题目：两电阻 R₁=4Ω、R₂=6Ω 串联接 10V 电源，R₁ 两端电压为（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。","analysis":"【审题】R₁=4 Ω 与 R₂=6 Ω 串联接 10 V，求 R₁ 两端电压，用分压公式。【定律/公式】串联分压：U₁=U×R₁/(R₁+R₂)。【步骤】① 因为串联电流相同 I=U/(R₁+R₂)=10/10=1 A；② 因为 U₁=IR₁=1×4=4 V，或分压 U₁=10×4/10=4 V；③ 因为 6 V 是 R₂ 电压、2.5 V 误用并联分压、10 V 是总压，所以 A 正确。【答案】4 V。【易错】×1 求成 R₂ 电压 6 V；×2 用并联分压或比例颠倒；×3 忘记先求总电阻/电流。【口诀】串联分压阻成比，总阻十欧电流一；四欧压降四伏整，六欧分去六伏去。","steps":["【秒懂考点】串联分压，按电阻比例","【第一步】总电阻=4+6=10Ω，电流I=10/10=1A","【第二步】R₁电压=I×R₁=1×4=4V","【第三步】R₂=6V，4+6=10V，核对正确","【答案】选4V"]});
  window.STUDY_DATA.questions.push({"id":"ee09","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"基尔霍夫电压定律（KVL）的实质是（　）","options":["电荷守恒","能量守恒","动量守恒","质量守恒"],"answer":"能量守恒","pitfalls":["KVL能量守恒，KCL电荷守恒"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】能量守恒 【考点】直流电路分析 【一步步怎么算】 ① 题目：基尔霍夫电压定律（KVL）的实质是（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单","analysis":"【审题】问 KVL 的实质是什么，考查定律的物理本质：能量守恒。【定律/公式】KVL：沿任一回路，电压升之和=电压降之和，ΣU=0。其物理本质是单位电荷绕行一周电场力做功为零，即能量守恒（保守场）。【步骤】① 因为电荷绕闭合回路一周电场力做功为零，电位单值，所以电压升降代数和为零，体现能量守恒；② 因为电荷守恒是 KCL 的实质，所以 A 错误；③ 因为动量守恒、质量守恒与电路电压定律无关，所以 C、D 错误。【答案】能量守恒。【易错】×1 与 KCL 的电荷守恒记混；×2 记成“电压守恒”（没有这一守恒律名称）；×3 不理解“实质”，只背公式不知物理意义。【口诀】KVL 实质能量守，绕行一周功为零；KCL 才是电荷守，两律实质要分清。","steps":["【秒懂考点】KVL实质是能量守恒","【第一步】绕回路一周，电压升=电压降，电位回到原点","【第二步】电荷守恒对应KCL（节点）","【答案】选能量守恒"]});
  window.STUDY_DATA.questions.push({"id":"ee10","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"回路中电压升 10V、电压降 6V 与 4V，是否满足 KVL（　）","options":["满足，升=降","不满足","取决于电流","取决于电阻"],"answer":"满足，升=降","pitfalls":["6+4=10"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】满足，升=降 【考点】直流电路分析 【一步步怎么算】 ① 题目：回路中电压升 10V、电压降 6V 与 4V，是否满足 KVL（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ","analysis":"【审题】回路电压升 10 V、电压降 6 V 与 4 V，是否满足 KVL，验证升=降。【定律/公式】KVL：ΣU升=ΣU降，即 10=6+4。【步骤】① 因为电压降之和=6+4=10 V，电压升=10 V；② 因为升=降=10 V，满足 KVL；③ 因为满足与否只看电压关系，与电流、电阻无直接关系（它们已体现在电压中），所以 C、D 错误，选 A。【答案】满足，升=降。【易错】×1 误加成升 10 与降 10 不等（6+4=10 应相等）；×2 认为还要看电流电阻才定（KVL 只看电压）；×3 把“降 6 V 与 4 V”理解成其中一个。【口诀】KVL 升降要相等，十伏升来十伏降；六加四来正相合，只看电压不看旁。","steps":["【秒懂考点】KVL：升=降","【第一步】升10V，降6+4=10V，相等","【第二步】满足基尔霍夫电压定律","【答案】选满足，升=降"]});
  window.STUDY_DATA.questions.push({"id":"ee12","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"电阻 R=10Ω，通过电流 I=0.5A，则功率为（　）","options":["5 W","2.5 W","20 W","0.5 W"],"answer":"2.5 W","pitfalls":["I要先平方；5W是漏平方"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】2.5 W 【考点】直流电路分析 【一步步怎么算】 ① 题目：电阻 R=10Ω，通过电流 I=0.5A，则功率为（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量","analysis":"【审题】R=10 Ω、I=0.5 A，求功率，已知 I、R 用 P=I²R。【定律/公式】P=I²R=U²/R=UI。【步骤】① 因为已知 I、R，用 P=I²R=0.5²×10=0.25×10=2.5 W；② 因为 5 W 是 10×0.5 误用 U=IR 当功率、20 W 是 10/0.5 或误算、0.5 W 是漏乘，所以 B 正确；③ 因为也可 U=IR=5 V、P=UI=5×0.5=2.5 W，验算一致。【答案】2.5 W。【易错】×1 用 P=UI 时把 U 当 10 V（10 是 R）；×2 用 P=I²R 时漏平方得 5 W；×3 把 P=U²/R 的 U 用错。【口诀】已知电流用平方，零点五方乘十欧；二点五瓦算分明，电压电流功率路。","steps":["【秒懂考点】P=I²R","【第一步】I=0.5A，I²=0.25","【第二步】P=0.25×10=2.5W","【第三步】也可先算U=IR=5V，P=UI=5×0.5=2.5W","【答案】选2.5W"]});
  window.STUDY_DATA.questions.push({"id":"ee23","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"电路中某点电位为 5V，另一点为 2V，则两点间电压为（　）","options":["3 V","7 V","−3 V","10 V"],"answer":"3 V","pitfalls":["3V"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】3 V 【考点】直流电路分析 【一步步怎么算】 ① 题目：电路中某点电位为 5V，另一点为 2V，则两点间电压为（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量","analysis":"【审题】某点电位 5 V、另一点 2 V，求两点间电压，用电位差。【定律/公式】U=|φ₁−φ₂| 或按方向 Uab=Va−Vb。未指明方向时取大小，5−2=3 V。【步骤】① 因为电压等于两点电位之差，U=5−2=3 V；② 因为 7 V 是误加 5+2，所以 B 错误；③ 因为 −3 V 是方向反了（若定义 2 V 点到 5 V 点）、10 V 是误乘，所以 C、D 一般不选，题意求大小为 3 V。【答案】3 V。【易错】×1 误加电位得 7 V；×2 符号搞反得 −3 V（与谁减谁有关）；×3 不用电位差而乱算。【口诀】电压就是电位差，五减二来是三伏；加法乘法都不对，方向相反出负数。","steps":["【秒懂考点】电压=两点电位之差","【第一步】U=5-2=3V","【第二步】7V是相加，-3V是把顺序减反","【答案】选3V"]});
  window.STUDY_DATA.questions.push({"id":"ee32","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"R₁=3Ω 与 R₂=6Ω 并联，总电阻为（　）","options":["9 Ω","2 Ω","18 Ω","4.5 Ω"],"answer":"2 Ω","pitfalls":["2Ω"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】2 Ω 【考点】直流电路分析 【一步步怎么算】 ① 题目：R₁=3Ω 与 R₂=6Ω 并联，总电阻为（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（3）计算。","analysis":"【审题】R₁=3 Ω 与 R₂=6 Ω 并联求总电阻。【定律/公式】并联 R=R₁R₂/(R₁+R₂)=3×6/9=2 Ω。【步骤】① 因为 R=3×6/(3+6)=18/9=2 Ω；② 因为 9 Ω 是串联相加，所以 A 错误；③ 因为 18 Ω 是误乘、4.5 Ω 是算术平均，所以 C、D 错误。【答案】2 Ω。【易错】×1 用串联相加 9 Ω；×2 用平均 4.5 Ω；×3 倒数和算成 1/3+1/6=1/2 后答 0.5 未取倒。【口诀】三并六欧积除和，十八除九是两欧；串九并二要分清，倒数和后再取倒。","steps":["【秒懂考点】并联 R=R₁R₂/(R₁+R₂)","【第一步】R=3×6/(3+6)=18/9=2Ω","【第二步】9Ω是串联","【答案】选2Ω"]});
  window.STUDY_DATA.questions.push({"id":"ee33","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"串联分压：R₁=R₂，U=10V，则 U₁=（　）","options":["5 V","10 V","2.5 V","0 V"],"answer":"5 V","pitfalls":["5V"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】5 V 【考点】直流电路分析 【一步步怎么算】 ① 题目：串联分压：R₁=R₂，U=10V，则 U₁=（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（10）计","analysis":"【审题】串联分压，R₁=R₂，总压 U=10 V，求 U₁，等阻分压各半。【定律/公式】串联分压：U₁=U×R₁/(R₁+R₂)；当 R₁=R₂ 时 U₁=U/2。【步骤】① 因为 R₁=R₂，两电阻各分一半电压；② 因为 U₁=10/2=5 V；③ 因为 10 V 是总压、2.5 V 是再分一半误算、0 V 不可能，所以 A 正确。【答案】5 V。【易错】×1 答总压 10 V；×2 又除 2 得 2.5 V；×3 与并联（电压相同）混淆。【口诀】串阻相等压平分，十伏两半各五伏；并联才是同电压，分压分流要分清。","steps":["【秒懂考点】串联电阻相等，分压相等","【第一步】U₁=10/2=5V","【第二步】两电阻相同，各分一半","【答案】选5V"]});
  window.STUDY_DATA.questions.push({"id":"ee34","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"并联分流：R₁=R₂，I=4A，则 I₁=（　）","options":["2 A","4 A","1 A","8 A"],"answer":"2 A","pitfalls":["2A"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】2 A 【考点】直流电路分析 【一步步怎么算】 ① 题目：并联分流：R₁=R₂，I=4A，则 I₁=（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（4）计算。","analysis":"【审题】并联分流，R₁=R₂，总流 I=4 A，求 I₁，等阻分流各半。【定律/公式】并联分流：I₁=I×R₂/(R₁+R₂)（与自身电阻成反比）；R₁=R₂ 时 I₁=I/2。【步骤】① 因为 R₁=R₂，并联电压相同，电流平均分配；② 因为 I₁=4/2=2 A；③ 因为 4 A 是总流、1 A 是再分误算、8 A 是误乘，所以 A 正确。【答案】2 A。【易错】×1 答总电流 4 A；×2 以为与电阻成正比分多分少（等阻时仍各半）；×3 与串联分流概念颠倒。【口诀】并阻相等流平分，四安两半各两安；分流阻大流反小，串联电流才一样。","steps":["【秒懂考点】并联电阻相等，分流相等","【第一步】I₁=4/2=2A","【第二步】各支路电流相同","【答案】选2A"]});
  window.STUDY_DATA.questions.push({"id":"ee35","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"KCL 的物理本质是（　）","options":["能量守恒","电荷守恒","动量守恒","质量守恒"],"answer":"电荷守恒","pitfalls":["电荷守恒"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】电荷守恒 【考点】直流电路分析 【一步步怎么算】 ① 题目：KCL 的物理本质是（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω","analysis":"【审题】问 KCL 的物理本质，与 KVL 对照：KCL 是电荷守恒。【定律/公式】KCL：节点电流代数和为零，物理本质是电荷守恒（电荷不会在节点堆积）。【步骤】① 因为电荷在节点不能堆积也不能消失，流入必等于流出，所以 KCL 本质是电荷守恒；② 因为能量守恒是 KVL 的本质，所以 A 错误；③ 因为动量、质量守恒与节点电流无关，所以 C、D 错误。【答案】电荷守恒。【易错】×1 与 KVL 能量守恒记混；×2 答“电流守恒”（没有此守恒律名称）；×3 只背公式不知本质。【口诀】KCL 本质电荷守，节点进出一样走；KVL 才是能量守，两律本质别搞丢。","steps":["【秒懂考点】KCL本质电荷守恒","【第一步】节点处电荷不能积累，流入多少流出多少","【第二步】能量守恒对应KVL","【答案】选电荷守恒"]});
  window.STUDY_DATA.questions.push({"id":"ee37","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"短路时电路中电流（　）","options":["为 0","很小","很大","不变"],"answer":"很大","pitfalls":["很大"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】很大 【考点】直流电路分析 【一步步怎么算】 ① 题目：短路时电路中电流（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符号","analysis":"【审题】短路时电路电流如何，短路电阻近 0，电流很大。【定律/公式】短路时 I=E/r内，r内 很小，I 很大；端电压 U≈0。【步骤】① 因为短路把负载旁路，总电阻近似只剩电源内阻，很小；② 因为 I=U/R，R 极小所以 I 很大；③ 因为 0 是开路、很小不是短路、不变不对，所以 C 正确。【答案】很大。【易错】×1 与开路电流 0 混淆；×2 认为短路电压也大（端电压近 0）；×3 忽略烧毁危险。【口诀】短路电流非常大，开路电流才是零；短路电压近似零，保护装置要先行。","steps":["【秒懂考点】短路电流很大","【第一步】短路相当于R≈0，I=U/R趋于极大","【第二步】会烧断电源或导线，必须加保护","【答案】选很大"]});
  window.STUDY_DATA.questions.push({"id":"ee38","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"R=5Ω，U=10V，I=（　）","options":["2 A","50 A","0.5 A","15 A"],"answer":"2 A","pitfalls":["2A"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】2 A 【考点】直流电路分析 【一步步怎么算】 ① 题目：R=5Ω，U=10V，I=（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（5）计算。 ④ 注意单位（","analysis":"【审题】R=5 Ω、U=10 V，求 I，欧姆定律 I=U/R。【定律/公式】I=U/R=10/5=2 A。【步骤】① 因为 I=U/R；② 因为 10/5=2 A；③ 因为 50 A 是误乘、0.5 A 是除反、15 A 是误加，所以 A 正确。【答案】2 A。【易错】×1 做成 U×R=50 A；×2 做成 R/U=0.5 A；×3 单位漏写。【口诀】电流压除阻，十除五来是二安；乘法除法要分清，单位安培写周全。","steps":["【秒懂考点】I=U/R","【第一步】I=10/5=2A","【第二步】50A是U×R，0.5A是R/U","【答案】选2A"]});
  window.STUDY_DATA.questions.push({"id":"ee57","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","stem":"两电阻 R 与 R 并联等效为（　）","options":["R","frac{R}{2}","2R","4R"],"answer":"frac{R}{2}","pitfalls":["R/2"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】(R)/(2) 【考点】直流电路分析 【一步步怎么算】 ① 题目：两电阻 R 与 R 并联等效为（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意","analysis":"【审题】两个相同电阻 R 并联等效为多少，符号题，结果 R/2。【定律/公式】n 个相同电阻 R 并联：R并=R/n；两个则 R/2。【步骤】① 因为并联总阻倒数相加，1/R并=1/R+1/R=2/R；② 因为取倒数得 R并=R/2；③ 因为 R 是没算、2R 是串联、4R 无依据，所以选 R/2（frac{R}{2}）。【答案】frac{R}{2}。【易错】×1 与串联 2R 记混；×2 倒数和后忘记取倒；×3 认为并联还是 R。【口诀】两同相并除以二，两同相串乘以二；倒数和后再取倒，串大并小不忘记。","steps":["【秒懂考点】两个R并联=R/2","【第一步】R×R/(R+R)=R/2","【第二步】2R是串联","【答案】选R/2"]});
  window.STUDY_DATA.questions.push({"id":"ex06e","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"两电阻 R 串联，总电阻（　）","options":["R","2R","frac{R}{2}","R²"],"answer":"2R","tags":["串联"],"source":"batch","pitfalls":["2R"],"explainLevel":"subject-specific","hint":"【结论】2R 【考点】直流电路分析 【一步步怎么算】 ① 题目：两电阻 R 串联，总电阻（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω","analysis":"【审题】两个电阻 R 串联总电阻，符号推导题，不代具体数值，结果是 2R。要与并联 R/2 严格区分。【定律/公式】串联电阻：R总=R1+R2+…+Rn。两个相同电阻 R 相加：R总=R+R=2R。【步骤】① 因为串联电路电流处处相等，各电阻电压按阻值分配，等效电阻等于各电阻代数和；② 因为两个阻值都是 R，所以 R总=R+R=2R；③ 因为 R 是漏加、R/2 是并联结果、R² 是误乘，所以只有 2R 正确。【答案】2R。【易错】×1 与并联 R/2 记混，答成一半；×2 只写 R 忘记相加；×3 误乘成 R²，或把符号题当数字题乱代。【口诀】两阻串联加起来，R 加 R 等于 2R；并联才是 R 一半，串并对照记心怀。","steps":["【秒懂考点】两R串联=2R","【第一步】R+R=2R","【答案】2R"]});
  window.STUDY_DATA.questions.push({"id":"ex07e","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"两电阻 R 并联，总电阻（　）","options":["R","2R","frac{R}{2}","4R"],"answer":"frac{R}{2}","tags":["并联"],"source":"batch","pitfalls":["R/2"],"explainLevel":"subject-specific","hint":"【结论】(R)/(2) 【考点】直流电路分析 【一步步怎么算】 ① 题目：两电阻 R 并联，总电阻（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（","analysis":"【审题】两个电阻 R 并联总电阻，与串联题对照，结果 R/2。【定律/公式】并联 R总=R×R/(R+R)=R/2。【步骤】① 因为 1/R并=2/R；② 因为 R并=R/2；③ 因为 2R 是串联、4R 无依据，所以 C 正确。【答案】frac{R}{2}。【易错】×1 与串联 2R 对调；×2 倒数未取倒；×3 答 R。【口诀】两同并联得一半，R 除以二记心间；串联才是二 R 值，串并大小相反看。","steps":["【秒懂考点】两R并联=R/2","【第一步】R²/(2R)=R/2","【答案】R/2"]});
  window.STUDY_DATA.questions.push({"id":"mqe1","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"single","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"R=2Ω，U=4V，I=（　）","options":["1A","2A","3A","4A"],"answer":"2A","tags":["欧姆"],"source":"batch","pitfalls":["I=U/R"],"explainLevel":"subject-specific","hint":"【结论】2A 【考点】直流电路分析 【一步步怎么算】 ① 题目：R=2Ω，U=4V，I=（ ）。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（2）计算。 ④ 注意单位（V/","analysis":"【审题】已知 R=2 Ω、U=4 V，求电流 I，是欧姆定律 I=U/R 的一步除法计算，干扰项来自除反、相加、相乘。【定律/公式】欧姆定律：I=U/R。电压单位 V，电阻 Ω，电流 A。【步骤】① 因为电流等于电压除以电阻，所以 I=U/R；② 因为 U=4 V、R=2 Ω，所以 I=4/2=2 A；③ 因为 2/4=0.5 再错成 1A、4+2=6、4×2=8 都不是本题运算，选项中只有 2A 对应正确结果。【答案】2A。【易错】×1 把 I=U/R 做成 R/U=0.5 A 或误选 1A；×2 做成 U+R 或 U×R；×3 单位漏写 A，或把 2A 写成 2V。【口诀】四伏除以二欧姆，电流正好二安培；欧姆定律最常用，压上阻下别弄反。","steps":["【秒懂考点】欧姆定律 I=U/R","【第一步】I=4/2=2A","【答案】2A"]});
