  window.STUDY_DATA.questions.push({"id":"ne2001","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"基尔霍夫定律","type":"single","typeLabel":"单选","stem":"基尔霍夫电流定律KCL，下列说法正确的是（　）","options":["适用于任一节点","只适用于闭合回路","只适用于线性电路","只适用于直流电路"],"answer":"适用于任一节点","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电路","KCL"],"analysis":"【审题】问 KCL 的适用范围，下列说法正确的是：适用于任一节点。注意 KCL 不限于直流/线性。【定律/公式】KCL（基尔霍夫电流定律）：任一时刻，对任一节点，流入电流之和等于流出电流之和。适用于集总参数电路，与线性/直流无关。【步骤】① 因为 KCL 基于电荷守恒，对任意节点、任意时刻成立，所以 A 正确；② 因为“只适用于闭合回路”是 KVL 的说法，所以 B 错误；③ 因为 KCL 对非线性、交流电路同样成立，所以 C、D 限制错误。【答案】适用于任一节点。【易错】×1 与 KVL（回路）适用对象混淆；×2 认为只适用于直流或线性；×3 认为需要电阻元件才成立（其实与元件性质无关）。【口诀】KCL 适用任一节点，交流直流都对接；线性非线性都成立，电荷守恒不打折。","steps":["【秒懂考点】KCL适用任一节点","【第一步】不限于线性","【答案】适用于任一节点"],"pitfalls":["任一节点通用"]});
  window.STUDY_DATA.questions.push({"id":"ne2101","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"电阻串联","type":"single","typeLabel":"单选","stem":"两个电阻R1=6Ω，R2=3Ω串联，总电阻为（　）","options":["2Ω","3Ω","9Ω","18Ω"],"answer":"9Ω","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电路","串联"],"analysis":"【审题】R1=6 Ω、R2=3 Ω 串联求总电阻，串联相加。【定律/公式】串联 R总=R1+R2=6+3=9 Ω。【步骤】① 因为串联电阻直接相加；② 因为 6+3=9 Ω；③ 因为 2 Ω 是并联结果、3 Ω 是单个、18 Ω 是误乘，所以 C 正确。【答案】9Ω。【易错】×1 与并联混淆得 2 Ω；×2 只答 R2=3 Ω；×3 误乘 6×3=18 Ω。【口诀】六欧三欧串起来，相加九欧是总阻；并联才是积除和，串大并小分清楚。","steps":["【秒懂考点】串联9Ω","【第一步】6+3=9","【答案】9Ω"],"pitfalls":["串联9"]});
  window.STUDY_DATA.questions.push({"id":"ne2102","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"电阻并联","type":"single","typeLabel":"单选","stem":"两个电阻R1=6Ω，R2=3Ω并联，总电阻为（　）","options":["2Ω","3Ω","9Ω","18Ω"],"answer":"2Ω","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电路","并联"],"analysis":"【审题】R1=6 Ω、R2=3 Ω 并联求总电阻，与上题串联对照。【定律/公式】并联 R=R1R2/(R1+R2)=6×3/9=2 Ω。【步骤】① 因为并联用积除以和；② 因为 18/9=2 Ω；③ 因为 9 Ω 是串联、3 Ω 是单个、18 Ω 是误乘，所以 A 正确。【答案】2Ω。【易错】×1 与串联相加得 9 Ω；×2 答较大电阻 6 或较小 3；×3 倒数和 1/6+1/3=1/2 后忘记取倒答 0.5。【口诀】六并三欧积除和，十八除九是两欧；串联九欧并两欧，对照记忆最稳妥。","steps":["【秒懂考点】并联2Ω","【第一步】18/9=2","【答案】2Ω"],"pitfalls":["并联2"]});
  window.STUDY_DATA.questions.push({"id":"ne2103","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"KVL","type":"single","typeLabel":"单选","stem":"基尔霍夫电压定律KVL，正确的是（　）","options":["任一节点电流和为0","任一回路电压和为0","只适用于直流","只适用于电阻"],"answer":"任一回路电压和为0","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电路","KVL"],"analysis":"【审题】问 KVL 的正确表述：任一回路电压和为 0（代数和）。与 KCL 表述对照。【定律/公式】KVL：任一时刻，沿任一回路，各段电压代数和为零，ΣU=0。【步骤】① 因为 KVL 描述回路电压关系，ΣU=0，所以 B 正确；② 因为“节点电流和为 0”是 KCL，所以 A 错误；③ 因为 KVL 对交流、非线性、含源回路都成立，不限于直流和电阻，所以 C、D 错误。【答案】任一回路电压和为0。【易错】×1 与 KCL 节点电流混淆；×2 认为只适用直流/电阻；×3 把“电压和为 0”理解成各电压都为 0（是代数和为 0）。【口诀】KVL 回路电压零，KCL 节点电流平；交流直流都适用，代数和来才说清。","steps":["【秒懂考点】KVL回路电压和0","【第一步】KCL才节点","【答案】任一回路电压和为0"],"pitfalls":["KCL节点、KVL回路"]});
  window.STUDY_DATA.questions.push({"id":"ne2201","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"欧姆定律","type":"single","typeLabel":"单选","stem":"某电阻两端电压10V，流过电流2A，电阻阻值是（　）","options":["5Ω","20Ω","0.2Ω","12Ω"],"answer":"5Ω","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电路","欧姆定律"],"analysis":"【审题】已知电压 10 V、电流 2 A，求电阻 R，R=U/I。【定律/公式】欧姆定律：R=U/I=10/2=5 Ω。【步骤】① 因为 R=U/I；② 因为 10÷2=5 Ω；③ 因为 20 Ω 是误乘、0.2 Ω 是除反、12 Ω 是误加，所以 A 正确。【答案】5Ω。【易错】×1 做成 U×I=20 Ω；×2 做成 I/U=0.2 Ω；×3 误加 12 Ω。【口诀】电阻压除电流算，十伏两安五欧姆；乘法除法别弄反，单位欧姆要记住。","steps":["【秒懂考点】R=U/I=5","【第一步】10/2=5","【答案】5Ω"],"pitfalls":["10÷2=5"]});
  window.STUDY_DATA.questions.push({"id":"ne2301","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"串联电阻","type":"single","typeLabel":"单选","stem":"R1=10Ω，R2=20Ω，R3=30Ω串联，总电阻是（　）","options":["10Ω","30Ω","60Ω","20Ω"],"answer":"60Ω","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电路","串联"],"analysis":"【审题】R1=10 Ω、R2=20 Ω、R3=30 Ω 串联求总电阻，多电阻串联相加。【定律/公式】串联 R总=R1+R2+R3=10+20+30。【步骤】① 因为串联电阻相加；② 因为 10+20+30=60 Ω；③ 因为 10、30、20 都是单个电阻，所以 C 正确。【答案】60Ω。【易错】×1 只加其中两个；×2 与并联混淆得小于最小电阻；×3 误乘。【口诀】三阻串联加起来，十加二十再三十；六十欧姆是总阻，串联相加不会坏。","steps":["【秒懂考点】串联60Ω","【第一步】10+20+30","【答案】60Ω"],"pitfalls":["串联相加"]});
  window.STUDY_DATA.questions.push({"id":"ne2302","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"并联电阻","type":"single","typeLabel":"单选","stem":"两个10Ω电阻并联，总电阻是（　）","options":["20Ω","10Ω","5Ω","2.5Ω"],"answer":"5Ω","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电路","并联"],"analysis":"【审题】两个 10 Ω 电阻并联求总电阻，相同电阻并联除以个数。【定律/公式】并联：两个相同 R 并联=R/2=5 Ω。【步骤】① 因为 1/R并=1/10+1/10=2/10；② 因为 R并=10/2=5 Ω；③ 因为 20 Ω 是串联、10 Ω 是没算、2.5 Ω 是再除误算，所以 C 正确。【答案】5Ω。【易错】×1 与串联相加得 20 Ω；×2 答 10 Ω；×3 再除 2 得 2.5 Ω。【口诀】两同十欧并联起，总阻五欧是正理；串二十来并五欧，串大并小记心里。","steps":["【秒懂考点】并联5Ω","【第一步】10/2=5","【答案】5Ω"],"pitfalls":["并联减半"]});
  window.STUDY_DATA.questions.push({"id":"ne2303","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"基尔霍夫电流定律","type":"single","typeLabel":"单选","stem":"基尔霍夫电流定律（KCL）是指（　）","options":["节点上流入电流之和等于流出电流之和","回路电压之和为0","电阻两端电压等于IR","功率守恒"],"answer":"节点上流入电流之和等于流出电流之和","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电路","KCL"],"analysis":"【审题】问 KCL 的含义：节点上流入电流之和等于流出电流之和。【定律/公式】KCL：ΣI入=ΣI出，或 ΣI=0（流入取负流出取正）。【步骤】① 因为 KCL 描述节点电流关系，流入等于流出，所以 A 正确；② 因为“回路电压之和为 0”是 KVL，所以 B 错误；③ 因为“U=IR”是欧姆定律、“功率守恒”不是 KCL 表述，所以 C、D 错误。【答案】节点上流入电流之和等于流出电流之和。【易错】×1 与 KVL 混淆；×2 把 KCL 说成“电流处处相等”（那是串联）；×3 与功率守恒混淆。【口诀】KCL 节点流进等，进出相等是真经；KVL 回路电压零，两律表述要分清。","steps":["【秒懂考点】KCL节点流入=流出","【第一步】电荷守恒","【答案】节点上流入电流之和等于流出电流之和"],"pitfalls":["KVL才是回路"]});
  window.STUDY_DATA.questions.push({"id":"ne2403","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"电源外特性","type":"single","typeLabel":"单选","stem":"理想电压源的内阻等于（　）","options":["0","无穷大","1Ω","不确定"],"answer":"0","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电路","电压源"],"analysis":"【审题】问理想电压源的内阻等于多少，与理想电流源内阻对照。【定律/公式】理想电压源内阻 rs=0（端电压不随电流变）；理想电流源内阻 rs=∞。【步骤】① 因为理想电压源内阻为 0，才能保持端电压恒定；② 因为无穷大是理想电流源内阻，所以 B 错误；③ 因为 1 Ω、不确定都不是理想模型，所以 C、D 错误。【答案】0。【易错】×1 与理想电流源内阻无穷大记混；×2 认为内阻越大越理想（电压源要小）；×3 答不确定。【口诀】理想压源内阻零，理想流源无穷大；压源零阻压恒定，流源无穷流不怕。","steps":["【秒懂考点】理想电压源内阻0","【第一步】电流源∞","【答案】0"],"pitfalls":["电压源内阻0，电流源∞"]});
  window.STUDY_DATA.questions.push({"id":"ne2601","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"并联电阻","type":"single","typeLabel":"单选","stem":"两个100Ω电阻并联总电阻是（　）","options":["50Ω","100Ω","200Ω","25Ω"],"answer":"50Ω","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电路","并联"],"analysis":"【审题】两个 100 Ω 电阻并联求总电阻，相同电阻并联减半。【定律/公式】两个相同电阻并联：R并=R/2=100/2=50 Ω。【步骤】① 因为 1/R并=1/100+1/100=2/100；② 因为 R并=100/2=50 Ω；③ 因为 100 Ω 是没算、200 Ω 是串联、25 Ω 是再除，所以 A 正确。【答案】50Ω。【易错】×1 与串联 200 Ω 混淆；×2 答 100 Ω；×3 再除 2 得 25 Ω。【口诀】两同百欧并联起，总阻五十正合理；串二百来并五十，串大并小要牢记。","steps":["【秒懂考点】两100并=50","【第一步】减半","【答案】50Ω"],"pitfalls":["并联减半"]});
  window.STUDY_DATA.questions.push({"id":"ne2602","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"理想电流源","type":"single","typeLabel":"单选","stem":"理想电流源内阻等于（　）","options":["0","无穷大","1Ω","不确定"],"answer":"无穷大","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电路","电流源"],"analysis":"【审题】问理想电流源内阻等于多少，与理想电压源内阻对照。【定律/公式】理想电流源内阻 rs=∞；理想电压源内阻 rs=0。【步骤】① 因为理想电流源要保持电流恒定，内阻必须无穷大，分流才可忽略；② 因为 0 是理想电压源内阻，所以 A 错误；③ 因为 1 Ω、不确定不是理想模型，所以 C、D 错误。【答案】无穷大。【易错】×1 与理想电压源内阻 0 记混；×2 认为内阻越小越理想（电流源要大）；×3 答不确定。【口诀】理想流源无穷大，理想压源内阻零；流源无穷流恒定，压源零阻压不崩。","steps":["【秒懂考点】电流源内阻∞","【第一步】电压源0","【答案】无穷大"],"pitfalls":["电流∞电压0"]});
  window.STUDY_DATA.questions.push({"id":"ne2604","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"电桥平衡应用","type":"single","typeLabel":"单选","stem":"惠斯通电桥用来测量（　）","options":["电阻","电压","电流","功率"],"answer":"电阻","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电路","电桥"],"analysis":"【审题】问惠斯通电桥的用途，经典电阻测量仪器，平衡时测电阻精度高。【定律/公式】惠斯通电桥（直流电桥）：平衡条件 R1/R2=R3/R4，用于精确测量电阻。【步骤】① 因为电桥平衡时检流计示零，由比例关系可求未知电阻，所以 A 正确；② 因为电压用电压表、电流用电流表，所以 B、C 不是电桥主要用途；③ 因为功率由 P=UI 算出，不是电桥直接测量，所以 D 错误。【答案】电阻。【易错】×1 与电压表电流表用途混淆；×2 认为电桥测功率；×3 忽略“平衡”条件的意义。【口诀】惠斯通桥测电阻，平衡比例精度足；压表流表测压流，功率乘出不靠桥。","steps":["【秒懂考点】电桥测电阻","【第一步】平衡条件","【答案】电阻"],"pitfalls":["测电阻"]});
  window.STUDY_DATA.questions.push({"id":"e201","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"戴维南等效","type":"single","stem":"某有源二端网络开路电压为12V，等效电阻为4Ω，外接负载R=8Ω时，负载电流为（　）","options":["1A","1.5A","2A","3A"],"answer":"1A","pitfalls":["别用12/8=1.5漏内阻；要12/(4+8)=1A"],"difficulty":2,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"强化","tags":["戴维南定理","ch-ee-3"],"explainLevel":"subject-specific","analysis":"【审题】有源二端网络：开路电压 12 V、等效电阻 4 Ω，外接 R=8 Ω，求负载电流，用戴维南等效后简单回路。【定律/公式】戴维南等效：Uoc 串 R0；接负载后 I=Uoc/(R0+RL)。【步骤】① 因为戴维南等效电路是 12 V 电压源串 4 Ω 内阻；② 因为外接 8 Ω 后总电阻 4+8=12 Ω，I=12/12=1 A；③ 因为 1.5 A、2 A、3 A 都与 12/(4+8) 不符，所以 A 正确。【答案】1A。【易错】×1 忘记串上等效内阻，算成 12/8=1.5 A；×2 内阻与负载并联误算；×3 开路电压与短路电流公式混用。【口诀】戴维南后串内阻，总阻相加再求流；十二除以十二欧，一安电流不用愁。","steps":["【秒懂考点】戴维南等效：Uoc=12V串R₀=4Ω，再接负载，答案1A","【第一步：等效】网络=12V电压源串联4Ω内阻","【第二步：总电阻】R总=R₀+R=4+8=12Ω","【第三步：电流】I=Uoc/R总=12/12=1A","【第四步：验证】负载8V+内阻4V=12V，正确","【答案】选A（1A）"]});
  window.STUDY_DATA.questions.push({"id":"ee14","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电路定理","type":"single","stem":"戴维南等效电路由（　）组成。","options":["电流源串电阻","电压源串电阻","电压源并电阻","两个电流源"],"answer":"电压源串电阻","pitfalls":["电压源串内阻"],"difficulty":2,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"强化","tags":["电路定理","ch-ee-3"],"explainLevel":"subject-specific","hint":"【结论】电压源串电阻 【考点】电路定理 【一步步怎么算】 ① 题目：戴维南等效电路由（ ）组成。。 ② 用「电路定理」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）","analysis":"【审题】问戴维南等效电路由什么组成：电压源串联电阻。【定律/公式】戴维南定理：线性有源二端网络可等效为电压源 Uoc 与电阻 R0 串联。【步骤】① 因为戴维南等效对外表现为开路电压 Uoc 串等效内阻 R0，所以 B 正确；② 因为“电流源串电阻”是错误结构（诺顿是电流源并电阻），所以 A 错误；③ 因为“电压源并电阻”“两个电流源”都不是戴维南标准形式，所以 C、D 错误。【答案】电压源串电阻。【易错】×1 与诺顿（电流源并电阻）混淆；×2 记成电压源并电阻；×3 记成电流源串电阻。【口诀】戴维南压串阻，诺顿流并阻；两形式要分清，等效对外不认输。","steps":["【秒懂考点】戴维南=电压源串联电阻","【第一步】等效为开路电压Uoc串等效内阻R0","【第二步】电压源并电阻是错误结构","【答案】选电压源串电阻"]});
  window.STUDY_DATA.questions.push({"id":"ee15","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电路定理","type":"single","stem":"求戴维南等效内阻时，独立电压源应（　）","options":["开路","短路","保留","改电流"],"answer":"短路","pitfalls":["电压源短路、电流源开路"],"difficulty":2,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"强化","tags":["电路定理","ch-ee-3"],"explainLevel":"subject-specific","hint":"【结论】短路 【考点】电路定理 【一步步怎么算】 ① 题目：求戴维南等效内阻时，独立电压源应（ ）。 ② 用「电路定理」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω","analysis":"【审题】求戴维南等效内阻时独立电压源应如何处理：短路（置零）。【定律/公式】求 R0 时：独立电压源短路（U=0），独立电流源开路（I=0）；受控源保留。【步骤】① 因为电压源置零即电压为 0，相当于导线短路；② 因为电流源置零是开路，所以本题电压源应短路；③ 因为保留、改电流都不是置零方法，所以 B 正确。【答案】短路。【易错】×1 把电压源开路（那是电流源置零）；×2 把受控源也置零（应保留）；×3 求 R0 时短路负载或搞错方向。【口诀】压源置零要短路，流源置零要开路；受控电源要保留，内阻求法记牢固。","steps":["【秒懂考点】求内阻：电压源短路","【第一步】独立电压源短路（置零），电流源开路","【第二步】再从端口看进去算等效电阻","【答案】选短路"]});
  window.STUDY_DATA.questions.push({"id":"ee25","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电路定理","type":"single","stem":"诺顿等效电路由（　）组成。","options":["电压源串电阻","电流源并电阻","电压源并电阻","两电流源串联"],"answer":"电流源并电阻","pitfalls":["电流源并电阻"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["电路定理","ch-ee-3"],"explainLevel":"subject-specific","hint":"【结论】电流源并电阻 【考点】电路定理 【一步步怎么算】 ① 题目：诺顿等效电路由（ ）组成。。 ② 用「电路定理」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与","analysis":"【审题】问诺顿等效电路组成：电流源并联电阻。【定律/公式】诺顿定理：二端网络等效为电流源 Isc 与电阻 R0 并联。与戴维南可互换：Uoc=Isc×R0。【步骤】① 因为诺顿形式是电流源并电阻，所以 B 正确；② 因为“电压源串电阻”是戴维南，所以 A 错误；③ 因为“电压源并电阻”“两电流源串联”都不是诺顿标准形式，所以 C、D 错误。【答案】电流源并电阻。【易错】×1 与戴维南混淆；×2 记成电流源串电阻；×3 记成电压源并电阻。【口诀】诺顿流源并电阻，戴维南压串阻；互换公式 U 等于 I 乘 R，两形等效不糊涂。","steps":["【秒懂考点】诺顿=电流源并联电阻","【第一步】戴维南是电压源串电阻，诺顿是其对偶形式","【第二步】电流源方向由短路电流方向决定","【答案】选电流源并电阻"]});
  window.STUDY_DATA.questions.push({"id":"ee39","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电路定理","type":"single","stem":"叠加定理中，电压源置零指（　）","options":["开路","短路","保留","反向"],"answer":"短路","pitfalls":["短路"],"difficulty":2,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"强化","tags":["电路定理","ch-ee-3"],"explainLevel":"subject-specific","hint":"【结论】短路 【考点】电路定理 【一步步怎么算】 ① 题目：叠加定理中，电压源置零指（ ）。 ② 用「电路定理」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符号","analysis":"【审题】叠加定理中电压源置零指什么：短路。与电流源置零对照。【定律/公式】叠加定理：各独立源单独作用时，电压源置零=短路（U=0），电流源置零=开路（I=0）。【步骤】① 因为电压源置零要求其端电压为 0，实现方式是短路；② 因为开路是电流源置零方式，所以 A 错误；③ 因为保留、反向都不是置零，所以 C、D 错误。【答案】短路。【易错】×1 把电压源置零做成开路；×2 与电流源置零记反；×3 叠加时把受控源也置零。【口诀】叠加压源置零短，流源置零要开断；受控电源不能消，单独作用再求算。","steps":["【秒懂考点】电压源置零=短路","【第一步】电压源短路（电压为0）","【第二步】求等效内阻时使用","【答案】选短路"]});
  window.STUDY_DATA.questions.push({"id":"ee40","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电路定理","type":"single","stem":"叠加定理中，电流源置零指（　）","options":["短路","开路","反向","并联电阻"],"answer":"开路","pitfalls":["开路"],"difficulty":2,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"强化","tags":["电路定理","ch-ee-3"],"explainLevel":"subject-specific","hint":"【结论】开路 【考点】电路定理 【一步步怎么算】 ① 题目：叠加定理中，电流源置零指（ ）。 ② 用「电路定理」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符号","analysis":"【审题】叠加定理中电流源置零指什么：开路。与电压源置零对照。【定律/公式】电流源置零=开路（I=0）；电压源置零=短路。【步骤】① 因为电流源置零要求电流为 0，实现方式是开路；② 因为短路是电压源置零方式，所以 A 错误；③ 因为反向、并联电阻不是置零，所以 C、D 错误。【答案】开路。【易错】×1 与电压源置零短路记反；×2 把电流源短路（会出大问题）；×3 叠加后忘记把各分量按参考方向相加。【口诀】流源置零要开路，压源置零才短路；两句话要对着记，叠加单独再合股。","steps":["【秒懂考点】电流源置零=开路","【第一步】电流源开路（电流为0）","【第二步】与电压源短路配对记忆","【答案】选开路"]});
  window.STUDY_DATA.questions.push({"id":"exam-ee-2026-03","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"戴维南定理","type":"single","typeLabel":"单选","stem":"戴维南等效电路是（　）","options":["电压源串电阻","电流源并电阻","电压源并电阻","电流源串电阻"],"answer":"电压源串电阻","difficulty":2,"difficultyLabel":"强化","source":"school","tags":["真题","2026"],"analysis":"【审题】问戴维南等效电路是什么，与诺顿对照：电压源串电阻。【定律/公式】戴维南等效：Uoc 与 R0 串联。【步骤】① 因为戴维南定理结论是等效为电压源串电阻，所以 A 正确；② 因为“电流源并电阻”是诺顿，所以 B 错误；③ 因为“电压源并电阻”“电流源串电阻”不是标准等效形式，所以 C、D 错误。【答案】电压源串电阻。【易错】×1 与诺顿记混；×2 记成并联结构；×3 记成电流源串电阻。【口诀】戴维南压串阻，诺顿流并阻；考试常考两形式，看清题目再落笔。","steps":["【秒懂考点】戴维南电压串电阻","【第一步】诺顿电流并","【答案】电压源串电阻"],"pitfalls":["电压串电阻"]});
  window.STUDY_DATA.questions.push({"id":"exam25-ee-s04","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"叠加定理","type":"single","typeLabel":"单选","stem":"叠加定理适用于（　）","options":["线性电路","非线性电路","所有电路","直流电路"],"answer":"线性电路","difficulty":1,"difficultyLabel":"基础","source":"school","tags":["2025真题","电工"],"analysis":"【审题】问叠加定理适用于什么电路，叠加定理基于线性性，只适用于线性电路。【定律/公式】叠加定理：线性电路中，多个独立源共同作用的响应=各独立源单独作用响应之和。非线性元件（二极管等）不适用。【步骤】① 因为叠加依赖齐次性与可加性（线性性质），所以只适用于线性电路；② 因为非线性电路不满足可加性，所以 B 错误；③ 因为“所有电路”太宽，“直流电路”只是线性电路的一种，交流线性电路同样适用，所以 C、D 不准确。【答案】线性电路。【易错】×1 认为所有电路都能叠加；×2 认为只适用直流；×3 在含二极管电路用叠加。【口诀】叠加只对线性路，非线性来不满足；直流交流线性可，二极管路要另谋。","steps":["【秒懂考点】叠加线性","【第一步】非线性不适用","【答案】线性电路"],"pitfalls":["线性"]});
  window.STUDY_DATA.questions.push({"id":"ne3002","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"感抗容抗","type":"single","typeLabel":"单选","stem":"电感L的感抗XL与频率f的关系是（　）","options":["XL = 2πfL","XL = 1/(2πfL)","XL = fL","XL = L/f"],"answer":"XL = 2πfL","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["交流电路","感抗"],"analysis":"【审题】问感抗 XL 与频率 f 的关系，考查公式 XL=2πfL=ωL。【定律/公式】感抗：XL=ωL=2πfL，与频率成正比；直流时 f=0，XL=0（电感相当于短路）。【步骤】① 因为感抗 XL=ωL 且 ω=2πf，所以 XL=2πfL；② 因为 1/(2πfL) 是容抗形式，所以 B 错误；③ 因为 fL、L/f 都缺 2π 或关系反了，所以 C、D 错误。【答案】XL = 2πfL。【易错】×1 与容抗 XC=1/(2πfC) 记混；×2 漏掉 2π；×3 认为感抗与频率成反比。【口诀】感抗二派 fL，频率越高阻越大；容抗倒数二派 fC，频率越高阻越下。","steps":["【秒懂考点】Xl=2πfL","【第一步】正比f","【答案】XL = 2πfL"],"pitfalls":["2πfL"]});
  window.STUDY_DATA.questions.push({"id":"ne3101","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"有效值","type":"single","typeLabel":"单选","stem":"民用照明电压220V是指交流电的（　）","options":["最大值","有效值","瞬时值","平均值"],"answer":"有效值","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["交流电路","有效值"],"analysis":"【审题】问民用照明电压 220 V 指的是交流电的什么值：有效值。【定律/公式】交流有效值 U=Um/√2；民用电压 220 V 是有效值，最大值约 311 V。【步骤】① 因为电气设备额定值、民用电压都用有效值表示，220 V 是有效值；② 因为最大值约 220×√2≈311 V，所以 A 错误；③ 因为瞬时值随时间变、平均值正弦波一周为 0，所以 C、D 错误。【答案】有效值。【易错】×1 当成最大值；×2 与瞬时值混淆；×3 认为平均值是 220 V。【口诀】二百二十有效值，最大三百一十一；瞬时时刻在变化，平均一周是零值。","steps":["【秒懂考点】220有效值","【第一步】峰值311","【答案】有效值"],"pitfalls":["220有效值峰值311"]});
  window.STUDY_DATA.questions.push({"id":"ne3102","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"频率周期","type":"single","typeLabel":"单选","stem":"我国市电的频率是（　）","options":["50Hz","60Hz","100Hz","220Hz"],"answer":"50Hz","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["交流电路","频率"],"analysis":"【审题】问我国市电频率，常识：50 Hz。【定律/公式】我国交流电频率 f=50 Hz，周期 T=1/f=0.02 s；美国等 60 Hz。【步骤】① 因为我国电力系统标准频率 50 Hz，所以 A 正确；② 因为 60 Hz 是部分国家（美、日部分）标准，所以 B 错误；③ 因为 100 Hz、220 Hz 都不是市电频率（220 是电压数值），所以 C、D 错误。【答案】50Hz。【易错】×1 与 60 Hz 混淆；×2 把电压 220 与频率混答；×3 与倍频 100 Hz 混淆。【口诀】我国市电五十赫，周期零点零二秒；六十赫兹是外邦，电压二百二并列。","steps":["【秒懂考点】市电50Hz","【第一步】220V 50Hz","【答案】50Hz"],"pitfalls":["50Hz"]});
  window.STUDY_DATA.questions.push({"id":"ne3201","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"感抗容抗","type":"single","typeLabel":"单选","stem":"电容的容抗XC与频率f的关系是（　）","options":["XC = 2πfC","XC = 1/(2πfC)","XC = fC","XC = C/f"],"answer":"XC = 1/(2πfC)","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["交流电路","容抗"],"analysis":"【审题】问容抗 XC 与频率 f 的关系，公式 XC=1/(2πfC)=1/(ωC)。【定律/公式】容抗：XC=1/(ωC)=1/(2πfC)，与频率成反比；直流 f=0 时 XC→∞（隔直）。【步骤】① 因为 XC=1/(ωC)、ω=2πf，所以 XC=1/(2πfC)；② 因为 2πfC 是感抗形式的系数，所以 A 错误；③ 因为 fC、C/f 都不是容抗公式，所以 C、D 错误。【答案】XC = 1/(2πfC)。【易错】×1 与感抗 XL=2πfL 记混；×2 漏掉倒数；×3 认为容抗与频率成正比。【口诀】容抗倒数二派 fC，频率越高阻越松；感抗二派 fL 正相反，直流电容全隔空。","steps":["【秒懂考点】Xc=1/(2πfC)","【第一步】f越大越小","【答案】XC = 1/(2πfC)"],"pitfalls":["f越大容抗越小"]});
  window.STUDY_DATA.questions.push({"id":"ne3301","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"正弦量三要素","type":"single","typeLabel":"单选","stem":"正弦交流电的三要素是（　）","options":["最大值、角频率、初相位","电压、电流、功率","电阻、电感、电容","周期、频率、角频率"],"answer":"最大值、角频率、初相位","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["交流电路","三要素"],"analysis":"【审题】问正弦交流电三要素，与前面“不包括”题呼应：最大值、角频率、初相位。【定律/公式】u=Um sin(ωt+ψ)：三要素 Um、ω、ψ。【步骤】① 因为三要素是最大值、角频率、初相位，所以 A 正确；② 因为电压、电流、功率是电路量不是波形三要素，所以 B 错误；③ 因为 RLC 是元件、周期频率角频率互相关联不是三独立要素，所以 C、D 错误。【答案】最大值、角频率、初相位。【易错】×1 把有效值当三要素；×2 把频率与角频率都算上漏了初相；×3 与电路三元件混淆。【口诀】三要素压最大值，角频初相要记齐；有效压除根号二，三量决定波形齐。","steps":["【秒懂考点】三要素Umωφ","【第一步】周期角频率可互算","【答案】最大值、角频率、初相位"],"pitfalls":["Umωφ三要素"]});
  window.STUDY_DATA.questions.push({"id":"ne3302","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"有效值","type":"single","typeLabel":"单选","stem":"市电220V指的是交流电的（　）","options":["最大值","有效值","瞬时值","平均值"],"answer":"有效值","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["交流电路","有效值"],"analysis":"【审题】市电 220 V 指的是什么值，与前面同考点：有效值。【定律/公式】额定电压、民用电压均指有效值；Um=√2 U。【步骤】① 因为 220 V 是有效值，用于电器额定；② 因为最大值约 311 V，所以 A 错误；③ 因为瞬时值、平均值都不是 220 V 的定义，所以 C、D 错误。【答案】有效值。【易错】×1 当最大值；×2 当瞬时值；×3 当平均值。【口诀】市电二百二有效，最大乘以根号二；额定电压有效值，三个数值要分清。","steps":["【秒懂考点】220有效值","【第一步】峰值311","【答案】有效值"],"pitfalls":["有效值"]});
  window.STUDY_DATA.questions.push({"id":"ne3303","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"频率与周期","type":"single","typeLabel":"单选","stem":"我国市电频率是50Hz，周期是（　）","options":["0.02秒","0.2秒","2秒","50秒"],"answer":"0.02秒","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["交流电路","周期频率"],"analysis":"【审题】频率 50 Hz 求周期，T=1/f。【定律/公式】周期与频率互为倒数：T=1/f。【步骤】① 因为 T=1/f；② 因为 1/50=0.02 s；③ 因为 0.2、2、50 s 都不等于 1/50，所以 A 正确。【答案】0.02秒。【易错】×1 算成 1/50=0.2（小数点错）；×2 把 f 当 T 答 50；×3 单位写成 Hz。【口诀】周期倒数是频率，一除五十零点二不对；零点零二秒才是，单位秒来要到位。","steps":["【秒懂考点】T=1/50=0.02","【第一步】每秒50周期","【答案】0.02秒"],"pitfalls":["1/50=0.02"]});
  window.STUDY_DATA.questions.push({"id":"ne3304","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"相位差","type":"single","typeLabel":"单选","stem":"u1=sin(ωt+30°)，u2=sin(ωt-60°)，则（　）","options":["u1超前u2 90°","u1滞后u2 90°","同相","反相"],"answer":"u1超前u2 90°","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["交流电路","相位差"],"analysis":"【审题】u1=sin(ωt+30°)、u2=sin(ωt−60°)，比较相位差。【定律/公式】相位差 φ=ψ1−ψ2=30°−(−60°)=90°，u1 超前 u2 90°。【步骤】① 因为相位差=初相之差；② 因为 30−(−60)=90°>0，所以 u1 超前 u2 90°；③ 因为滞后是差为负、同相是差 0、反相是差 180°，所以 B、C、D 错误。【答案】u1超前u2 90°。【易错】×1 符号弄反答滞后；×2 减成 30−60=−30°；×3 把 90° 当成同相或反相。【口诀】相位差是初相减，三十减负六十九；正来超前负滞后，九十正交要记住。","steps":["【秒懂考点】30-(-60)=90，u1超前","【第一步】同频相减","【答案】u1超前u2 90°"],"pitfalls":["30-(-60)=90"]});
  window.STUDY_DATA.questions.push({"id":"ne3305","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"有功功率","type":"single","typeLabel":"单选","stem":"纯电阻电路中，有功功率P等于（　）","options":["UI","UIcosφ","UIsinφ","S"],"answer":"UI","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["交流电路","功率"],"analysis":"【审题】纯电阻电路中有功功率 P 等于什么，cosφ=1，P=UI。【定律/公式】有功功率 P=UI cosφ；纯电阻 φ=0，cosφ=1，故 P=UI=I²R=U²/R。【步骤】① 因为纯电阻电压电流同相，φ=0；② 因为 cos0°=1，所以 P=UI×1=UI；③ 因为 UIcosφ 是一般式（此时等于 UI）、UIsinφ 是无功、S 是视在功率，所以 A 正确。【答案】UI。【易错】×1 在纯电阻仍写 cosφ 以为要再乘；×2 与无功 UIsinφ 混淆；×3 与视在功率 S=UI 概念混（数值同但意义不同）。【口诀】纯阻有功就是 UI，因数等于一不疑；一般电路才乘 cos，无功正弦视在记。","steps":["【秒懂考点】纯电阻P=UI","【第一步】cosφ=1","【答案】UI"],"pitfalls":["纯电阻P=UI"]});
  window.STUDY_DATA.questions.push({"id":"ne3306","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"功率因数","type":"single","typeLabel":"单选","stem":"功率因数cosφ等于（　）","options":["P/S","Q/S","P/Q","S/Q"],"answer":"P/S","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["交流电路","功率因数"],"analysis":"【审题】问功率因数 cosφ 等于什么，用有功与视在功率之比定义。【定律/公式】cosφ=P/S；S=UI（视在），P=UIcosφ（有功），Q=UIsinφ（无功）。【步骤】① 因为功率因数定义为有功功率与视在功率之比；② 因为 cosφ=P/S；③ 因为 Q/S=sinφ、P/Q、S/Q 都不是功率因数定义，所以 A 正确。【答案】P/S。【易错】×1 与 sinφ=Q/S 混淆；×2 答 P/Q；×3 不知 S=UI 的含义。【口诀】功率因数 P 比 S，有功除以视在值；无功比上视在 sin，两比定义要记实。","steps":["【秒懂考点】cosφ=P/S","【第一步】无功sin","【答案】P/S"],"pitfalls":["P/S"]});
  window.STUDY_DATA.questions.push({"id":"ne3501","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电容电压相位","type":"single","typeLabel":"单选","stem":"纯电容电路中，电压相位比电流（　）","options":["超前90°","滞后90°","同相","反相"],"answer":"滞后90°","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["交流电路","相位"],"analysis":"【审题】纯电容电路中电压相位比电流如何，考查相位关系：电压滞后电流 90°。【定律/公式】纯电容：电流超前电压 90°，即电压滞后电流 90°；i=C du/dt。【步骤】① 因为电容电流与电压变化率成正比，电流相位超前电压 90°；② 所以反过来说电压比电流滞后 90°；③ 因为超前 90° 是电流对电压、同相是电阻、反相是 180°，所以 B 正确。【答案】滞后90°。【易错】×1 把“电压比电流”看成“电流比电压”答超前；×2 与纯电感（电压超前电流 90°）混淆；×3 答同相。【口诀】纯容电压滞后流，九十正交要记熟；纯感压超流九十，纯阻同相不糊涂。","steps":["【秒懂考点】电容电压滞后90","【第一步】电流超前","【答案】滞后90°"],"pitfalls":["电容电压滞后90"]});
  window.STUDY_DATA.questions.push({"id":"ne3502","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"提高功率因数","type":"single","typeLabel":"单选","stem":"感性电路提高功率因数通常（　）","options":["并联电容","串联电容","并联电感","并联电阻"],"answer":"并联电容","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["交流电路","功率因数"],"analysis":"【审题】感性电路提高功率因数的方法：并联电容。【定律/公式】感性负载电流滞后，并联电容产生超前无功，补偿感性无功，使总电流相位靠近电压，cosφ 提高。【步骤】① 因为感性电路无功为正（滞后），并联电容提供容性无功抵消；② 所以通常并联电容提高功率因数；③ 因为串联电容改变电路阻抗不用于补偿、并联电感/电阻会加重或损耗，所以 A 正确。【答案】并联电容。【易错】×1 答串联电容；×2 答并联电感（感上加感）；×3 不理解为何并联能提高功率因数。【口诀】感性并容补无功，功率因数往上冲；串容并感都不对，并阻耗能不采用。","steps":["【秒懂考点】并联电容","【第一步】抵消无功","【答案】并联电容"],"pitfalls":["并联电容"]});
  window.STUDY_DATA.questions.push({"id":"ne3602","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"无功功率","type":"single","typeLabel":"单选","stem":"无功功率单位是（　）","options":["瓦特W","乏var","伏安VA","焦耳J"],"answer":"乏var","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["交流电路","功率"],"analysis":"【审题】问无功功率单位，与有功 W、视在 VA、能量 J 区分。【定律/公式】无功功率 Q 单位：乏（var）；有功 P：瓦 W；视在 S：伏安 VA；电能：焦 J。【步骤】① 因为无功功率单位是乏 var；② 因为瓦特是有功单位，所以 A 错误；③ 因为伏安是视在、焦耳是能量，所以 C、D 错误。【答案】乏var。【易错】×1 与有功 W 混淆；×2 与视在 VA 混淆；×3 答焦耳。【口诀】无功单位叫做乏，有功瓦特视在 VA；能量焦耳要分开，三功单位记不差。","steps":["【秒懂考点】无功乏var","【第一步】有功W视在VA","【答案】乏var"],"pitfalls":["无功var"]});
  window.STUDY_DATA.questions.push({"id":"nee52","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"周期频率","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"我国市电频率是（　）","options":["50Hz","60Hz","100Hz","220Hz"],"answer":"50Hz","analysis":"【审题】问我国市电频率，再次考查 50 Hz。【定律/公式】我国市电 f=50 Hz。【步骤】① 因为我国标准频率 50 Hz；② 因为 60 Hz 是国外部分地区；③ 因为 100、220 都不是频率标准，所以 A 正确。【答案】50Hz。【易错】×1 与 60 Hz 混淆；×2 把 220 V 答成频率；×3 与 100 Hz 倍频混淆。【口诀】市电频率五十赫，周期零点零二秒；数字二二零是压，不要张冠又李戴。","source":"2027考纲补充","tags":["周期频率","考纲补充"],"steps":["【秒懂考点】50Hz","【第一步】我国","【答案】50Hz"],"pitfalls":["50Hz"]});
  window.STUDY_DATA.questions.push({"id":"nee55","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"有效值","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"正弦交流电有效值与最大值的关系是（　）","options":["U=Um/√2","U=Um·√2","U=Um/2","U=Um"],"answer":"U=Um/√2","analysis":"【审题】正弦交流有效值与最大值关系：U=Um/√2。【定律/公式】有效值 U=Um/√2≈0.707Um；Um=√2 U。【步骤】① 因为有效值按热效应定义，等于最大值除以 √2；② 因为乘 √2 是由有效值求最大值，所以 B 错误；③ 因为除 2、相等都不对，所以 A 正确。【答案】U=Um/√2。【易错】×1 把关系记反成 U=Um×√2；×2 记成 U=Um/2；×3 认为有效值等于最大值。【口诀】有效除以根号二，最大乘回根号二；二百二有效三百一最大，方向千万别弄反。","source":"2027考纲补充","tags":["有效值","考纲补充"],"steps":["【秒懂考点】U=Um/√2","【第一步】Um=√2 U","【答案】U=Um/√2"],"pitfalls":["Um/√2"]});
  window.STUDY_DATA.questions.push({"id":"nee57","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电容特性","type":"choice","typeLabel":"单选","difficulty":2,"difficultyLabel":"强化","stem":"电容在直流稳态下相当于（　）","options":["开路","短路","电阻","导线"],"answer":"开路","analysis":"【审题】电容在直流稳态下相当于什么：开路（隔直）。【定律/公式】直流稳态时电容电压不变，i=C du/dt=0，相当于开路。【步骤】① 因为直流稳态电容充电完成，电流为 0；② 所以电容相当于开路；③ 因为短路是电感直流稳态、电阻导线都不对，所以 A 正确。【答案】开路。【易错】×1 与电感直流短路混淆；×2 认为电容导通直流；×3 与电容“通交流”混淆（交流下有容抗）。【口诀】电容隔直在稳态，直流稳态像断开；电感直流像短路，交流电容才有态。","source":"2027考纲补充","tags":["电容特性","考纲补充"],"steps":["【秒懂考点】直流电容开路","【第一步】电感短路","【答案】开路"],"pitfalls":["直流电容开路"]});
  window.STUDY_DATA.questions.push({"id":"nee67","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"相位关系","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"纯电阻电路中，电压与电流相位（　）","options":["同相","反相","差 90°","差 180°"],"answer":"同相","analysis":"【审题】纯电阻电路中电压与电流相位关系：同相。【定律/公式】纯电阻 u=IR，电压电流同相位，相位差 φ=0。【步骤】① 因为电阻不产生相移；② 所以电压电流同相；③ 因为差 90° 是 L/C、反相 180° 不是电阻特性，所以 A 正确。【答案】同相。【易错】×1 与电容电感 90° 混淆；×2 答反相；×3 答差 90°。【口诀】纯阻同相零相位，电容电压滞九十；电感电压超九十，三者对照要牢记。","source":"2027考纲补充","tags":["相位关系","考纲补充"],"steps":["【秒懂考点】电阻同相","【第一步】功率因数1","【答案】同相"],"pitfalls":["电阻同相"]});
  window.STUDY_DATA.questions.push({"id":"nee84","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"三要素","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"正弦电流 i=10sin(314t+π/6)A，最大值是（　）","options":["10A","7.07A","14.14A","5A"],"answer":"10A","analysis":"【审题】i=10sin(314t+π/6) A，求最大值，直接读振幅。【定律/公式】i=Im sin(ωt+ψ)，最大值即 Im=10 A。【步骤】① 因为正弦表达式中 sin 前系数就是最大值；② 所以 Im=10 A；③ 因为 7.07 是有效值、14.14 是若 Um=10 再乘 √2 的错误、5 是再除，所以 A 正确。【答案】10A。【易错】×1 答有效值 10/√2≈7.07 A；×2 误乘 √2 得 14.14；×3 把角频率或初相当成幅值。【口诀】正弦系数是最大，十安就是幅值大；有效除根七点零七，不要乘除乱如麻。","source":"2027考纲补充","tags":["三要素","考纲补充"],"steps":["【秒懂考点】最大值10","【第一步】sin前系数","【答案】10A"],"pitfalls":["最大值10，有效7.07"]});
  window.STUDY_DATA.questions.push({"id":"ee17","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"single","stem":"理想反相放大器 R₁=10kΩ，Rf=50kΩ，ui=0.2V，则 uo=（　）","options":["1.0 V","−1.0 V","0.04 V","−0.04 V"],"answer":"−1.0 V","pitfalls":["负号别丢；1.0V是漏负号"],"difficulty":2,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"强化","tags":["运算放大器","ch-ee-4"],"explainLevel":"subject-specific","hint":"【结论】−1.0 V 【考点】运算放大器 【一步步怎么算】 ① 题目：理想反相放大器 R₁=10kΩ，Rf=50kΩ，ui=0.2V，则 uo=（ ）。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL ","analysis":"【审题】理想反相放大器：R₁=10 kΩ、Rf=50 kΩ、ui=0.2 V，求 uo，用反相比例公式。【定律/公式】反相放大器：uo=−(Rf/R₁)ui。【步骤】① 因为反相放大增益 Av=−Rf/R₁=−50/10=−5；② 因为 uo=−5×0.2=−1.0 V；③ 因为 1.0 V 少了负号、0.04 V 是除成 R₁/Rf、−0.04 V 是比例反了，所以 B 正确。【答案】−1.0 V。【易错】×1 漏负号答 1.0 V；×2 比例写成 R₁/Rf；×3 忘记乘 ui。【口诀】反相放大负阻比，五十除十是五倍；零点二乘负五倍，负一伏特","steps":["【秒懂考点】反相放大器 uo=-(Rf/R₁)ui","【第一步】Rf/R₁=50/10=5","【第二步】uo=-5×0.2=-1.0V","【第三步】反相输入，输出与输入符号相反，必须带负号","【答案】选−1.0V"]});
  window.STUDY_DATA.questions.push({"id":"ee18","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"single","stem":"同相放大器电压放大倍数为（　）","options":["−frac{Rf}{R₁}","1+frac{Rf}{R₁}","frac{R₁}{Rf}","frac{Rf}{R₁}"],"answer":"1+frac{Rf}{R₁}","pitfalls":["同相有+1，反相没有"],"difficulty":2,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"强化","tags":["运算放大器","ch-ee-4"],"accept":["1+Rf/R1","1+Rf/R₁"],"explainLevel":"subject-specific","hint":"【结论】1+(Rf)/(R₁) 【考点】运算放大器 【一步步怎么算】 ① 题目：同相放大器电压放大倍数为（ ）。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单","analysis":"【审题】问同相放大器电压放大倍数公式，与反相放大器对照。【定律/公式】同相放大器：Au=1+Rf/R₁（同相、大于 1）；反相放大器：Au=−Rf/R₁。【步骤】① 因为同相输入时虚短虚断可推出 uo=(1+Rf/R₁)ui；② 所以 Au=1+Rf/R₁；③ 因为 −Rf/R₁ 是反相、R₁/Rf 比例颠倒、Rf/R₁ 少了 1，所以 B 正确。【答案】1+frac{Rf}{R₁}。【易错】×1 与反相公式记混带负号；×2 漏掉 1；×3 比例写成 R₁/Rf。【口诀】同相增益一加比，反相才是负阻比；Rf 除以 R1 加一，正负大小要牢记。","steps":["【秒懂考点】同相放大倍数 Au=1+Rf/R₁","【第一步】同相输入，输出与输入同号","【第二步】-Rf/R₁是反相放大器的倍数","【答案】选1+Rf/R₁"]});
  window.STUDY_DATA.questions.push({"id":"ee19","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"single","stem":"理想运放工作在线性区时，虚短是指（　）","options":["u+ = u−","i+ = i− = 0","uo = 0","Rid = 0"],"answer":"u+ = u−","pitfalls":["虚短是电压等，虚断是电流零"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["运算放大器","ch-ee-4"],"explainLevel":"subject-specific","hint":"【结论】u+ = u− 【考点】运算放大器 【一步步怎么算】 ① 题目：理想运放工作在线性区时，虚短是指（ ）。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单","analysis":"【审题】理想运放线性区“虚短”指什么：u+=u−。与虚断对照。【定律/公式】虚短：两输入端电位近似相等 u+≈u−（因开环增益∞）；虚断：输入电流 i+=i−≈0。【步骤】① 因为开环增益无穷大，输出有限时差模输入近 0，故 u+=u−；② 所以虚短是电压相等；③ 因为 i+=i−=0 是虚断、uo=0 不是虚短、Rid=0 不对，所以 A 正确。【答案】u+ = u−。【易错】×1 与虚断（电流为 0）混淆；×2 认为虚短是输出为 0；×3 认为两输入端短接。【口诀】虚短电压两相等，虚断电流等于零；名称带虚并非假，线性分析常用到。","steps":["【秒懂考点】虚短：u+=u-","【第一步】理想运放线性区，两输入端电压相等","【第二步】虚断才是输入电流为0（i+=i-=0）","【答案】选u+=u−"]});
  window.STUDY_DATA.questions.push({"id":"ee21","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"single","stem":"二极管正向导通时，理想模型两端电压约为（　）","options":["0.7 V","0 V","0.3 V","∞"],"answer":"0 V","pitfalls":["0V"],"difficulty":2,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"强化","tags":["运算放大器","ch-ee-4"],"explainLevel":"subject-specific","hint":"【结论】0 V 【考点】运算放大器 【一步步怎么算】 ① 题目：二极管正向导通时，理想模型两端电压约为（ ）。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位","analysis":"【审题】二极管正向导通时理想模型两端电压约多少，注意是“理想模型”不是实际硅管。【定律/公式】理想二极管模型：导通时压降 0 V（短路）；实际硅管约 0.7 V、锗 0.3 V。【步骤】① 因为题目明确说理想模型，导通即短路，压降为 0；② 因为 0.7 V、0.3 V 是实际管压降，所以 A、C 不符题意；③ 因为 ∞ 是截止，所以 D 错误。【答案】0 V。【易错】×1 看到二极管就答 0.7 V，忽略“理想模型”；×2 与锗管 0.3 V 混淆；×3 答 ∞。【口诀】理想二极管压零，实际硅管七伏整；看清题目问模型，还是实际要分清。","steps":["【秒懂考点】理想二极管模型：导通压降0V","【第一步】理想模型把二极管当作开关，导通时电阻为0、压降为0","【第二步】0.7V是恒压降模型（硅管实际值），0.3V是锗管","【答案】选0V"]});
  window.STUDY_DATA.questions.push({"id":"ee22","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"single","stem":"NPN 三极管工作在放大区的条件是（　）","options":["发射结正偏、集电结反偏","发射结反偏、集电结正偏","两结均正偏","两结均反偏"],"answer":"发射结正偏、集电结反偏","pitfalls":["发射结正偏、集电结反偏"],"difficulty":2,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"强化","tags":["运算放大器","ch-ee-4"],"explainLevel":"subject-specific","hint":"【结论】发射结正偏、集电结反偏 【考点】运算放大器 【一步步怎么算】 ① 题目：NPN 三极管工作在放大区的条件是（ ）。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ","analysis":"【审题】NPN 三极管工作在放大区的条件：发射结正偏、集电结反偏。【定律/公式】放大区（线性区）：发射结正偏、集电结反偏；饱和区两结均正偏；截止区两结均反偏。【步骤】① 因为放大需要发射极注入载流子（发射结正偏），集电极收集（集电结反偏形成漂移）；② 所以 A 正确；③ 因为 B 是反向/截止条件、C 是饱和、D 不完整，所以均错。【答案】发射结正偏、集电结反偏。【易错】×1 与饱和（两结正偏）混淆；×2 与截止（两结反偏）混淆；×3 记成发射结反偏。【口诀】放大发射正偏集反偏，饱和两结都正偏；截止两结全反偏，三区条件要记全。","steps":["【秒懂考点】NPN放大：发射结正偏、集电结反偏","【第一步】发射结正偏让大量电子注入基区","【第二步】集电结反偏把电子拉到集电极，实现放大","【第三步】两结均正偏是饱和，两结均反偏是截止","【答案】选发射结正偏、集电结反偏"]});
  window.STUDY_DATA.questions.push({"id":"ee43","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"single","stem":"反相放大器 R1=2k，Rf=10k，放大倍数为（　）","options":["5","−5","6","−6"],"answer":"−5","pitfalls":["−5"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["运算放大器","ch-ee-4"],"explainLevel":"subject-specific","hint":"【结论】−5 【考点】运算放大器 【一步步怎么算】 ① 题目：反相放大器 R1=2k，Rf=10k，放大倍数为（ ）。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（1）计算。","analysis":"【审题】反相放大器 R1=2 k、Rf=10 k，求放大倍数，含符号。【定律/公式】反相放大：Au=−Rf/R₁=−10/2=−5。【步骤】① 因为反相放大增益为负阻比；② 因为 −10/2=−5；③ 因为 5 少负号、6 是 1+Rf/R₁、−6 是同相带负号，所以 B 正确。【答案】−5。【易错】×1 漏负号答 5；×2 用同相公式 1+Rf/R₁=6；×3 比例颠倒。【口诀】反相增益负阻比，十除二来负五倍；负号表示反相位，数值五倍要记对。","steps":["【秒懂考点】反相倍数 Au=-Rf/R1","【第一步】Au=-10/2=-5","【第二步】必须带负号；6是同相的+1形式","【答案】选−5"]});
  window.STUDY_DATA.questions.push({"id":"ee44","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"single","stem":"同相放大器 R1=2k，Rf=8k，Au=（　）","options":["4","5","−4","10"],"answer":"5","pitfalls":["5"],"difficulty":2,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"强化","tags":["运算放大器","ch-ee-4"],"explainLevel":"subject-specific","hint":"【结论】5 【考点】运算放大器 【一步步怎么算】 ① 题目：同相放大器 R1=2k，Rf=8k，Au=（ ）。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（1）计算。 ④ 注","analysis":"【审题】同相放大器 R1=2 k、Rf=8 k，求 Au。【定律/公式】同相：Au=1+Rf/R₁=1+8/2=5。【步骤】① 因为同相增益 1+Rf/R₁；② 因为 1+4=5；③ 因为 4 是只算比值、−4、10 都不对，所以 B 正确。【答案】5。【易错】×1 漏 1 答 4；×2 用反相公式带负号；×3 比例颠倒算成 1+2/8=1.25。【口诀】同相增益一加比，八除二来四加一；","steps":["【秒懂考点】同相 Au=1+Rf/R1","【第一步】Au=1+8/2=1+4=5","【第二步】4是漏加1","【答案】选5"]});
  window.STUDY_DATA.questions.push({"id":"ee45","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"single","stem":"虚断是指运放（　）","options":["输入电流为 0","输入电压为 0","输出电阻为 0","开环增益为 0"],"answer":"输入电流为 0","pitfalls":["输入电流为0"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["运算放大器","ch-ee-4"],"explainLevel":"subject-specific","hint":"【结论】输入电流为 0 【考点】运算放大器 【一步步怎么算】 ① 题目：虚断是指运放（ ）。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符","analysis":"【审题】虚断指运放什么：输入电流为 0。【定律/公式】虚断：理想运放输入电阻无穷大，i+=i−=0。【步骤】① 因为输入阻抗∞，流入输入端电流为 0；② 所以虚断是输入电流为 0；③ 因为输入电压为 0 是虚短的结果、输出电阻 0、开环增益 0 都不是虚断，所以 A 正确。【答案】输入电流为 0。【易错】×1 与虚短混淆；×2 认为虚断是断开外部电路；×3 答输出电阻为 0。【口诀】虚断电流等于零，虚短电压两相平；两虚概念分清楚，分析运放最常用。","steps":["【秒懂考点】虚断：输入电流为0","【第一步】理想运放输入电阻无穷大，电流进不去","【第二步】虚短才是输入电压相等","【答案】选输入电流为0"]});
  window.STUDY_DATA.questions.push({"id":"ee46","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"single","stem":"硅二极管导通压降约（　）","options":["0.3 V","0.7 V","1.4 V","0 V"],"answer":"0.7 V","pitfalls":["0.7V"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"基础","tags":["运算放大器","ch-ee-4"],"explainLevel":"subject-specific","hint":"【结论】0.7 V 【考点】运算放大器 【一步步怎么算】 ① 题目：硅二极管导通压降约（ ）。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与","analysis":"【审题】硅二极管导通压降约多少，实际管压降 0.7 V。【定律/公式】硅管导通压降约 0.6~0.8 V，取 0.7 V；锗 0.3 V。【步骤】① 因为硅 PN 结导通典型压降 0.7 V；② 所以 B 正确；③ 因为 0.3 V 是锗、1.4 V 是两管串联、0 V 是理想模型，所以 A、C、D 错误。【答案】0.7 V。【易错】×1 与锗 0.3 V 混淆；×2 答理想模型 0 V；×3 答两管 1.4 V。【口诀】硅管七伏锗三伏，理想模型才是零；题目问约要选七，看清材料再定音。","steps":["【秒懂考点】硅管压降0.7V","【第一步】0.3V是锗管，0V是理想模型","【答案】选0.7V"]});
  window.STUDY_DATA.questions.push({"id":"ee47","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"single","stem":"三极管放大的外部条件（　）","options":["发射结正偏，集电结反偏","两结均反偏","两结均正偏","发射结反偏"],"answer":"发射结正偏，集电结反偏","pitfalls":["发射结正偏，集电结反偏"],"difficulty":2,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"强化","tags":["运算放大器","ch-ee-4"],"explainLevel":"subject-specific","hint":"【结论】发射结正偏，集电结反偏 【考点】运算放大器 【一步步怎么算】 ① 题目：三极管放大的外部条件（ ）。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（","analysis":"【审题】三极管放大的外部条件，与前面放大区条件一致。【定律/公式】放大外部条件：发射结正偏、集电结反偏。【步骤】① 因为放大需发射结正偏注入、集电结反偏收集；② 所以 A 正确；③ 因为两结反偏是截止、两结正偏是饱和、发射结反偏不完整，所以 B、C、D 错误。【答案】发射结正偏，集电结反偏。【易错】×1 与饱和混淆；×2 与截止混淆；×3 只说一个结。【口诀】放大条件发正集反偏，饱和截止要分辨；外部偏置电压定，三区特性不改变。","steps":["【秒懂考点】放大条件：发射结正偏、集电结反偏","【第一步】正偏注入，反偏收集","【答案】选发射结正偏，集电结反偏"]});
  window.STUDY_DATA.questions.push({"id":"ee48","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"single","stem":"电压跟随器的电压增益约为（　）","options":["0","1","∞","−1"],"answer":"1","pitfalls":["1"],"difficulty":2,"source":"highfreq","typeLabel":"单选","video":"v-ee","difficultyLabel":"强化","tags":["运算放大器","ch-ee-4"],"explainLevel":"subject-specific","hint":"【结论】1 【考点】运算放大器 【一步步怎么算】 ① 题目：电压跟随器的电压增益约为（ ）。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符","analysis":"【审题】电压跟随器电压增益约多少：1。【定律/公式】电压跟随器是同相放大器 Rf=0（或 R1=∞）特例：Au=1+0=1。【步骤】① 因为跟随器输出跟随输入，电压增益为 1；② 所以 B 正确；③ 因为 0、∞、−1 都不对，所以 A、C、D 错误。【答案】1。【易错】×1 答 0；×2 与反相 −1 混淆；×3 认为跟随器无增益（电压增益是 1 不是 0）。【口诀】跟随器增益等于一，输出跟随输入走；阻抗变换用途大，隔离缓冲记心头。","steps":["【秒懂考点】电压跟随器增益=1","【第一步】输出直接跟随同相输入，Rf=0时Au=1","【第二步】输入电阻高、输出电阻低，常用作缓冲","【答案】选1"]});
  window.STUDY_DATA.questions.push({"id":"exam-ee-2026-05","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运放","type":"single","typeLabel":"单选","stem":"理想运放反相比例放大器，R1=10kΩ，Rf=50kΩ，电压放大倍数是（　）","options":["-5","5","-6","6"],"answer":"-5","difficulty":2,"difficultyLabel":"强化","source":"school","tags":["真题","2026"],"analysis":"【审题】理想运放反相比例放大器，R1=10 kΩ、Rf=50 kΩ，求电压放大倍数，含符号。【定律/公式】反相放大：Au=−Rf/R1=−50/10=−5。【步骤】① 因为反相放大增益是负的反馈电阻与输入电阻之比；② 因为 −50/10=−5；③ 因为 5 少负号、−6 是 1+Rf/R1 带负、6 是同相，所以 A 正确。【答案】-5。【易错】×1 漏负号答 5；×2 用同相公式；×3 比例颠倒。【口诀】反相放大负阻比，五十除十负五倍；负号反相要保留，数值五倍不能丢。","steps":["【秒懂考点】-(50/10)=-5","【第一步】反相不加1","【答案】-5"],"pitfalls":["-5，同相才6"]});
  window.STUDY_DATA.questions.push({"id":"ne4002","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"时间常数","type":"single","typeLabel":"单选","stem":"RC电路的时间常数τ等于（　）","options":["RC","R/C","C/R","R+C"],"answer":"RC","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["动态电路","时间常数"],"analysis":"【审题】RC 电路时间常数 τ 等于什么：RC。【定律/公式】RC 一阶电路时间常数 τ=RC（单位秒）；RL 电路 τ=L/R。【步骤】① 因为 τ=RC，反映充放电快慢；② 所以 A 正确；③ 因为 R/C、C/R、R+C 都不是时间常数公式，所以 B、C、D 错误。【答案】RC。【易错】×1 与 RL 的 L/R 混淆；×2 记成 R/C 或 C/R；×3 记成相加。【口诀】RC 时间常数积，RL 电路 L 除 R；单位都是秒来记，五倍 τ 放电完毕。","steps":["【秒懂考点】τ=RC","【第一步】乘积","【答案】RC"],"pitfalls":["τ=RC"]});
  window.STUDY_DATA.questions.push({"id":"ne5001","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管单向导电性","type":"single","typeLabel":"单选","stem":"二极管的主要特性是（　）","options":["单向导电性","放大作用","滤波作用","稳压作用"],"answer":"单向导电性","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["二极管","单向导电"],"analysis":"【审题】二极管主要特性：单向导电性。【定律/公式】二极管正偏导通、反偏截止，即单向导电；放大是三极管、滤波是电容、稳压是稳压管。【步骤】① 因为 PN 结正偏导通反偏截止；② 所以 A 正确；③ 因为放大、滤波、稳压都不是二极管主要特性，所以 B、C、D 错误。【答案】单向导电性。【易错】×1 与三极管放大混淆；×2 与稳压管混淆；×3 答滤波。【口诀】二极管单向导电，正通反截是本家；放大三极管本事，稳压滤波别安错。","steps":["【秒懂考点】二极管单向导电","【第一步】放大是三极管","【答案】单向导电性"],"pitfalls":["单向导电"]});
  window.STUDY_DATA.questions.push({"id":"ne5002","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管导通压降","type":"single","typeLabel":"单选","stem":"硅二极管正向导通时，两端压降约为（　）","options":["0V","0.3V","0.7V","1.5V"],"answer":"0.7V","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["二极管","导通压降"],"analysis":"【审题】硅二极管正向导通压降约多少，再次考查 0.7 V。【定律/公式】硅管 0.7 V、锗管 0.3 V。【步骤】① 因为硅管导通压降约 0.7 V；② 所以 C 正确；③ 因为 0 V 是理想、0.3 V 是锗、1.5 V 过大，所以 A、B、D 错误。【答案】0.7V。【易错】×1 与锗 0.3 V 混淆；×2 答理想 0 V；×3 答 1.5 V。【口诀】硅管七伏要记清，锗管三伏是兄弟；理想模型才是零，实际压降看材料。","steps":["【秒懂考点】硅0.7","【第一步】锗0.3","【答案】0.7V"],"pitfalls":["硅0.7锗0.3"]});
  window.STUDY_DATA.questions.push({"id":"ne5003","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"整流电路","type":"single","typeLabel":"单选","stem":"单相桥式整流电路中，二极管在一个周期内导通（　）","options":["180°","90°","360°","270°"],"answer":"180°","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["整流电路","桥式整流"],"analysis":"【审题】单相桥式整流，二极管在一个周期内导通多少度：180°（每管半周）。【定律/公式】桥式整流四管轮流导通，每管导通 180°（半周期），两管一组。【步骤】① 因为正半周一对管导通、负半周另一对导通，每管只导通半周；② 所以 180°；③ 因为 90°、360°、270° 都不对，所以 A 正确。【答案】180°。【易错】×1 认为一管导通全周期 360°；×2 与半波整流混淆（半波也是 180° 但只一管）；×3 答 90°。【口诀】桥式整流两管半，每管导通一百八；正负半周轮流转，全波输出波形佳。","steps":["【秒懂考点】导通180","【第一步】半周期","【答案】180°"],"pitfalls":["180°"]});
  window.STUDY_DATA.questions.push({"id":"ne5101","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管偏置","type":"single","typeLabel":"单选","stem":"二极管正向偏置是指（　）","options":["阳极接正，阴极接负","阳极接负，阴极接正","两极接同电位","两极都悬空"],"answer":"阳极接正，阴极接负","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["二极管","偏置"],"analysis":"【审题】二极管正向偏置指什么：阳极接正、阴极接负。【定律/公式】正偏：阳极（P）电位高于阴极（N）；反偏则相反。【步骤】① 因为正偏要使 PN 结内电场减弱，P 接高 N 接低；② 所以 A 正确；③ 因为阳极接负是反偏、同电位不导通、悬空无意义，所以 B、C、D 错误。【答案】阳极接正，阴极接负。【易错】×1 与反偏定义颠倒；×2 把阳极阴极认反；×3 认为同电位也算正偏。【口诀】正偏阳正阴极负，反偏正好反着来；P 高 N 低才导通，极性别装反口袋。","steps":["【秒懂考点】正偏阳极正阴极负","【第一步】阳高阴低","【答案】阳极接正，阴极接负"],"pitfalls":["阳高阴低正偏"]});
  window.STUDY_DATA.questions.push({"id":"ne5102","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"稳压管","type":"single","typeLabel":"单选","stem":"稳压管工作在什么区域？（　）","options":["正向导通区","反向击穿区","反向截止区","饱和区"],"answer":"反向击穿区","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["二极管","稳压管"],"analysis":"【审题】稳压管工作在什么区域：反向击穿区。【定律/公式】稳压二极管利用反向击穿区电压基本恒定特性稳压；正向与普通二极管相同。【步骤】① 因为反向击穿区电流变化大电压变化小，可稳压；② 所以 B 正确；③ 因为正向导通、反向截止、饱和不是稳压工作区，所以 A、C、D 错误。【答案】反向击穿区。【易错】×1 答正向导通区；×2 与反向截止混淆；×3 以为击穿就坏。【口诀】稳压管用反向击穿，电压恒定好稳压；正向如同二极管，限流电阻不能差。","steps":["【秒懂考点】稳压管反向击穿区","【第一步】配限流电阻","【答案】反向击穿区"],"pitfalls":["反向击穿区配限流"]});
  window.STUDY_DATA.questions.push({"id":"ne5202","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"滤波电路","type":"single","typeLabel":"单选","stem":"直流电源中，滤波电路的作用是（　）","options":["把交流变直流","把脉动直流变平滑","把电压升高","把电压降低"],"answer":"把脉动直流变平滑","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电源","滤波"],"analysis":"【审题】直流电源中滤波电路的作用：把脉动直流变平滑。【定律/公式】整流后是脉动直流，滤波（电容/电感）滤除交流成分，使输出平滑。【步骤】① 因为整流输出脉动大，滤波电容充放电平滑波形；② 所以 B 正确；③ 因为交流变直流是整流、升压降压是变压器，所以 A、C、D 错误。【答案】把脉动直流变平滑。【易错】×1 与整流功能混淆；×2 与变压器混淆；×3 认为滤波能稳压（稳压是稳压电路）。【口诀】整流转流滤波平，脉动直流变稳定；升压降压变压器，各司其职要分清。","steps":["【秒懂考点】滤波使平滑","【第一步】整流变直流","【答案】把脉动直流变平滑"],"pitfalls":["整流变直流，滤波变平滑"]});
  window.STUDY_DATA.questions.push({"id":"ne5301","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管反向击穿","type":"single","typeLabel":"单选","stem":"二极管反向击穿后，（　）","options":["一定损坏","只要限制电流就不一定损坏","一定恢复不了","变为导线"],"answer":"只要限制电流就不一定损坏","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["二极管","反向击穿"],"analysis":"【审题】二极管反向击穿后会怎样：只要限制电流就不一定损坏。【定律/公式】反向击穿分电击穿（可逆）与热击穿（损坏）；限流可避免热击穿。稳压管就工作在电击穿区。【步骤】① 因为电击穿若电流受限，去掉反压可恢复；② 所以 B 正确；③ 因为“一定损坏”“恢复不了”“变为导线”都过于绝对，所以 A、C、D 错误。【答案】只要限制电流就不一定损坏。【易错】×1 认为击穿必坏；×2 与热击穿混淆；×3 认为击穿后永久短路。【口诀】电击穿可逆热击穿坏，限流保护不受害；稳压管用击穿区，电流限制是关键。","steps":["【秒懂考点】限流不一定损坏","【第一步】电击穿可逆，热击穿损坏","【答案】只要限制电流就不一定损坏"],"pitfalls":["电击穿可逆"]});
  window.STUDY_DATA.questions.push({"id":"ne5302","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"稳压二极管","type":"single","typeLabel":"单选","stem":"稳压二极管工作在（　）","options":["正向导通区","反向击穿区","反向截止区","饱和区"],"answer":"反向击穿区","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["二极管","稳压管"],"analysis":"【审题】稳压二极管工作在哪个区，与反向击穿题呼应，考查稳压管的特殊工作状态。【定律/公式】稳压二极管利用反向击穿区电压基本恒定的特性实现稳压，使用时必须反向接入并串联限流电阻。【步骤】① 因为反向击穿区内电流在较大范围变化时电压几乎不变，所以适合用来稳压；② 因为稳压管正常工作就是反向击穿区，所以选反向击穿区；③ 因为正向导通区与普通二极管相同、反向截止区电流太小无法稳压、饱和区是三极管概念，所以其余选项都错。【答案】反向击穿区。【易错】×1 答正向导通区，与普通二极管混淆；×2 答反向截止区，不知击穿才能稳压；×3 与三极管饱和区概念张冠李戴。【口诀】稳压二极管反向击穿，工作区记不能混；正向截止都不稳，击穿区内压不崩。","steps":["【秒懂考点】稳压管反向击穿","【第一步】串限流","【答案】反向击穿区"],"pitfalls":["反向击穿区"]});
  window.STUDY_DATA.questions.push({"id":"ne5303","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"半波整流","type":"single","typeLabel":"单选","stem":"单相半波整流电路，输出直流电压平均值是（　）","options":["0.45U","0.9U","1.2U","1.414U"],"answer":"0.45U","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["整流电路","半波"],"analysis":"【审题】单相半波整流输出直流电压平均值与交流电压 U 的关系：0.45U。【定律/公式】半波整流：Uo=0.45U2（U2 为变压器次级有效值）；全波/桥式：Uo=0.9U2。【步骤】① 因为半波只保留半周，平均值 Uo=Um/π=√2 U/π≈0.45U；② 所以 A 正确；③ 因为 0.9U 是全波、1.2U 是电容滤波近似、1.414U 是最大值，所以 B、C、D 错误。【答案】0.45U。【易错】×1 与全波 0.9U 混淆；×2 与滤波后 1.2U 混淆；×3 与最大值 √2 U 混淆。【口诀】半波零点四五 U，全波桥式零点九；滤波电容升到一二，最大一点四一四。","steps":["【秒懂考点】半波0.45","【第一步】桥式0.9","【答案】0.45U"],"pitfalls":["半波0.45桥式0.9"]});
  window.STUDY_DATA.questions.push({"id":"ne5304","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"稳压电路","type":"single","typeLabel":"单选","stem":"直流电源中稳压电路的作用是（　）","options":["把交流变直流","让输出电压不受电网波动和负载变化影响","减小纹波","升高电压"],"answer":"让输出电压不受电网波动和负载变化影响","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电源","稳压"],"analysis":"【审题】直流电源中稳压电路的作用：让输出电压不受电网波动和负载变化影响。【定律/公式】稳压电路（稳压管/三端稳压器）在电网电压或负载变化时保持输出电压基本恒定。【步骤】① 因为整流滤波后输出仍会随电网、负载变，需要稳压；② 所以 B 正确；③ 因为交流变直流是整流、减小纹波是滤波、升压是变压器，所以 A、C、D 错误。【答案】让输出电压不受电网波动和负载变化影响。【易错】×1 与整流功能混淆；×2 与滤波混淆；×3 认为稳压就是升压。【口诀】整流转流滤波平，稳压恒定不受惊；电网负载一变化，输出电压仍稳定。","steps":["【秒懂考点】稳压使输出稳定","【第一步】滤波减纹波","【答案】让输出电压不受电网波动和负载变化影响"],"pitfalls":["稳压稳定、滤波平滑"]});
  window.STUDY_DATA.questions.push({"id":"ne5401","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管正向压降","type":"single","typeLabel":"单选","stem":"硅二极管正向导通压降约为（　）","options":["0.3V","0.7V","1.5V","0V"],"answer":"0.7V","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["二极管","正向压降"],"analysis":"【审题】硅二极管正向导通压降约多少，重复考点 0.7 V。【定律/公式】硅管 0.7 V、锗 0.3 V。【步骤】① 因为硅管导通压降约 0.7 V；② 所以 B 正确；③ 因为 0.3 V 是锗、1.5 V 过大、0 V 是理想，所以 A、C、D 错误。【答案】0.7V。【易错】×1 与锗混淆；×2 答理想 0 V；×3 答 1.5 V。【口诀】硅管七伏反复考，锗管三伏对照好；理想零伏是模型，看清题目问哪条。","steps":["【秒懂考点】硅0.7","【第一步】锗0.3","【答案】0.7V"],"pitfalls":["硅0.7锗0.3"]});
  window.STUDY_DATA.questions.push({"id":"ne5402","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"发光二极管","type":"single","typeLabel":"单选","stem":"发光二极管LED发光条件是（　）","options":["正向导通","反向击穿","加反向电压","零偏"],"answer":"正向导通","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["二极管","LED"],"analysis":"【审题】发光二极管 LED 发光条件：正向导通。【定律/公式】LED 正向导通时发光，需串限流电阻；反向不亮且易损坏。【步骤】① 因为 LED 是特殊二极管，正偏导通注入载流子复合发光；② 所以 A 正确；③ 因为反向击穿、加反压、零偏都不发光，所以 B、C、D 错误。【答案】正向导通。【易错】×1 认为加反压能亮；×2 与稳压管击穿混淆；×3 忘记串限流电阻烧管。【口诀】LED 正偏才发光，反向不亮易烧伤；串上限流电阻保，电流合适亮度强。","steps":["【秒懂考点】LED正向导通","【第一步】限流","【答案】正向导通"],"pitfalls":["正向导通"]});
  window.STUDY_DATA.questions.push({"id":"ne5501","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管反向电阻","type":"single","typeLabel":"单选","stem":"二极管反向电阻（　）","options":["很大","很小","为0","和正向一样"],"answer":"很大","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["二极管","反向电阻"],"analysis":"【审题】二极管反向电阻如何：很大。【定律/公式】二极管反偏时反向电阻很大（截止），正向电阻较小（导通）。【步骤】① 因为反偏截止，只有微小漏电流，所以反向电阻很大；② 所以 A 正确；③ 因为很小是正向、为 0 是理想导通、和正向一样不对，所以 B、C、D 错误。【答案】很大。【易错】×1 与正向电阻混淆；×2 认为反向电阻为 0；×3 认为正反一样。【口诀】反向电阻非常大，正向电阻不算大；单向导电靠这差，测量好坏用它查。","steps":["【秒懂考点】反向电阻大","【第一步】正小反大","【答案】很大"],"pitfalls":["正小反大"]});
  window.STUDY_DATA.questions.push({"id":"ne5502","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"稳压管限流电阻","type":"single","typeLabel":"单选","stem":"稳压管电路必须串联（　）","options":["限流电阻","电感","电容","二极管"],"answer":"限流电阻","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["二极管","稳压管"],"analysis":"【审题】稳压管电路必须串联什么：限流电阻。【定律/公式】稳压管工作在反向击穿区，必须串限流电阻限制电流，防止热击穿损坏。【步骤】① 因为击穿区电流过大会热损坏，串电阻限流；② 所以 A 正确；③ 因为电感、电容、二极管都不是必须串的限流元件，所以 B、C、D 错误。【答案】限流电阻。【易错】×1 忘记限流电阻直接接电源；×2 串错元件；×3 认为稳压管自身不限流。【口诀】稳压管要串限流，没有电阻易烧丢；电感电容不顶用，限流电阻不能离。","steps":["【秒懂考点】串限流电阻","【第一步】防过流","【答案】限流电阻"],"pitfalls":["限流电阻"]});
  window.STUDY_DATA.questions.push({"id":"ne5601","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"光电二极管","type":"single","typeLabel":"单选","stem":"光电二极管工作在（　）","options":["正向导通","反向偏置","零偏","饱和"],"answer":"反向偏置","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["二极管","光电"],"analysis":"【审题】光电二极管工作在什么状态：反向偏置。【定律/公式】光电二极管反偏时，光照产生光电流，反向电流随光强变化；常作光检测。【步骤】① 因为反偏使耗尽层宽，光生载流子被收集形成光电流；② 所以 B 正确；③ 因为正向导通、零偏、饱和都不是光电二极管典型工作状态，所以 A、C、D 错误。【答案】反向偏置。【易错】×1 认为正偏工作；×2 与发光二极管混淆（LED 正偏）；×3 答零偏。【口诀】光电二极管反偏用，光照生流方向明；LED 正偏才发光，一收一发要分清。","steps":["【秒懂考点】光电二极管反向","【第一步】光照生光电流","【答案】反向偏置"],"pitfalls":["LED正向光电反向"]});
  window.STUDY_DATA.questions.push({"id":"ne5602","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"稳压管稳压值","type":"single","typeLabel":"单选","stem":"稳压管2CW57的稳定电压是9V，它工作在（　）","options":["正向导通","反向击穿","正向截止","反向截止"],"answer":"反向击穿","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["二极管","稳压管"],"analysis":"【审题】稳压管 2CW57 稳定电压 9 V，工作在什么状态：反向击穿。【定律/公式】稳压管在反向击穿区稳压，稳定电压即击穿电压 9 V。【步骤】① 因为稳压值就是反向击穿电压；② 所以 B 正确；③ 因为正向导通、正向截止、反向截止都不能稳压，所以 A、C、D 错误。【答案】反向击穿。【易错】×1 答正向；×2 答反向截止；×3 不知稳定电压含义。【口诀】稳压值是击穿压，九伏稳定反向加；正向截止都不稳，击穿区内把压卡。","steps":["【秒懂考点】稳压管反向击穿","【第一步】9V，串限流","【答案】反向击穿"],"pitfalls":["反向击穿"]});
  window.STUDY_DATA.questions.push({"id":"nee101","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管特性","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"二极管最重要的特性是（　）","options":["单向导电性","双向导电性","放大作用","开关作用"],"answer":"单向导电性","analysis":"【审题】二极管最重要的特性：单向导电性。【定律/公式】二极管核心特性是单向导电（正通反截）；开关作用是应用，不是本质特性。【步骤】① 因为 PN 结单向导电是二极管根本特性；② 所以 A 正确；③ 因为双向导电不对、放大是三极管、开关是应用，所以 B、C、D 不选。【答案】单向导电性。【易错】×1 答开关作用（应用非本质）；×2 与三极管放大混淆；×3 答双向。【口诀】二极管本单向导，正通反截最重要；开关整流是应用，本质特性记得牢。","source":"2027考纲补充","tags":["二极管特性","考纲补充"],"steps":["【秒懂考点】二极管最重要特性：单向导电性","【第一步：含义】只让电流正向通过、反向截止，像单向开的门","【第二步：来源】由一个PN结构成，正偏导通、反偏截止","【第三步：排除】双向错；放大是三极管；开关是应用不是特性","【答案】选A（单向导电性）"],"pitfalls":["开关是应用不是特性；放大是三极管；二极管本质=单向导电"]});
  window.STUDY_DATA.questions.push({"id":"nee102","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管导通","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"硅二极管导通时正向压降约为（　）","options":["0.3V","0.7V","1V","0V"],"answer":"0.7V","analysis":"【审题】硅二极管导通时正向压降约为多少，高频基础参数题，注意与锗管、理想模型区分。【定律/公式】硅 PN 结正向导通压降典型值约 0.6~0.8 V，通常取 0.7 V；锗管约 0.2~0.3 V；理想二极管导通压降为 0。【步骤】① 因为硅材料 PN 结导通后两端电压基本稳定在 0.7 V 左右；② 因为选项中 0.7V 符合硅管实际参数，所以选 B；③ 因为 0.3V 是锗管压降、1V 偏大、0V 是理想模型，所以其余选项都不符合硅管实际值。【答案】0.7V。【易错】×1 与锗管 0.3 V 记混，材料不分；×2 把理想模型 0 V 当成实际压降；×3 答 1 V，没有记住硅管典型值。【口诀】硅管七伏记心间，三伏锗管是一般；理想零伏是模型，反复考查不能偏。","source":"2027考纲补充","tags":["二极管导通","考纲补充"],"steps":["【秒懂考点】硅二极管正向压降约0.7V","【第一步：含义】导通时仍有一小段电压降在二极管上","【第二步：分材料】硅管约0.7V，锗管约0.3V","【第三步：对号】题目是硅管，选0.7V","【第四步：排除】0.3V是锗管；0V是理想模型；1V非标准","【答案】选B（0.7V）"],"pitfalls":["硅0.7、锗0.3别记反；0V是理想模型"]});
  window.STUDY_DATA.questions.push({"id":"nee103","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管导通","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"锗二极管导通时正向压降约为（　）","options":["0.3V","0.7V","1V","0V"],"answer":"0.3V","analysis":"【审题】锗二极管导通正向压降约多少，与硅管对照：0.3 V。【定律/公式】锗管导通压降约 0.2~0.3 V，取 0.3 V；硅管约 0.7 V。【步骤】① 因为锗 PN 结势垒较低，导通压降约 0.3 V；② 所以 A 正确；③ 因为 0.7 V 是硅、1 V 偏大、0 V 是理想，所以 B、C、D 错误。【答案】0.3V。【易错】×1 与硅管 0.7 V 记混；×2 答理想 0 V；×3 答 1 V。【口诀】锗管三伏硅七伏，材料不同压降殊；理想零伏是模型，对照记忆不糊涂。","source":"2027考纲补充","tags":["二极管导通","考纲补充"],"steps":["【秒懂考点】锗二极管正向压降约0.3V","【第一步】压降=导通时两端电压","【第二步】按材料：锗管0.3V、硅管0.7V","【第三步】题目是锗管，选0.3V","【第四步】排除：0.7V硅管；0V理想模型；1V非标准","【答案】选A（0.3V）"],"pitfalls":["锗0.3、硅0.7；锗小硅大"]});
  window.STUDY_DATA.questions.push({"id":"nee104","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管偏置","type":"choice","typeLabel":"单选","difficulty":2,"difficultyLabel":"强化","stem":"二极管正偏是指（　）","options":["阳极接正、阴极接负","阳极接负、阴极接正","两极短接","两极悬空"],"answer":"阳极接正、阴极接负","analysis":"【审题】二极管正偏指什么：阳极接正、阴极接负。【定律/公式】正偏：阳极（P）电位高于阴极（N），PN 结导通。【步骤】① 因为正偏要让 P 区接高电位、N 区接低电位；② 所以 A 正确；③ 因为阳负阴正是反偏、短接悬空都不是偏置定义，所以 B、C、D 错误。【答案】阳极接正，阴极接负。【易错】×1 与反偏颠倒；×2 阳极阴极认反；×3 认为短接是正偏。【口诀】正偏阳正阴极负，反偏阳负阴正求；P 高 N 低才导通，极性别接反了头。","source":"2027考纲补充","tags":["二极管偏置","考纲补充"],"steps":["【秒懂考点】正偏=阳极接正、阴极接负","【第一步：认极】阳极A是三角形那头，阴极K是横杠那头","【第二步：正偏】阳极电位高于阴极，PN结导通","【第三步：反偏】阳极负阴极正，截止","【第四步：排除】阳极负阴极正是反偏；短接悬空非正常","【答案】选A（阳极接正、阴极接负）"],"pitfalls":["正偏=阳极比阴极高；顺着箭头方向导通"]});
  window.STUDY_DATA.questions.push({"id":"nee110","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"三极管类型","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"三极管有两个 PN 结，分别是（　）","options":["发射结和集电结","正极和负极","阳极和阴极","基极和发射极"],"answer":"发射结和集电结","analysis":"【审题】三极管两个 PN 结分别是什么：发射结和集电结。【定律/公式】三极管结构：发射区-基区为发射结，基区-集电区为集电结。【步骤】① 因为三极管由两个 PN 结组成，靠近发射极的叫发射结，靠近集电极的叫集电结；② 所以 A 正确；③ 因为正负极、阳阴极、基极发射极（电极名不是结名）都不对，所以 B、C、D 错误。【答案】发射结和集电结。【易错】×1 用电极名代替结名；×2 与二极管阴阳极混淆；×3 与场效应管混淆。【口诀】三极管有两 PN 结，发射结来集电结；电极三根 BCE，结与电极要区别。","source":"2027考纲补充","tags":["三极管类型","考纲补充"],"steps":["【秒懂考点】三极管两个PN结：发射结、集电结","【第一步：三个区】发射区、基区、集电区","【第二步：两个结】发射结（发射区-基区）、集电结（基区-集电区）","【第三步：三个极】发射极E、基极B、集电极C","【第四步：排除】正负极、阳阴极是二极管；基极发射极是电极不是结","【答案】选A（发射结和集电结）"],"pitfalls":["电极EBC≠PN结；两个结是发射结、集电结"]});
  window.STUDY_DATA.questions.push({"id":"nee111","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"三极管引脚","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"三极管三个电极是（　）","options":["基极 B、发射极 E、集电极 C","阳极、阴极、栅极","正极、负极、接地","输入、输出、电源"],"answer":"基极 B、发射极 E、集电极 C","analysis":"【审题】三极管三个电极是：基极 B、发射极 E、集电极 C。【定律/公式】三极管电极：基极 B（Base）、发射极 E（Emitter）、集电极 C（Collector）。【步骤】① 因为三极管引出三个电极 B、E、C；② 所以 A 正确；③ 因为阳阴栅是晶闸管/场效应、源漏栅是场效应管、输入输出电源不是电极名，所以 B、C、D 错误。【答案】基极 B、发射极 E、集电极 C。【易错】×1 与场效应管源漏栅混淆；×2 与二极管阴阳极混淆；×3 用功能名代替电极名。【口诀】三极电极 BCE，基极发射集电极；场管源漏加栅极，两种器件要分立。","source":"2027考纲补充","tags":["三极管引脚","考纲补充"],"steps":["【秒懂考点】三极管三个电极：基极B、发射极E、集电极C","【第一步：对应】发射区→E，基区→B，集电区→C","【第二步：作用】E发射、B控制、C收集","【第三步：排除】阳阴极是二极管，栅极是场效应管；其余非管脚","【答案】选A（B、E、C）"],"pitfalls":["BJT用BEC；场效应管才用GDS栅漏源"]});
  window.STUDY_DATA.questions.push({"id":"nee125","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管极性","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"二极管外壳上有色环的一端是（　）","options":["阴极","阳极","基极","发射极"],"answer":"阴极","analysis":"【审题】二极管外壳色环一端是什么极：阴极。【定律/公式】二极管色环/色点标记阴极（N 端）；发光二极管长脚为阳极。【步骤】① 因为制造时色环标在阴极端便于识别；② 所以 A 正确；③ 因为阳极是另一端、基极发射极是三极管电极，所以 B、C、D 错误。【答案】阴极。【易错】×1 认为色环是阳极；×2 与 LED 引脚长短混淆；×3 答三极管电极。【口诀】二极色环是阴极，长脚 LED 是阳极；认极先看标记端，接反电路出问题。","source":"2027考纲补充","tags":["二极管极性","考纲补充"],"steps":["【秒懂考点】色环端是阴极","【第一步】色环对应符号横杠","【答案】阴极"],"pitfalls":["阴极"]});
  window.STUDY_DATA.questions.push({"id":"nee132","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"三极管类型识别","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"箭头朝外的三极管是（　）","options":["NPN","PNP","二极管","场效应管"],"answer":"NPN","analysis":"【审题】箭头朝外的三极管是 NPN 还是 PNP：NPN。【定律/公式】三极管符号箭头在发射极：箭头朝外为 NPN，朝里为 PNP。【步骤】① 因为 NPN 发射极电流流出，符号箭头朝外；② 所以 A 正确；③ 因为 PNP 箭头朝里、二极管场效应管不是三极管，所以 B、C、D 错误。【答案】NPN。【易错】×1 与 PNP 箭头方向记反；×2 不知箭头含义；×3 与其他器件混淆。【口诀】箭头朝外 NPN，朝里就是 PNP；发射极上画箭头，电流方向看端倪。","source":"2027考纲补充","tags":["三极管类型识别","考纲补充"],"steps":["【秒懂考点】箭头朝外=NPN","【第一步】NPN发射极箭头朝外","【答案】NPN"],"pitfalls":["NPN"]});
  window.STUDY_DATA.questions.push({"id":"nee142","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"发光二极管","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"发光二极管 LED 工作时（　）","options":["正向导通","反向击穿","零偏","反偏"],"answer":"正向导通","analysis":"【审题】发光二极管 LED 工作时处于什么状态，考查 LED 的偏置与发光条件，要与光电二极管区分。【定律/公式】LED 是正偏发光器件：正向导通时注入载流子复合发光；反偏不发光且可能损坏，必须串联限流电阻。【步骤】① 因为 LED 发光需要正向电流注入，所以工作时必须正向导通；② 因为反向击穿、零偏、反偏都不能正常发光，所以其余选项错误；③ 因为 LED 本质是二极管，正向导通才形成电流并发光，所以选正向导通。【答案】正向导通。【易错】×1 与光电二极管反向偏置混淆；×2 答反向击穿，以为所有特殊二极管都工作在击穿区；×3 忘记串联限流电阻导致电流过大烧毁 LED。【口诀】LED 正偏才发光，光电反偏收光忙；一发一收正反异，限流电阻不能忘。","source":"2027考纲补充","tags":["发光二极管","考纲补充"],"steps":["【秒懂考点】LED正向导通发光","【第一步】正向偏置限流","【答案】正向导通"],"pitfalls":["正向导通"]});
  window.STUDY_DATA.questions.push({"id":"nee143","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"光电二极管","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"光电二极管工作在（　）状态。","options":["反向偏置","正向导通","零偏","饱和"],"answer":"反向偏置","analysis":"【审题】光电二极管工作在什么状态，与 LED 对照，考查光电器件的偏置方式。【定律/公式】光电二极管在反向偏置下工作：无光照时反向电流很小，有光照时产生与光强成正比的光电流。【步骤】① 因为反向偏置使耗尽层变宽，光生电子空穴对被电场收集形成光电流；② 因为正向导通、零偏、饱和都不是光电二极管的典型工作状态，所以其余选项错误；③ 因为光电二极管利用反向光电流检测光信号，所以工作在反向偏置状态。【答案】反向偏置。【易错】×1 与发光二极管 LED 正偏混淆，两者偏置相反；×2 答正向导通，不知反偏才便于光电检测；×3 答饱和，把三极管概念套到光电二极管上。【口诀】光电反偏工作用，LED 正偏才亮灯；两管用途正相反，偏置方式记心中。","source":"2027考纲补充","tags":["光电二极管","考纲补充"],"steps":["【秒懂考点】光电二极管反向偏置","【第一步】反向电流随光强变化","【答案】反向偏置"],"pitfalls":["反向偏置"]});
  window.STUDY_DATA.questions.push({"id":"ne6001","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-6","knowledgePoint":"三极管结构","type":"single","typeLabel":"单选","stem":"三极管有三个电极，分别是（　）","options":["发射极、基极、集电极","阳极、阴极、栅极","源极、漏极、栅极","正极、负极、接地极"],"answer":"发射极、基极、集电极","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["三极管","电极"],"analysis":"【审题】三极管三个电极：发射极、基极、集电极。【定律/公式】三极管电极 E、B、C。【步骤】① 因为三极管引出发射极、基极、集电极；② 所以 A 正确；③ 因为阳阴栅是其他器件、源漏栅是场效应管、正负接地不是三极管命名，所以 B、C、D 错误。【答案】发射极、基极、集电极。【易错】×1 与场效应管混淆；×2 与二极管混淆；×3 用电源极性代替电极。【口诀】三极管三极 EBC，发射基极集电极；源漏栅极是场管，名字不同要辨析。","steps":["【秒懂考点】发射基集","【第一步】源漏栅是场效应","【答案】发射极、基极、集电极"],"pitfalls":["别和场效应管混"]});
  window.STUDY_DATA.questions.push({"id":"ne6301","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-6","knowledgePoint":"三极管电流关系","type":"single","typeLabel":"单选","stem":"三极管三个电极电流关系正确的是（　）","options":["IE = IB + IC","IB = IC + IE","IC = IB + IE","IE = IB = IC"],"answer":"IE = IB + IC","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["三极管","电流关系"],"analysis":"【审题】三极管三个电极电流关系：IE=IB+IC。【定律/公式】基尔霍夫应用于三极管：IE=IB+IC（发射极电流=基极电流+集电极电流）；IC=βIB。【步骤】① 因为电流从发射极流出等于基极与集电极电流之和（NPN）；② 所以 A 正确；③ 因为 B、C 关系颠倒、D 三者相等不对，所以 B、C、D 错误。【答案】IE = IB + IC。【易错】×1 记成 IC=IB+IE；×2 记成 IB=IC+IE；×3 认为三者相等。【口诀】发射电流等于和，IE 等于 IB 加 IC；基流很小集流大，电流关系记准确。","steps":["【秒懂考点】IE=IB+IC","【第一步】IB最小","【答案】IE = IB + IC"],"pitfalls":["IE=IB+IC"]});
  window.STUDY_DATA.questions.push({"id":"ne6302","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-6","knowledgePoint":"放大倍数","type":"single","typeLabel":"单选","stem":"三极管电流放大系数β等于（　）","options":["IC / IB","IB / IC","IE / IB","IC / IE"],"answer":"IC / IB","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["三极管","放大倍数"],"analysis":"【审题】三极管电流放大系数 β 等于什么，用集电极电流与基极电流之比定义。【定律/公式】β=IC/IB（共射电流放大系数）；IE=IB+IC≈IC（β 较大时）。【步骤】① 因为 β 表示基极电流对集电极电流的控制能力；② 因为 β=IC/IB；③ 因为 IB/IC 是倒数、IE/IB、IC/IE 都不是 β 定义，所以 A 正确。【答案】IC / IB。【易错】×1 分子分母颠倒；×2 用 IE 代替 IC；×3 与 α=IC/IE 混淆。【口诀】贝塔等于 IC 除 IB，放大能力看它大；阿尔法是 IC 除 IE，两个系数要分家。","steps":["【秒懂考点】β=IC/IB","【第一步】α=IC/IE","【答案】IC / IB"],"pitfalls":["β=IC/IB，α=IC/IE"]});
  window.STUDY_DATA.questions.push({"id":"ne6401","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-6","knowledgePoint":"三极管类型","type":"single","typeLabel":"单选","stem":"NPN型三极管发射区掺杂的是（　）","options":["N型半导体","P型半导体","本征半导体","绝缘材料"],"answer":"N型半导体","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["三极管","结构"],"analysis":"【审题】NPN 型三极管发射区掺杂什么：N 型半导体。【定律/公式】NPN：发射区 N、基区 P、集电区 N；PNP 则相反。发射区掺杂浓度最高。【步骤】① 因为 NPN 的发射区是 N 型，所以 A 正确；② 因为 P 型是基区材料，所以 B 错误；③ 因为本征半导体、绝缘材料不是发射区掺杂类型，所以 C、D 错误。【答案】N型半导体。【易错】×1 与 PNP 混淆；×2 把基区 P 型当成发射区；×3 不知 NPN 命名含义（N-P-N 结构）。【口诀】NPN 发射是 N 区，基区 P 来集 N 区；PNP 三区正相反，命名顺序记心里。","steps":["【秒懂考点】NPN发射区N型","【第一步】N-P-N","【答案】N型半导体"],"pitfalls":["基区P型"]});
  window.STUDY_DATA.questions.push({"id":"ne7001","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"理想运放参数","type":"single","typeLabel":"单选","stem":"理想运放的输入电阻为（　）","options":["0","无穷大","1kΩ","100Ω"],"answer":"无穷大","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["运放","理想参数"],"analysis":"【审题】理想运放输入电阻为多少：无穷大。【定律/公式】理想运放：输入电阻 Rid=∞，输出电阻 Ro=0，开环增益 Auo=∞，带宽∞。【步骤】① 因为理想运放输入不取电流，输入电阻无穷大；② 所以 B 正确；③ 因为 0 是输出电阻、1 kΩ/100 Ω 是实际有限值，所以 A、C、D 错误。【答案】无穷大。【易错】×1 与输出电阻 0 混淆；×2 答 0；×3 用实际运放参数代替理想。【口诀】理想运放输入阻抗无穷大，输出电阻等于零；增益无穷带宽宽，四条理想要记清。","steps":["【秒懂考点】输入电阻∞","【第一步】虚断","【答案】无穷大"],"pitfalls":["输入电阻∞"]});
  window.STUDY_DATA.questions.push({"id":"ne7002","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"反相放大器","type":"single","typeLabel":"单选","stem":"反相比例运算电路中，已知R1=10kΩ，Rf=100kΩ，则电压放大倍数为（　）","options":["10","-10","11","-11"],"answer":"-10","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["运放","反相放大"],"analysis":"【审题】反相比例电路 R1=10 kΩ、Rf=100 kΩ，求电压放大倍数，含符号。【定律/公式】反相：Au=−Rf/R1=−100/10=−10。【步骤】① 因为反相放大增益为负阻比；② 因为 −100/10=−10；③ 因为 10 少负号、11 是 1+Rf/R1、−11 是同相带负，所以 B 正确。【答案】-10。【易错】×1 漏负号；×2 用同相公式；×3 比例颠倒。【口诀】反相增益负阻比，一百除十负十倍；负号别丢要牢记，同相才是一加比。","steps":["【秒懂考点】-(100/10)=-10","【第一步】反相不加1","【答案】-10"],"pitfalls":["反相Rf/R1，同相1+"]});
  window.STUDY_DATA.questions.push({"id":"ne7003","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"电压跟随器","type":"single","typeLabel":"单选","stem":"电压跟随器的电压放大倍数为（　）","options":["0","1","-1","无穷大"],"answer":"1","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["运放","电压跟随器"],"analysis":"【审题】电压跟随器的电压放大倍数是多少，考查同相放大器的特例：输出与输入相等，增益为 1。【定律/公式】电压跟随器是同相放大器 Rf=0（或反馈短接）的特例，Au=1+Rf/R1=1，输出电压等于输入电压。【步骤】① 因为跟随器输出端直接反馈到反相端，输出完全跟随输入；② 因为电压放大倍数 uo/ui=1，所以增益为 1；③ 因为 0 表示无输出、−1 是反相放大、无穷大是理想运放开环增益，所以其余选项都不符合跟随器。【答案】1。【易错】×1 答 0，误以为跟随就是没有增益；×2 与反相放大器增益 −1 混淆；×3 答无穷大，把开环增益当闭环增益。【口诀】跟随器增益等于一，输出跟随不偏移；缓冲隔离阻抗变，电压增益就是一。","steps":["【秒懂考点】Au=1","【第一步】跟随","【答案】1"],"pitfalls":["1"]});
  window.STUDY_DATA.questions.push({"id":"ne7102","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"电压比较器","type":"single","typeLabel":"单选","stem":"电压比较器工作在运放的什么区域？（　）","options":["线性区","非线性区","饱和区","截止区"],"answer":"非线性区","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["运放","电压比较器"],"analysis":"【审题】电压比较器工作在运放什么区域：非线性区。【定律/公式】比较器开环（或正反馈）工作，输出饱和到电源轨，属于非线性区；比例运算才在线性区。【步骤】① 因为比较器输出只有高/低两种饱和值，不满足线性比例；② 所以 B 正确；③ 因为线性区是放大电路、饱和区/截止区是三极管说法，所以 A、C、D 错误。【答案】非线性区。【易错】×1 与线性区放大器混淆；×2 用三极管饱和截止名词；×3 认为比较器也线性放大。【口诀】比较器在非线性区，输出饱和高低出；比例运放在线性，虚短虚断才可用。","steps":["【秒懂考点】比较器非线性","【第一步】开环两态","【答案】非线性区"],"pitfalls":["非线性"]});
  window.STUDY_DATA.questions.push({"id":"ne7201","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"反相放大器","type":"single","typeLabel":"单选","stem":"反相比例运算电路，R1=10kΩ，Rf=50kΩ，ui=0.2V，输出uo为（　）","options":["-1V","1V","-0.5V","0.5V"],"answer":"-1V","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["运放","反相放大"],"analysis":"【审题】反相运算 R1=10 k、Rf=50 k、ui=0.2 V，求 uo。【定律/公式】uo=−(Rf/R1)ui=−5×0.2=−1 V。【步骤】① 因为增益 Av=−50/10=−5；② 因为 uo=−5×0.2=−1 V；③ 因为 1 V 少负号、−0.5 V 比例反了、0.5 V 都不对，所以 A 正确。【答案】-1V。【易错】×1 漏负号；×2 比例算成 R1/Rf；×3 忘乘 ui。【口诀】反相五倍零点二，输出负一伏特齐；负号阻比都要对，计算三步不离题。","steps":["【秒懂考点】Uo=-5×0.2=-1","【第一步】50/10=5带负","【答案】-1V"],"pitfalls":["带负号-1"]});
  window.STUDY_DATA.questions.push({"id":"ne7202","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"同相放大器","type":"single","typeLabel":"单选","stem":"同相比例运算电路，R1=10kΩ，Rf=40kΩ，电压放大倍数是（　）","options":["4","5","-4","-5"],"answer":"5","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["运放","同相放大"],"analysis":"【审题】同相比例运算电路，R1=10 kΩ、Rf=40 kΩ，求电压放大倍数，注意同相公式带 1 且为正。【定律/公式】同相放大器：Au=1+Rf/R1，本题为 1+40/10=5。【步骤】① 因为同相输入时输出与输入同相，增益等于 1 加上反馈电阻与接地电阻之比；② 因为 1+40/10=1+4=5，所以放大倍数为 5；③ 因为 4 是漏加 1、负号选项是反相放大公式，所以都不选，正确【答案】5。【易错】×1 漏掉 1 只算 Rf/R1 得 4；×2 与反相放大公式混淆带上负号；×3 把 R1 与 Rf 位置颠倒算成 1+10/40=1.25。【口诀】同相增益一加比，四十除十再加一；","steps":["【秒懂考点】Au=1+4=5","【第一步】别漏+1","【答案】5"],"pitfalls":["别漏+1"]});
  window.STUDY_DATA.questions.push({"id":"ne7301","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"运放虚短","type":"single","typeLabel":"单选","stem":"理想运放工作在线性区时，同相端和反相端电压相等，称为（　）","options":["虚短","虚断","虚地","虚接"],"answer":"虚短","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["运放","虚短虚断"],"analysis":"【审题】同相端和反相端电压相等称为什么：虚短。【定律/公式】虚短：u+=u−（线性区、深度负反馈）。【步骤】① 因为两输入端电位近似相等如同短接，故称虚短；② 所以 A 正确；③ 因为虚断是电流 0、虚地是反相接地特例、虚接不是标准术语，所以 B、C、D 不选。【答案】虚短。【易错】×1 与虚断混淆；×2 与虚地混淆（虚地是虚短特例）；×3 认为真的短接。【口诀】虚短电压两相等，虚断电流等于零；虚地反相接地特，三个概念要分清。","steps":["【秒懂考点】U+=U-=虚短","【第一步】虚断是电流0","【答案】虚短"],"pitfalls":["虚短电压等"]});
  window.STUDY_DATA.questions.push({"id":"ne7302","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"运放虚断","type":"single","typeLabel":"单选","stem":"理想运放输入电流为0，称为（　）","options":["虚短","虚断","虚地","虚接"],"answer":"虚断","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["运放","虚短虚断"],"analysis":"【审题】理想运放输入电流为 0 称为什么概念，与虚短对照，考查虚断的定义。【定律/公式】虚断：理想运放输入电阻无穷大，故两输入端电流 i+=i−=0，如同断开一样，但并非真的断开。【步骤】① 因为理想运放输入阻抗无穷大，流入输入端的电流为零；② 因为这一现象称为虚断，所以选虚断；③ 因为虚短指两输入端电压相等、虚地是反相端接地的特例、虚接不是规范术语，所以其余选项都不对。【答案】虚断。【易错】×1 与虚短概念混淆，把电压相等当电流为零；×2 与虚地混淆，虚地只是反相放大器的特例；×3 认为输入端真的物理断开，其实只是电流近似为零。【口诀】虚断电流等于零，虚短电压两相平；名称带虚实为特性，分析运放最常用。","steps":["【秒懂考点】输入电流0=虚断","【第一步】虚短电压等","【答案】虚断"],"pitfalls":["虚断电流零"]});
  window.STUDY_DATA.questions.push({"id":"ne7304","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"电压跟随器","type":"single","typeLabel":"单选","stem":"电压跟随器的电压放大倍数是（　）","options":["1","0","-1","无穷大"],"answer":"1","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["运放","跟随器"],"analysis":"【审题】电压跟随器的电压放大倍数是多少，再次考查同相特例增益为 1。【定律/公式】电压跟随器：uo=ui，Au=1，输入电阻高、输出电阻低。【步骤】① 因为跟随器输出端反馈到反相端，输出跟随输入；② 因为电压放大倍数等于 1，所以选 A；③ 因为 0 表示无输出、−1 是反相、无穷大是开环增益，所以 B、C、D 都错。【答案】1。【易错】×1 答 0；×2 与反相 −1 混淆；×3 答无穷大。【口诀】跟随增益等于一，输出跟随不偏移；阻抗变换用途大，隔离缓冲记心里。","steps":["【秒懂考点】Au=1","【第一步】跟随","【答案】1"],"pitfalls":["Au=1"]});
  window.STUDY_DATA.questions.push({"id":"ne7401","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"积分电路","type":"single","typeLabel":"单选","stem":"积分运算电路反馈元件是（　）","options":["电阻","电容","电感","二极管"],"answer":"电容","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["运放","积分电路"],"analysis":"【审题】积分运算电路的反馈元件是什么：电容。【定律/公式】反相积分器：反馈支路用电容 C，uo=−(1/R1C)∫ui dt；微分器反馈用 R、输入用 C。【步骤】① 因为积分是对电流累积成电压，电容电压与电流积分成正比；② 因为反馈元件要用电容，所以 B 正确；③ 因为电阻是比例反馈、电感二极管不是积分反馈，所以 A、C、D 错误。【答案】电容。【易错】×1 与比例运算（反馈电阻）混淆；×2 与微分电路元件搞反；×3 答电感。【口诀】积分反馈要用电容，微分输入才用电容；比例反馈是电阻，三种电路记清楚。","steps":["【秒懂考点】积分反馈电容","【第一步】微分反馈电阻","【答案】电容"],"pitfalls":["电容做积分"]});
  window.STUDY_DATA.questions.push({"id":"ne7501","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"反相比例","type":"single","typeLabel":"单选","stem":"反相比例运算电路输入电阻（　）","options":["高","低","为0","无穷大"],"answer":"低","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["运放","反相比例"],"analysis":"【审题】反相比例运算电路输入电阻如何：低。【定律/公式】反相放大器输入电阻近似等于 R1（反相端虚地），故不高；同相放大器输入电阻才高。【步骤】① 因为反相端虚地，输入电流 ui/R1，输入电阻≈R1；② 因为 R1 通常不大，所以输入电阻低；③ 因为高是同相电路特点、为 0 是短路、无穷大是理想运放自身输入电阻，所以 A、C、D 不选。【答案】低。【易错】×1 与同相放大器输入电阻高混淆；×2 认为运放输入电阻无穷大所以电路也高；×3 答 0。【口诀】反相输入电阻低，约等 R1 虚地起；同相输入才很高，两电路要对比记。","steps":["【秒懂考点】反相输入电阻低","【第一步】同相才高","【答案】低"],"pitfalls":["同相才高"]});
  window.STUDY_DATA.questions.push({"id":"ne7502","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"差分运算","type":"single","typeLabel":"单选","stem":"差分运算电路输出与两个输入的（　）成正比","options":["差","和","积","商"],"answer":"差","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["运放","差分"],"analysis":"【审题】差分运算电路输出与两个输入的什么成正比：差。【定律/公式】差分放大：uo=A(u2−u1)，输出与两输入之差成正比，抑制共模。【步骤】① 因为差分电路放大两输入之差；② 所以输出与差成正比；③ 因为和是同相加法、积商都不是模拟运算基本功能，所以 B、C、D 错误。【答案】差。【易错】×1 答和；×2 与加法器混淆；×3 不知差分含义。【口诀】差分输出比差值，两入相减再放大；同相加法求和用，差放共模能压下。","steps":["【秒懂考点】差分=差","【第一步】Uo=Ad(u+-u-)","【答案】差"],"pitfalls":["放大差值"]});
  window.STUDY_DATA.questions.push({"id":"ne7601","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"运放电源","type":"single","typeLabel":"单选","stem":"集成运放工作需要（　）电源","options":["双极性","单极性","不需要","高压"],"answer":"双极性","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["运放","电源"],"analysis":"【审题】集成运放工作需要什么电源：双极性（正负双电源）。【定律/公式】集成运放通常需正负双电源（如 ±12 V），以便输出能正能负；也有单电源运放但需偏置。【步骤】① 因为运放要放大交流或双极性信号，需正负电源；② 所以 A 正确；③ 因为单极性、不需要、高压都不是标准要求，所以 B、C、D 错误。【答案】双极性。【易错】×1 答单极性；×2 认为不需要电源；×3 认为必须高压。【口诀】运放常用双电源，正负对称输出强；单电源要加偏置，供电极性别装反。","steps":["【秒懂考点】运放双极性电源","【第一步】±15V","【答案】双极性"],"pitfalls":["正负双电源"]});
  window.STUDY_DATA.questions.push({"id":"nee166","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"逻辑代数","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"逻辑代数中 1+1=（　）","options":["0","1","2","10"],"answer":"1","analysis":"【审题】逻辑代数中 1+1=？注意是逻辑或不是算术加法。【定律/公式】逻辑或：1+1=1（有 1 出 1）。【步骤】① 因为或运算有 1 出 1，两个 1 相或仍为 1；② 所以 B 正确；③ 因为 0 不对、2 是算术、10 是二进制误读，所以 A、C、D 错误。【答案】1。【易错】×1 按算术算成 2；×2 答 0；×3 把二进制 10 当结果。【口诀】逻辑加法一加一，结果还是一不疑；算术才是等于二，逻辑或运算记心里。","source":"2027考纲补充","tags":["逻辑代数","考纲补充"],"steps":["【秒懂考点】逻辑或1+1=1","【第一步】或是非算术，不进位","【第二步】1或1=1","【答案】1"],"pitfalls":["逻辑或1+1=1不是2"]});
  window.STUDY_DATA.questions.push({"id":"nee167","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"逻辑代数","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"逻辑代数中 1·1=（　）","options":["0","1","2","11"],"answer":"1","analysis":"【审题】逻辑代数中 1·1=？逻辑与运算。【定律/公式】逻辑与：1·1=1（全 1 出 1）。【步骤】① 因为与运算全 1 出 1；② 所以 B 正确；③ 因为 0、2、11 都不是逻辑结果，所以 A、C、D 错误。【答案】1。【易错】×1 答 0；×2 算术想成 1 结果虽对但原理要记逻辑；×3 把 11 当二进制结果。【口诀】逻辑乘法一乘一，结果是一没问题；全 1 出 1 要牢记，算术巧合莫当真。","source":"2027考纲补充","tags":["逻辑代数","考纲补充"],"steps":["【秒懂考点】逻辑与1·1=1","【第一步】全1才1","【答案】1"],"pitfalls":["与全1才1"]});
  window.STUDY_DATA.questions.push({"id":"nee168","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"逻辑代数","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"逻辑代数中 A·0=（　）","options":["0","1","A","A̅"],"answer":"0","analysis":"【审题】逻辑代数中 A·0 等于什么，考查与运算的支配律（0-1 律），注意逻辑乘法不是算术乘法。【定律/公式】与运算：A·0=0，表示只要有一个输入为 0，与的结果就是 0；类似地 A·1=A，A·Ā=0。【步骤】① 因为与运算规则是全 1 出 1、有 0 出 0，所以 A 与 0 相与时结果必为 0；② 因为不论 A 取 0 还是 1，A·0 的结果都是 0，所以③ 因为 1 是 A·1 或 A+Ā 的结果、A 是 A·1、Ā 是非运算结果，所以其余选项都不对。【答案】0。【易错】×1 与 A+0=A 混淆，把或运算结果当成与运算；×2 与 A·1=A 混淆，记错支配元素；×3 按算术思维以为结果是 A 或 0A，不理解逻辑运算只有 0 和 1。【口诀】A 乘零来恒为零，有零出零记心中；A 加零来才是 A，与或公式要分清。","source":"2027考纲补充","tags":["逻辑代数","考纲补充"],"steps":["【秒懂考点】A·0=0","【第一步】有0相与必0","【答案】0"],"pitfalls":["与任何量乘0得0"]});
  window.STUDY_DATA.questions.push({"id":"nee169","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"逻辑代数","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"逻辑代数中 A+0=（　）","options":["0","1","A","A̅"],"answer":"A","analysis":"【审题】逻辑代数中 A+0=？或运算单位元。【定律/公式】A+0=A（全 0 出 0 时看 A）。【步骤】① 因为或运算有 1 出 1、全 0 出 0，A+0 结果就是 A；② 所以 C 正确；③ 因为 0、1、Ā 都不对，所以 A、B、D 错误。【答案】A。【易错】×1 与 A+1=1 混淆；×2 与 A·0=0 混淆；×3 答 0 或 1。【口诀】A 加零来仍是 A，或零不改它本身；A 加一来才是一，两式对照记忆深。","source":"2027考纲补充","tags":["逻辑代数","考纲补充"],"steps":["【秒懂考点】A+0=A","【第一步】或中0不改变结果","【答案】A"],"pitfalls":["或加0不变，与乘0归零"]});
  window.STUDY_DATA.questions.push({"id":"nee170","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"逻辑代数","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"逻辑代数中 A+A̅=（　）","options":["0","1","A","A̅"],"answer":"1","analysis":"【审题】逻辑代数中 A+Ā 等于什么，考查互补律：互补变量相或得 1。【定律/公式】互补律：A+Ā=1，A·Ā=0。因为 A 与非 A 中必有一个为 1，所以相或为 1，相与为 0。【步骤】① 因为 A 与 Ā 是互补变量，取值总是相反；② 因为 A=0 时 Ā=1，A=1 时 Ā=0，所以 A+Ā 恒为 1；③ 因为 0 是 A·Ā 的结果、A 与 Ā 都只是单个变量，所以其余选项都不对。【答案】1。【易错】×1 与 A·Ā=0 混淆，把相与当成相或；×2 答 A，忘记互补相或覆盖全部取值；×3 答 0，把互补相与的结果搬过来。【口诀】A 加非 A 恒为一，互补相或是规律；A 乘非 A 恒为零，两条互补要牢记。","source":"2027考纲补充","tags":["逻辑代数","考纲补充"],"steps":["【秒懂考点】A+A̅=1","【第一步】互补必有一个1","【答案】1"],"pitfalls":["互补相或=1"]});
  window.STUDY_DATA.questions.push({"id":"nee171","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"逻辑代数","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"逻辑代数中 A·A̅=（　）","options":["0","1","A","A̅"],"answer":"0","analysis":"【审题】逻辑代数中 A·Ā 等于什么，考查互补律的与运算形式。【定律/公式】互补律：A·Ā=0（互补相与为 0）；A+Ā=1。因为 A 与非 A 不可能同时为 1。【步骤】① 因为 A 与 Ā 取值总是相反，不可能同时为 1，所以与的结果恒为 0；② 因为不论 A=0 还是 A=1，A·Ā 都等于 0，所以③ 因为 1 是 A+Ā 的结果、A 与 Ā 都是单个变量，所以其余选项都不对。【答案】0。【易错】×1 与 A+Ā=1 混淆，把或运算当与运算；×2 答 A 或 Ā，忘记互补相与必为 0；×3 按算术想成 A²。【口诀】A 乘非 A 恒为零，互补相与不可能；A 加非 A 恒为一，两条互补要记清。","source":"2027考纲补充","tags":["逻辑代数","考纲补充"],"steps":["【秒懂考点】A·A̅=0","【第一步】互补不可能同时1","【答案】0"],"pitfalls":["A+A̅=1、A·A̅=0"]});
  window.STUDY_DATA.questions.push({"id":"nee172","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"与门","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"与门逻辑表达式是（　）","options":["Y=A·B","Y=A+B","Y=A̅","Y=A⊕B"],"answer":"Y=A·B","analysis":"【审题】与门逻辑表达式是什么，考查基本门的代数形式。【定律/公式】与门：Y=A·B（或写成 Y=AB）；或门 Y=A+B；非门 Y=Ā；异或 Y=A⊕B。【步骤】① 因为与门实现逻辑乘，输出等于两输入相与；② 因为 Y=A·B 是与门表达式，所以 A 正确；③ 因为 A+B 是或门、Ā 是非门、A⊕B 是异或门，所以 B、C、D 都错。【答案】Y=A·B。【易错】×1 与或门 A+B 混淆；×2 与非门 Ā 混淆；×3 与异或混淆。【口诀】与门相乘 A 点 B，或门相加 A 加 B；非门取反带上划，异或半加符号奇。","source":"2027考纲补充","tags":["与门","考纲补充"],"steps":["【秒懂考点】与门Y=A·B","【第一步】全1才1，逻辑乘","【第二步】排除或门、非门、异或","【答案】Y=A·B"],"pitfalls":["与门·、或门+、非门取反"]});
  window.STUDY_DATA.questions.push({"id":"nee173","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"或门","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"或门逻辑表达式是（　）","options":["Y=A·B","Y=A+B","Y=A̅","Y=A⊕B"],"answer":"Y=A+B","analysis":"【审题】或门逻辑表达式是什么，与与门对照。【定律/公式】或门：Y=A+B；与门 Y=A·B。【步骤】① 因为或门实现逻辑加，有 1 出 1；② 因为 Y=A+B 是或门表达式，所以 B 正确；③ 因为 A·B 是与门、Ā 是非门、A⊕B 是异或，所以 A、C、D 错误。【答案】Y=A+B。【易错】×1 与与门混淆；×2 与非门混淆；×3 与异或混淆。【口诀】或门相加 A 加 B，与门相乘点出来；两个表达式要分清，真值表格对起来。","source":"2027考纲补充","tags":["或门","考纲补充"],"steps":["【秒懂考点】或门Y=A+B","【第一步】有1即1，逻辑加","【答案】Y=A+B"],"pitfalls":["或门+、与门·"]});
  window.STUDY_DATA.questions.push({"id":"nee174","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"非门","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"非门逻辑功能是（　）","options":["取反","相乘","相加","比较"],"answer":"取反","analysis":"【审题】非门逻辑功能是什么：取反。【定律/公式】非门：Y=Ā，入 1 出 0、入 0 出 1，实现取反。【步骤】① 因为非门输出与输入相反；② 所以功能是取反，A 正确；③ 因为相乘是与门、相加是或门、比较不是基本门功能，所以 B、C、D 错误。【答案】取反。【易错】×1 与与门或门混淆；×2 认为非门能相加相乘；×3 答比较。【口诀】非门取反最简单，入一出零入零翻；与或非是三基本，功能不同要分摊。","source":"2027考纲补充","tags":["非门","考纲补充"],"steps":["【秒懂考点】非门取反","【第一步】输出=输入的反，Y=A̅","【第二步】相乘是与、相加是或","【答案】取反"],"pitfalls":["非门取反，一输入"]});
  window.STUDY_DATA.questions.push({"id":"nee175","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"与非门","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"与非门输出低电平的条件是（　）","options":["全输入 1","任一输入 1","全输入 0","任一输入 0"],"answer":"全输入 1","analysis":"【审题】与非门输出低电平的条件是什么：全输入 1。【定律/公式】与非门：Y=¬(A·B)，全 1 时与结果为 1，取反出 0（低电平）；有 0 时与为 0，取反出 1。【步骤】① 因为与非门先与后非，全 1 时与为 1，非后为 0；② 所以输出低电平的条件是全输入 1；③ 因为任一输入 1 不一定全 1、全 0 时输出高、任一输入 0 时输出高，所以其余选项不对。【答案】全输入 1。【易错】×1 与与门全 1 出 1 混淆后答错电平；×2 与或非门条件混淆；×3 记反成全 0 出低。【口诀】与非全一方出零，有零出一要记清；与门全一才出一，非门取反加一程。","source":"2027考纲补充","tags":["与非门","考纲补充"],"steps":["【秒懂考点】与非全1出0","【第一步】先与后非","【第二步】全1相与=1，取反=0","【答案】全输入1"],"pitfalls":["与非有0出1、全1出0"]});
  window.STUDY_DATA.questions.push({"id":"nee176","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"或非门","type":"choice","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"或非门输出低电平的条件是（　）","options":["全输入 0","任一输入 1","全输入 1","任一输入 0"],"answer":"任一输入 1","analysis":"【审题】或非门输出低电平的条件：任一输入 1。【定律/公式】或非门：Y=¬(A+B)，有 1 时或为 1，非后为 0；全 0 时或为 0，非后为 1。【步骤】① 因为或非门先或后非，任一输入为 1 则或为 1，输出 0；② 所以输出低电平条件是任一输入 1；③ 因为全 0 输出高、全 1 输出低但不如“任一 1”准确（全 1 也是任一 1 的特例）、任一 0 不一定，所以 B 最准确。【答案】任一输入 1。【易错】×1 与或门有 1 出 1 混淆电平；×2 与与非门条件混淆；×3 答全 0（那是输出高）。【口诀】或非有 1 就出零，全零才出一电平；与非全一方出零，两门条件对照明。","source":"2027考纲补充","tags":["或非门","考纲补充"],"steps":["【秒懂考点】或非任一1出0","【第一步】先或后非","【第二步】任一1相或=1，取反=0","【答案】任一输入1"],"pitfalls":["或非有1出0、全0出1"]});
  window.STUDY_DATA.questions.push({"id":"ne8001","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-8","knowledgePoint":"基本逻辑门","type":"single","typeLabel":"单选","stem":"只有当输入全为1时，输出才为1的逻辑门是（　）","options":["与门","或门","非门","异或门"],"answer":"与门","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["门电路","与门"],"analysis":"【审题】只有输入全为 1 输出才为 1 的逻辑门是哪个：与门。【定律/公式】与门真值表：全 1 出 1，有 0 出 0。【步骤】① 因为与门要求所有输入同时为 1；② 所以 A 正确；③ 因为或门有 1 即出 1、非门取反、异或相同出 0，所以 B、C、D 错误。【答案】与门。【易错】×1 与或门混淆；×2 与异或混淆；×3 与非门取反后电平搞错。【口诀】与门全一方出一，或门有 1 就出一；非门取反异或奇，四门功能要牢记。","steps":["【秒懂考点】全1才1=与门","【第一步】或有1即1","【答案】与门"],"pitfalls":["与全1出1"]});
  window.STUDY_DATA.questions.push({"id":"ne8002","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-8","knowledgePoint":"逻辑代数","type":"single","typeLabel":"单选","stem":"逻辑代数中，A + A = （　）","options":["A","2A","A²","0"],"answer":"A","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["逻辑代数","基本公式"],"analysis":"【审题】逻辑代数中 A+A=？幂等律，与算术加法区分。【定律/公式】逻辑或幂等律：A+A=A；算术才会 2A。【步骤】① 因为或运算有 1 出 1，A 或 A 仍是 A；② 所以 A 正确；③ 因为 2A 是算术、A² 是与或误乘、0 不对，所以 B、C、D 错误。【答案】A。【易错】×1 算术思维答 2A；×2 答 A²；×3 答 0。【口诀】A 加 A 来仍是 A，幂等律记不难；不是算术得二 A，逻辑或加一样般。","steps":["【秒懂考点】A+A=A","【第一步】重叠律非2A","【答案】A"],"pitfalls":["重叠律A+A=A"]});
  window.STUDY_DATA.questions.push({"id":"ne8101","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-8","knowledgePoint":"或门","type":"single","typeLabel":"单选","stem":"或门的逻辑功能是（　）","options":["全1出1，有0出0","有1出1，全0出0","相同出1，不同出0","入1出0，入0出1"],"answer":"有1出1，全0出0","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["门电路","或门"],"analysis":"【审题】或门的逻辑功能表述：有 1 出 1，全 0 出 0。【定律/公式】或门：输入任一为 1 输出 1；输入全 0 输出 0。【步骤】① 因为或门“有 1 出 1、全 0 出 0”；② 所以 B 正确；③ 因为“全 1 出 1、有 0 出 0”是与门、相同出 1 是同或、入 1 出 0 是非门，所以 A、C、D 错误。【答案】有1出1，全0出0。【易错】×1 与与门功能描述对调；×2 与同或混淆；×3 与非门混淆。【口诀】或门有 1 就出 1，全零出零要记住；与门全一方出一，描述对照不糊涂。","steps":["【秒懂考点】或有1出1","【第一步】全0出0","【答案】有1出1，全0出0"],"pitfalls":["或有1出1，与全1出1"]});
  window.STUDY_DATA.questions.push({"id":"ne8301","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-8","knowledgePoint":"数制转换","type":"single","typeLabel":"单选","stem":"二进制数1010转换成十进制是（　）","options":["10","12","8","14"],"answer":"10","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["数字电路","数制"],"analysis":"【审题】二进制 1010 转十进制，按权展开。【定律/公式】(1010)₂=1×2³+0×2²+1×2¹+0×2⁰=8+0+2+0=10。【步骤】① 因为二转十按位权展开；② 因为 8+2=10；③ 因为 12 是误加 4、8 是漏 2¹、14 是位权错，所以 A 正确。【答案】10。【易错】×1 位权算错；×2 漏中间位；×3 与十进制字面混淆。【口诀】二转十按权展开，八四二一挨次乘；一零一零得一十，位权顺序右到左。","steps":["【秒懂考点】1010=8+2=10","【第一步】最左8","【答案】10"],"pitfalls":["8+2=10"]});
  window.STUDY_DATA.questions.push({"id":"ne8302","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-8","knowledgePoint":"十进制转二进制","type":"single","typeLabel":"单选","stem":"十进制数13转换成二进制是（　）","options":["1101","1011","1110","1100"],"answer":"1101","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["数字电路","数制"],"analysis":"【审题】十进制 13 转二进制，除 2 取余或按权凑数。【定律/公式】十转二：除 2 取余逆序；13=8+4+1=1101B。【步骤】① 因为 13÷2=6 余 1，6÷2=3 余 0，3÷2=1 余 1，1÷2=0 余 1，余数逆序 1101；② 因为 8+4+1=13 对应 1101，验算正确；③ 因为 1011=11、1110=14、1100=12，都不等于 13，所以 A 正确。【答案】1101。【易错】×1 余数写反成 1011；×2 漏最低位写成 1100；×3 用除 2 取商而非取余。【口诀】十转二除二取余，余数倒序拼起来；十三就是幺幺零幺，八四一凑最痛快。","steps":["【秒懂考点】13=8+4+1=1101","【第一步】1011=11","【答案】1101"],"pitfalls":["13=1101"]});
  window.STUDY_DATA.questions.push({"id":"ne8303","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-8","knowledgePoint":"八进制十六进制","type":"single","typeLabel":"单选","stem":"十六进制数A转换成十进制是（　）","options":["10","11","12","9"],"answer":"10","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["数字电路","数制"],"analysis":"【审题】十六进制 A 转十进制，A 对应 10。【定律/公式】十六进制 A=10，B=11，C=12，D=13，E=14，F=15。【步骤】① 因为十六进制用字母 A 表示 10；② 所以 A=10，选 A；③ 因为 11 是 B、12 是 C、9 就是 9，所以 B、C、D 错误。【答案】10。【易错】×1 把 A 当 11；×2 与字母序搞混；×3 与二进制 1010 混淆（虽同为 10）。【口诀】十六 A 就是十，B 十一 C 十二；F 十五要牢记，数制转换常考它。","steps":["【秒懂考点】A=10","【第一步】A-F=10-15","【答案】10"],"pitfalls":["A=10"]});
  window.STUDY_DATA.questions.push({"id":"ne8501","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-8","knowledgePoint":"八进制转二进制","type":"single","typeLabel":"单选","stem":"八进制数7转换成二进制是（　）","options":["111","110","101","100"],"answer":"111","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["数字电路","数制"],"analysis":"【审题】八进制 7 转二进制，一位八进制对应三位二进制。【定律/公式】八进制每位用 3 位二进制表示：7=111B，因为 4+2+1=7。【步骤】① 因为八进制 0~7 对应 000~111；② 因为 7=111；③ 因为 110=6、101=5、100=4，所以 A 正确。【答案】111。【易错】×1 位数写错成 110；×2 与十六进制 4 位规则混淆；×3 答 100。【口诀】八进转二三位看，七就是幺幺幺；四二一权要记熟，一位八进三位连。","steps":["【秒懂考点】7=111","【第一步】4+2+1","【答案】111"],"pitfalls":["7=111"]});
  window.STUDY_DATA.questions.push({"id":"ne9001","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-9","knowledgePoint":"组合逻辑特点","type":"single","typeLabel":"单选","stem":"组合逻辑电路的特点是（　）","options":["输出只与当前输入有关","输出与原状态有关","有记忆功能","包含触发器"],"answer":"输出只与当前输入有关","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["组合逻辑","特点"],"analysis":"【审题】组合逻辑电路特点：输出只与当前输入有关。【定律/公式】组合逻辑：无记忆元件，输出=f(当前输入)；时序逻辑输出还与原状态有关。【步骤】① 因为组合电路不含触发器，无记忆；② 所以输出只取决于当前输入，A 正确；③ 因为与原状态有关、有记忆、含触发器都是时序逻辑特点，所以 B、C、D 错误。【答案】输出只与当前输入有关。【易错】×1 与时序逻辑混淆；×2 认为组合电路有记忆；×3 以为组合电路含触发器。【口诀】组合逻辑看现在，时序才有记忆在；触发器属时序路，输出输入直关联。","steps":["【秒懂考点】组合只看当前","【第一步】无记忆","【答案】输出只与当前输入有关"],"pitfalls":["只看当前"]});
  window.STUDY_DATA.questions.push({"id":"ne9201","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-9","knowledgePoint":"组合逻辑分析","type":"single","typeLabel":"单选","stem":"组合逻辑电路的输出（　）","options":["只与当前输入有关","与原来状态有关","有记忆功能","包含触发器"],"answer":"只与当前输入有关","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["组合逻辑","特点"],"analysis":"【审题】组合逻辑电路的输出与什么有关，与上题同考点。【定律/公式】组合逻辑输出只与当前输入有关。【步骤】① 因为组合电路无存储元件，输出由当前输入唯一确定；② 所以 A 正确；③ 因为与原状态有关、有记忆、含触发器都是时序特征，所以 B、C、D 错误。【答案】只与当前输入有关。【易错】×1 与时序混淆；×2 认为有记忆；×3 认为含触发器。【口诀】组合输出看输入，时序还要看原态；两句话要分清楚，答题不会出意外。","steps":["【秒懂考点】只看当前","【第一步】无记忆","【答案】只与当前输入有关"],"pitfalls":["无记忆"]});
  window.STUDY_DATA.questions.push({"id":"ne9302","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-9","knowledgePoint":"译码器","type":"single","typeLabel":"单选","stem":"3线-8线译码器输入3位二进制，输出（　）个信号","options":["3","8","16","4"],"answer":"8","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["组合逻辑","译码器"],"analysis":"【审题】3 线-8 线译码器输入 3 位二进制，输出多少个信号：8。【定律/公式】n 线-2ⁿ 线译码器：3 线对应 8 线输出，每种输入组合激活一个输出。【步骤】① 因为 3 位二进制有 2³=8 种编码；② 所以输出 8 个信号，B 正确；③ 因为 3 是输入位数、16 是 4 线译码、4 不对，所以 A、C、D 错误。【答案】8。【易错】×1 答 3；×2 与 4 线-16 线混淆；×3 答 4。【口诀】译码输出二的 n，三位输入八路出；四线译码十六路，关系式来记得住。","steps":["【秒懂考点】3线-8线输出8","【第一步】8种组合","【答案】8"],"pitfalls":["8输出"]});
  window.STUDY_DATA.questions.push({"id":"ne9501","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-9","knowledgePoint":"七段显示器","type":"single","typeLabel":"单选","stem":"七段显示器用来显示（　）","options":["数字","文字","图像","声音"],"answer":"数字","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["组合逻辑","显示器"],"analysis":"【审题】七段显示器用来显示什么：数字。【定律/公式】七段 LED 数码管由 a~g 七段组成，可显示 0~9 数字（及部分字母），需译码驱动。【步骤】① 因为七段按数字字形设计，主要用于显示数码；② 所以 A 正确；③ 因为文字、图像、声音不是七段显示器主要用途，所以 B、C、D 错误。【答案】数字。【易错】×1 答文字（点阵/字符屏才是）；×2 答图像；×3 不知七段含义。【口诀】七段数码显数字，a 到 g 段拼字形；文字图像点阵用，译码驱动要配齐。","steps":["【秒懂考点】七段显示数字","【第一步】0-9","【答案】数字"],"pitfalls":["数字0-9"]});
  window.STUDY_DATA.questions.push({"id":"ee05","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"judge","stem":"电流的实际方向是负电荷移动的方向。","options":["正确","错误"],"answer":"错误","pitfalls":["规定方向"],"difficulty":1,"source":"highfreq","typeLabel":"判断","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】正确 【考点】电路基本概念 【一步步怎么算】 ① 题目：电流的实际方向是正电荷移动的方向。。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A","analysis":"【答案】错误。电流的实际方向规定为正电荷移动的方向，负电荷（自由电子）移动的方向与电流方向相反。\n\n判断：电流的实际方向是正电荷移动的方向。考查电流方向的物理规定。【定律/公式】物理学规定正电荷定向移动方向为电流方向；金属中电子移动方向与电流方向相反。【步骤】① 因为电流方向的国际规定就是正电荷移动方向；② 所以该说法正确；③ 因为电子（负电荷）移动方向与电流方向相反，若说成电子方向才错，故本题说法正确。【答案】正确。【易错】×1 以为电子方向才是电流方向；×2 把参考方向与实际方向混淆；×3 以为在任何导体中载流子都是正电荷。【口诀】电流方向正电荷，电子相反要记得；规定如此不改变，判断说法是正确。","steps":["【秒懂考点】电流方向规定，正确","【第一步】电流方向规定为正电荷定向移动的方向","【第二步】实际金属中是电子（负电荷）反方向移动","【答案】正确"]});
  window.STUDY_DATA.questions.push({"id":"ee31","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"judge","stem":"电流是形成电压的原因。","options":["正确","错误"],"answer":"错误","pitfalls":["正确"],"difficulty":1,"source":"highfreq","typeLabel":"判断","video":"v-ee","difficultyLabel":"基础","tags":["电路基本概念","ch-ee-1"],"explainLevel":"subject-specific","hint":"【结论】正确 【考点】电路基本概念 【一步步怎么算】 ① 题目：电压是形成电流的原因。。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符号","analysis":"【答案】错误。电压是形成电流的原因，有电压才可能有电流；有电流一定有电压。因果关系别搞反。\n\n判断：电压是形成电流的原因。考查电压与电流的因果关系。【定律/公式】电压（电位差）是推动电荷定向移动形成电流的原因；电源电动势维持电压。【步骤】① 因为导体两端有电压，电场推动自由电荷定向移动形成电流；② 所以电压是形成电流的原因，说法正确；③ 因为电阻是阻碍电流的因素，不是形成原因，但本题说法本身正确。【答案】正确。【易错】×1 以为电流产生电压（在电阻上电压由电流产生是结果，但整体上电压是原因）；×2 把电动势与电压概念混淆；×3 以为必须有电源才有电压（任何两点电位差都是电压）。【口诀】电压形成电流因，电场推动电荷行；欧姆定律 U 等 IR，因果关系要分清。","steps":["【秒懂考点】电压是形成电流的原因，正确","【第一步】有了电位差（电压），电荷才定向移动形成电流","【答案】正确"]});
  window.STUDY_DATA.questions.push({"id":"ex05e","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"电阻是耗能元件。","options":["正确","错误"],"answer":"正确","tags":["元件"],"source":"batch","pitfalls":["正确"],"explainLevel":"subject-specific","hint":"【结论】正确 【考点】电路基本概念 【一步步怎么算】 ① 题目：电阻是耗能元件。。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符号。 ⑤","analysis":"【审题】判断：电阻是耗能元件。考查电阻的物理性质。【定律/公式】电阻消耗电能转化为热能，P=I²R>0，是耗能元件；电容电感是储能元件。【步骤】① 因为电流通过电阻时电场力做功，电能转化为热能；② 因为电阻功率 P=I²R≥0，只消耗不储存，所以是耗能元件；③ 因为电容储存电场能、电感储存磁场能，它们才是储能元件，故本题说法正确。【答案】正确。【易错】×1 与电容电感储能混淆；×2 以为电阻也能储能；×3 把电源说成耗能（电源供能）。【口诀】电阻耗能变热光，电容电感储能量；耗能储能要分清，判断说法是正当。","steps":["【秒懂考点】电阻耗能，正确","【第一步】电阻把电能转化为热，P=I²R","【第二步】电容电感是储能元件","【答案】正确"]});
  window.STUDY_DATA.questions.push({"id":"exam25-ee-j01","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电压","type":"judge","typeLabel":"判断","stem":"电压是矢量，有大小有方向。","options":["正确","错误"],"answer":"正确","difficulty":1,"difficultyLabel":"基础","source":"school","tags":["2025真题","电工"],"analysis":"【审题】判断：电压是矢量，有大小有方向。考查电压的矢量性表述。【定律/公式】电压（电位差）是标量，但有方向（高电位指向低电位），电路分析中常带符号表示方向；严格说电压不是空间矢量，而是有向标量/代数量。在本题语境“有大小有方向”通常判为正确（指电压有方向性）。【步骤】① 因为电压既有大小又有方向（电位降低方向），电路中用正负表示；② 所以说“有大小有方向”符合电压的方向性特征，判正确；③ 因为若抠字眼“矢量”指空间矢量则电压是标量，但考试通常按“电压有方向”理解，选正确。【答案】正确。【易错】×1 以为电压完全无方向；×2 与电流矢量性混淆；×3 把“方向”理解成空间矢量方向。【口诀】电压大小带方向，高指向低是正当；标量代数有符号，判断说法不冤枉。","steps":["【秒懂考点】电压是标量，错误","【第一步】正负非矢量","【答案】错误"],"pitfalls":["电压标量"]});
  window.STUDY_DATA.questions.push({"id":"ne1004","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"理想电源","type":"judge","typeLabel":"判断","stem":"理想电压源的输出电流不随外电路变化。","options":["正确","错误"],"answer":"错误","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","理想电源"],"analysis":"【审题】判断：理想电压源的输出电流不随外电路变化。这是错误的——电流由外电路决定。【定律/公式】理想电压源：端电压恒定，输出电流随外电路变化；理想电流源才是电流恒定。【步骤】① 因为理想电压源只保证端电压不变；② 因为电流 I=U/R外，外电阻变化电流就变；③ 因为“输出电流不随外电路变化”是理想电流源特点，所以该说法错误。【答案】错误。【易错】×1 与理想电流源特点混淆；×2 认为理想电源电流也恒定；×3 不理解“由外电路决定”。【口诀】压源定压流外定，电流随外会变动；流源定流才是真，判断说法是错误。","steps":["【秒懂考点】电压恒定电流随负载，错误","【第一步】电流源才恒定","【答案】错误"],"pitfalls":["电流随负载变"]});
  window.STUDY_DATA.questions.push({"id":"ne1104","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电流方向","type":"judge","typeLabel":"判断","stem":"金属导体中，自由电子移动的方向就是电流的方向。","options":["正确","错误"],"answer":"错误","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","电流方向"],"analysis":"【审题】判断：金属导体中自由电子移动方向就是电流方向。错误，方向相反。【定律/公式】电流方向规定为正电荷移动方向；自由电子带负电，移动方向与电流方向相反。【步骤】① 因为电流方向是正电荷定向移动方向；② 因为电子是负电荷，其移动方向与电流方向相反；③ 所以该说法错误。【答案】错误。【易错】×1 认为电子方向就是电流方向；×2 不知电流方向的规定；×3 把参考方向与实际方向混淆。【口诀】电子移动反电流，正荷方向才是真；金属导电靠电子，方向相反要区分。","steps":["【秒懂考点】电子与电流方向相反，错误","【第一步】电流正电荷方向","【答案】错误"],"pitfalls":["电子方向与电流相反"]});
  window.STUDY_DATA.questions.push({"id":"ne1203","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"关联参考方向","type":"judge","typeLabel":"判断","stem":"电压电流关联参考方向是指电流从电压正极流入，负极流出。","options":["正确","错误"],"answer":"正确","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","参考方向"],"analysis":"【审题】判断：关联参考方向是电流从电压正极流入、负极流出。正确。【定律/公式】关联参考方向：电流参考方向与电压参考方向一致，即电流从电压“+”端流入、“−”端流出，此时 P=UI 表示吸收功率。【步骤】① 因为关联参考方向定义就是电流流入电压正极端；② 所以该说法正确；③ 因为非关联才是电流从负极流入，故本题正确。【答案】正确。【易错】×1 与非关联参考方向混淆；×2 不知“关联”含义；×3 认为关联只是随便一致。【口诀】关联方向流正入，负出才是关联路；P 正吸收 P 负发，非关联时正相反。","steps":["【秒懂考点】关联方向定义，正确","【第一步】P=UI>0吸收","【答案】正确"],"pitfalls":["关联方向定义"]});
  window.STUDY_DATA.questions.push({"id":"ne1306","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电流参考方向","type":"judge","typeLabel":"判断","stem":"电流的参考方向不能任意选定。","options":["正确","错误"],"answer":"错误","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","参考方向"],"analysis":"【答案】错误。电流的参考方向可以任意选定，选定后根据计算结果正负判断实际方向。参考方向选左或选右不影响结论。\n\n判断：电流的参考方向可以任意选定。正确。【定律/公式】参考方向是分析前人为假定的正方向，可任意选定；实际方向由计算结果符号决定。【步骤】① 因为参考方向只是计算基准，不必要求与实际一致；② 所以可以任意选定，说法正确；③ 因为选错方向只影响结果符号，不影响正确性，故本题正确。【答案】正确。【易错】×1 以为参考方向必须与实际一致；×2 与电流实际方向的规定混淆；×3 以为选定后不能改。【口诀】参考方向任选定，算正同向算负反；实际方向物理定，参考假定不改变。","steps":["【秒懂考点】参考方向任意，正确","【第一步】负则实际相反","【答案】正确"],"pitfalls":["参考方向任意"]});
  window.STUDY_DATA.questions.push({"id":"ne1503","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电流方向","type":"judge","typeLabel":"判断","stem":"金属导体中自由电子移动方向就是电流方向。","options":["正确","错误"],"answer":"错误","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["电路基本概念","电流"],"analysis":"【审题】判断：金属导体中自由电子移动方向就是电流方向。本题考查电流方向的规定，与前面同类题重复，【定律/公式】电流方向的物理规定是正电荷定向移动的方向；自由电子带负电，在金属导体中定向移动的方向与电流方向正好相反。【步骤】① 因为电流方向规定为正电荷移动方向，所以电子移动方向不能直接称为电流方向；② 因为电子带负电，负电荷移动方向与规定的电流方向相反，所以该说法错误；③ 因为若把电子方向当电流方向，则所有与电流方向相关的判断都会反号，所以必须牢记二者相反。【答案】错误。【易错】×1 以为电子移动方向就是电流方向，概念从一开始就反了；×2 不了解电流方向是人为规定的正电荷方向；×3 把参考方向与实际方向、电子方向三者混为一谈。【口诀】电子方向反电流，判断说法是错误；规定正荷移动向，反复考查不能丢。","steps":["【秒懂考点】电子与电流反，错误","【第一步】负电荷","【答案】错误"],"pitfalls":["电子反向"]});
  window.STUDY_DATA.questions.push({"id":"ne1603","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电压","type":"judge","typeLabel":"判断","stem":"两点间电压与参考点选择有关。","options":["正确","错误"],"answer":"错误","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["电路基本概念","电压"],"analysis":"【答案】错误。电压是两点电位之差，与参考点（零电位点）的选择无关。电位才与参考点有关，电压与参考点无关。\n\n判断：两点间电压与参考点选择无关。正确。【定律/公式】电压是两点电位之差 Uab=Va−Vb；换参考点时各点电位同增同减，差值不变。【步骤】① 因为电位是相对的，但电位差是绝对的；② 因为换参考点后 Va、Vb 同时加减同一常数，差值不变；③ 所以电压与参考点无关，说法正确。【答案】正确。【易错】×1 以为电位不变所以电压也不变（电位会变）；×2 以为电压也相对；×3 不理解电位差绝对性。【口诀】电位相对电压差，参考一换电位改；两点之差仍不变，判断说法是正派。","steps":["【秒懂考点】电压与参考点无关，正确","【第一步】电位差","【答案】正确"],"pitfalls":["电位才有关"]});
  window.STUDY_DATA.questions.push({"id":"nee203","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"关联参考方向","type":"judge","typeLabel":"判断","difficulty":2,"difficultyLabel":"强化","stem":"关联参考方向下，P=UI>0表示元件发出功率。","options":["正确","错误"],"answer":"错误","analysis":"【答案】错误。关联参考方向下P=UI>0表示元件吸收功率（负载），P<0才表示发出功率（电源）。\n\n判断：关联参考方向下 P=UI>0 表示元件吸收功率。正确。【定律/公式】关联参考方向：P=UI，P>0 吸收（消耗）功率，P<0 发出功率；非关联则相反。【步骤】① 因为关联方向下电流流入正极，UI>0 表示能量流入元件；② 所以 P>0 表示吸收功率，说法正确；③ 因为 P<0 才是发出功率，故本题正确。【答案】正确。【易错】×1 与非关联符号规则混淆；×2 以为 P>0 是发出；×3 不知关联含义。【口诀】关联 P 正是吸收，P 负发出要记住；非关联时正相反，符号规则不能输。","source":"2027考纲补充","tags":["关联参考方向","考纲补充"],"steps":["【秒懂考点】关联P>0吸收，正确","【第一步】电流从+端流入","【第二步】P<0才发出","【答案】正确"],"pitfalls":["关联P>0吸收，P<0发出"]});
  window.STUDY_DATA.questions.push({"id":"nee208","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"基尔霍夫","type":"judge","typeLabel":"判断","difficulty":2,"difficultyLabel":"强化","stem":"KCL只适用于节点，不适用于闭合面。","options":["正确","错误"],"answer":"错误","analysis":"【答案】错误。KCL不仅适用于节点，也适用于任意闭合面（广义节点）。比如把一个电路框起来，流入框的电流之和等于流出之和。\n\n判断：KCL 不仅适用于节点，也适用于任意闭合面。正确（广义 KCL）。【定律/公式】KCL 可推广到任意闭合面（广义节点）：流入闭合面电流之和=流出之和。【步骤】① 因为电荷守恒对任意闭合面成立，不限于一点；② 所以 KCL 适用于任意闭合面，说法正确；③ 因为这是 KCL 的推广形式，故本题正确。【答案】正确。【易错】×1 以为 KCL 只对节点；×2 与 KVL 推广混淆；×3 不知广义节点概念。【口诀】KCL 节点闭合面，电荷守恒都成立；广义节点会应用，判断说法是正确。","source":"2027考纲补充","tags":["基尔霍夫","考纲补充"],"steps":["【秒懂考点】KCL适用闭合面，正确","【第一步】闭合面当大节点","【答案】正确"],"pitfalls":["KCL对节点闭合面都成立"]});
  window.STUDY_DATA.questions.push({"id":"nee283","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"交流","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"正弦交流电的平均值等于最大值。","options":["正确","错误"],"answer":"错误","analysis":"【审题】判断：正弦交流电的平均值等于最大值。错误。【定律/公式】正弦波一个周期平均值为 0；半波平均值=2Um/π≈0.637Um；有效值=Um/√2≈0.707Um。【步骤】① 因为正弦波正负对称，全周期平均为 0；② 因为半波平均约 0.637Um，也不是最大值；③ 所以“平均值等于最大值”错误。【答案】错误。【易错】×1 以为平均=最大；×2 与有效值混淆；×3 不知半波平均公式。【口诀】正弦平均全周零，半波平均六三七；有效七零七最大，平均最大不相等。","source":"2027考纲补充","tags":["交流","考纲补充"],"steps":["【秒懂考点】平均值≠最大值，错误","【第一步】半波0.637、有效0.707","【答案】错误"],"pitfalls":["平均0.637、有效0.707，均非最大"]});
  window.STUDY_DATA.questions.push({"id":"nee287","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"运放电源","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"单电源供电运放输出不能到负电压。","options":["正确","错误"],"answer":"正确","analysis":"【审题】判断：单电源供电运放输出不能到负电压。正确。【定律/公式】单电源运放输出摆幅在 0（或地）与 Vcc 之间，不能输出低于地的负电压；双电源才有负输出。【步骤】① 因为单电源只有正电源和地，输出最低接近 0 V；② 所以输出不能到负电压，说法正确；③ 因为双电源运放才有负轨输出，故本题正确。【答案】正确。【易错】×1 以为单电源也能出负压；×2 与双电源混淆；×3 不知输出摆幅限制。【口诀】单电源输出不越零，负压输出要双源；输出摆幅看电源，判断说法是正确。","source":"2027考纲补充","tags":["运放电源","考纲补充"],"steps":["【秒懂考点】单电源不能负输出，正确","【第一步】需双电源","【答案】正确"],"pitfalls":["负输出要双电源"]});
  window.STUDY_DATA.questions.push({"id":"nee293","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"二极管","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"二极管是线性元件。","options":["正确","错误"],"answer":"错误","analysis":"【审题】判断：二极管是线性元件。错误，二极管是非线性元件。【定律/公式】二极管伏安特性是指数曲线，不满足欧姆定律，R 不是常数，属非线性元件。【步骤】① 因为二极管电流随电压指数变化，不是正比关系；② 所以不是线性元件，说法错误；③ 因为电阻才是线性元件典型代表，故本题错误。【答案】错误。【易错】×1 以为导通后可当线性；×2 与电阻混淆；×3 把理想模型当线性。【口诀】二极管是非线性，伏安特性曲线形；欧姆定律不适用，判断说法是错误。","source":"2027考纲补充","tags":["二极管","考纲补充"],"steps":["【秒懂考点】二极管非线性，错误","【第一步】指数曲线","【答案】错误"],"pitfalls":["二极管非线性"]});
  window.STUDY_DATA.questions.push({"id":"nee294","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"三极管","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"三极管有电流放大作用。","options":["正确","错误"],"answer":"正确","analysis":"【审题】判断：三极管有电流放大作用。正确。【定律/公式】三极管共射电流放大：IC=βIB，小基极电流控制大集电极电流。【步骤】① 因为三极管在放大区 IB 微小变化引起 IC 大变化；② 所以有电流放大作用，说法正确；③ 因为这是三极管基本功能，故本题正确。【答案】正确。【易错】×1 以为只有电压放大；×2 与二极管混淆；×3 以为饱和截止也有放大。【口诀】三极管有放大功，基流控制集流增；贝塔系数是倍数，判断说法是正确。","source":"2027考纲补充","tags":["三极管","考纲补充"],"steps":["【秒懂考点】三极管电流放大，正确","【第一步】Ic=βIb","【答案】正确"],"pitfalls":["电流放大"]});
  window.STUDY_DATA.questions.push({"id":"nee327","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"二极管","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"二极管正向导通反向截止。","options":["正确","错误"],"answer":"正确","analysis":"【审题】判断：二极管正向导通反向截止。考查二极管单向导电性的表述是否正确。【定律/公式】二极管伏安特性：正向电压超过死区后导通，反向电压下截止（反向电流很小），反向击穿是例外情况。【步骤】① 因为二极管正偏时 PN 结内电场被削弱，形成较大正向电流，所以正向导通；② 因为反偏时内电场增强，只有很小漏电流，所以反向截止；③ 因为“正向导通反向截止”正是单向导电性的标准表述，所以该说法正确。【答案】正确。【易错】×1 认为反向也完全导通，忽略截止区很小的反向电流；×2 与反向击穿混淆，以为反向总是截止；×3 与稳压管工作区混淆，稳压管才故意工作在反向击穿区。【口诀】正通反截单向导，二极管特性要记牢；反向击穿是例外，判断说法是正确。","source":"2027考纲补充","tags":["二极管","考纲补充"],"steps":["【秒懂考点】单向导电，正确","【第一步】正导通反截止","【答案】正确"],"pitfalls":["单向导电"]});
  window.STUDY_DATA.questions.push({"id":"nee328","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"三极管","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"三极管发射结正偏集电结反偏工作在放大区。","options":["正确","错误"],"answer":"正确","analysis":"【审题】判断：三极管发射结正偏集电结反偏工作在放大区。考查三极管放大区的偏置条件是否正确。【定律/公式】三极管三个工作区：放大区为发射结正偏、集电结反偏；饱和区两结均正偏；截止区两结均反偏。【步骤】① 因为发射结正偏才能向基区注入载流子；② 因为集电结反偏才能收集载流子形成集电极电流，实现放大；③ 因为该偏置组合正是放大区条件，所以该说法正确。【答案】正确。【易错】×1 与饱和区条件（两结均正偏）混淆；×2 与截止区条件（两结均反偏）混淆；×3 把发射结与集电结的偏置记反。【口诀】放大发正集反偏，饱和两正截止反；条件口诀要记全，判断说法是正确。","source":"2027考纲补充","tags":["三极管","考纲补充"],"steps":["【秒懂考点】放大区条件，正确","【第一步】发正集反","【答案】正确"],"pitfalls":["发正集反=放大"]});
  window.STUDY_DATA.questions.push({"id":"nee33","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电阻温度","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"金属电阻随温度升高而减小。","options":["正确","错误"],"answer":"错误","analysis":"【答案】错误。金属的电阻随温度升高而增大（正温度系数），因为温度升高晶格振动加剧，电子碰撞增多。\n\n判断：金属电阻随温度升高而增大。正确。【定律/公式】金属电阻温度系数为正：R=R0(1+αt)，温度升电阻增；半导体热敏电阻相反。【步骤】① 因为温度升金属晶格振动加剧，阻碍电子运动；② 所以电阻增大，说法正确；③ 因为半导体负温度系数相反，故本题正确。【答案】正确。【易错】×1 与半导体热敏电阻混淆；×2 以为温度升电阻减小；×3 不知温度系数。【口诀】金属温升阻变大，正温系数要记下；半导体温升阻变小，判断说法是正确。","source":"2027考纲补充","tags":["电阻温度","考纲补充"],"steps":["【秒懂考点】金属正温度系数，正确","【第一步】热敏有负","【答案】正确"],"pitfalls":["正温度系数"]});
  window.STUDY_DATA.questions.push({"id":"nee341","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电阻温度","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"金属电阻随温度升高增大。","options":["正确","错误"],"answer":"正确","analysis":"【审题】判断：金属电阻随温度升高增大。考查电阻温度特性，金属为正温度系数。【定律/公式】金属导体电阻与温度关系：R=R0(1+αt)，α>0，温度升高电阻增大；半导体材料 α<0，温度升高电阻减小。【步骤】① 因为金属温度升高时晶格振动加剧，对自由电子的阻碍增强；② 因为电阻随温度升高而增大，所以该说法正确；③ 因为半导体热敏电阻相反，若题目说半导体则错误，但金属说法正确。【答案】正确。【易错】×1 与半导体热敏电阻的负温度系数混淆；×2 以为温度升高电阻一定减小；×3 不知道温度系数正负的物理原因。【口诀】金属温升阻变大，反复出现不变化；正温系数是原因，判断说法是正确。","source":"2027考纲补充","tags":["电阻温度","考纲补充"],"steps":["【秒懂考点】金属正温度系数，正确","【第一步】温升电阻增","【答案】正确"],"pitfalls":["金属正温度系数"]});
  window.STUDY_DATA.questions.push({"id":"nee344","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"短路","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"短路电流很小，是安全状态。","options":["正确","错误"],"answer":"错误","analysis":"【答案】错误。短路时电流极大（几乎等于电源电压除以内阻），会烧坏电源和线路，是最危险的故障状态，必须避免。\n\n判断：短路电流很大应避免。考查短路的危害与安全用电。【定律/公式】短路时回路电阻近似为零，电流 I=E/r 很大，产生大量焦耳热，可能烧毁电源和线路，必须避免并设置保护。【步骤】① 因为短路使总电阻极小，电流远超额定值；② 因为大电流产生大量热，会烧坏电源、导线，引发火灾；③ 因为短路是危险状态应避免，所以该说法正确。【答案】正确。【易错】×1 以为短路只是电压为零没有危害；×2 与开路状态混淆，开路电流才为零；×3 忽略短路的热效应和火灾风险。【口诀】短路电流非常大，烧毁设备危害加；保护装置要安装，判断说法是正确。","source":"2027考纲补充","tags":["短路","考纲补充"],"steps":["【秒懂考点】短路电流大应避免，正确","【第一步】烧毁设备","【答案】正确"],"pitfalls":["短路要避免"]});
  window.STUDY_DATA.questions.push({"id":"nee349","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"三极管","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"三极管基极电流控制集电极电流。","options":["正确","错误"],"answer":"正确","analysis":"【审题】判断：三极管基极电流控制集电极电流。正确。【定律/公式】IC=βIB，基极小电流控制集电极大电流，是电流控制器件。【步骤】① 因为 IB 控制 IC，β 是放大倍数；② 所以该说法正确；③ 因为这是三极管工作原理，故本题正确。【答案】正确。【易错】×1 以为是电压控制（场效应管才是）；×2 与场效应管混淆；×3 以为集电极控制基极。【口诀】基流控制集流走，电流控制三极有；场管才是压控制，判断说法是正确。","source":"2027考纲补充","tags":["三极管","考纲补充"],"steps":["【秒懂考点】Ib控制Ic，正确","【第一步】Ic=βIb","【答案】正确"],"pitfalls":["Ib控制Ic"]});
  window.STUDY_DATA.questions.push({"id":"nee36","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"短路","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"电源短路会导致电流过大烧坏电源。","options":["正确","错误"],"answer":"正确","analysis":"【审题】判断：电源短路会导致电流过大烧坏电源。考查电源短路的后果。【定律/公式】电源短路时负载电阻为零，电流 I=E/r0，仅由电源内阻限制，电流极大，电源发热严重甚至烧毁。【步骤】① 因为短路后外电路电阻为零，电流只受内阻限制；② 因为电源内阻很小，所以短路电流非常大；③ 因为大电流使电源过热损坏，所以该说法正确。【答案】正确。【易错】×1 以为电源内阻大能限制电流不损坏；×2 与负载短路混淆，其实电源两端短路更危险；×3 不理解内阻对短路电流的决定作用。【口诀】电源短路电流大，内阻限制才发家；烧毁电源危害重，判断说法是正确。","source":"2027考纲补充","tags":["短路","考纲补充"],"steps":["【秒懂考点】短路烧坏，正确","【第一步】电流大","【答案】正确"],"pitfalls":["短路电流大"]});
  window.STUDY_DATA.questions.push({"id":"nee49","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"欧姆定律","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"欧姆定律适用于所有电路。","options":["正确","错误"],"answer":"错误","analysis":"【审题】判断：欧姆定律适用于所有电路。错误，只适用于线性电阻。【定律/公式】欧姆定律 U=IR 只适用于线性电阻元件；非线性元件（二极管等）、含源支路、动态元件不能直接套用。【步骤】① 因为欧姆定律要求电压电流成正比、R 为常数；② 因为非线性元件、电容电感暂态、含源网络不满足，所以不适用于所有电路；③ 所以该说法错误。【答案】错误。【易错】×1 以为任何导电都满足欧姆定律；×2 把二极管当线性；×3 忽略线性前提。【口诀】欧姆只对线性阻，非线性来不适用；任何电路说法错，适用范围要记清。","source":"2027考纲补充","tags":["欧姆定律","考纲补充"],"steps":["【秒懂考点】欧姆定律只线性，错误","【第一步】非线性不适用","【答案】错误"],"pitfalls":["只线性电阻"]});
  window.STUDY_DATA.questions.push({"id":"tr8","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"电容不是储能元件。","options":["正确","错误"],"answer":"错误","tags":["元件"],"source":"batch","pitfalls":["电容储能"],"explainLevel":"subject-specific","hint":"【结论】错误 【考点】电路基本概念 【一步步怎么算】 ① 题目：电容不是储能元件。。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符号。 ","analysis":"【审题】判断：电容不是储能元件。错误，电容是储能元件。【定律/公式】电容储存电场能 W=½CU²；电感储存磁场能 W=½LI²。两者都是储能元件，电阻才是耗能元件。【步骤】① 因为电容充电时储存电场能量，放电时释放；② 因为电容是典型储能元件，所以说“不是储能”错误；③ 因为电阻耗能、电容电感储能，故本题错误。【答案】错误。【易错】×1 与电阻耗能混淆；×2 以为只有电感储能；×3 不知电容储能公式。【口诀】电容电感储能量，电阻耗能变热光；电容储能电场存，判断说法是错误。","steps":["【秒懂考点】电容是储能元件，题目错误","【第一步】电容储能½Cu²，电感储能½Li²","【答案】错误"]});
  window.STUDY_DATA.questions.push({"id":"ne10002","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-10","knowledgePoint":"时序逻辑特点","type":"judge","typeLabel":"判断","stem":"时序逻辑电路具有记忆功能。","options":["正确","错误"],"answer":"正确","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["时序逻辑","特点"],"analysis":"【审题】判断：时序逻辑电路具有记忆功能。正确。【定律/公式】时序逻辑含触发器等存储元件，输出与原状态有关，具有记忆功能；组合逻辑无记忆。【步骤】① 因为触发器能保存二进制状态；② 所以时序电路有记忆功能，说法正确；③ 因为组合电路无记忆，时序才有，故本题正确。【答案】正确。【易错】×1 与组合逻辑混淆；×2 以为时序无记忆；×3 不知触发器作用。【口诀】时序电路有记忆，触发器把状态存；组合逻辑无记忆，判断说法是正确。","steps":["【秒懂考点】时序有记忆，正确","【第一步】含触发器","【答案】正确"],"pitfalls":["时序有记忆"]});
  window.STUDY_DATA.questions.push({"id":"ee60","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"judge","stem":"并联电路中各支路电压相等。","options":["正确","错误"],"answer":"正确","pitfalls":["正确"],"difficulty":1,"source":"highfreq","typeLabel":"判断","video":"v-ee","difficultyLabel":"基础","tags":["直流电路分析","ch-ee-2"],"explainLevel":"subject-specific","hint":"【结论】正确 【考点】直流电路分析 【一步步怎么算】 ① 题目：并联电路中各支路电压相等。。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与","analysis":"【审题】判断：并联电路中各支路电压相等。正确。【定律/公式】并联电路各支路两端电压相同，等于总电压；电流按电阻分配。【步骤】① 因为并联支路接在相同两节点之间；② 所以各支路电压相等，说法正确；③ 因为串联才是电流相等、电压分配，故本题正确。【答案】正确。【易错】×1 与串联电流相等混淆；×2 以为并联电压按阻分配；×3 不知并联定义。【口诀】并联电压都相等，串联电流一样行；串分压来并分流，判断说法是正确。","steps":["【秒懂考点】并联各支路电压相等，正确","【第一步】各支路两端都接在同一对节点上","【答案】正确"]});
  window.STUDY_DATA.questions.push({"id":"see-j0059","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"瞬态电路/换路定律","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"1、‍换路定理指出：电感两端的电压是不能发生跃变的，只能连续变化。","options":["正确","错误"],"answer":"错误","pitfalls":["错误"],"tags":["学校题库"],"source":"school","explainLevel":"subject-specific","hint":"【结论】错误 【考点】瞬态电路/换路定律 【一步步怎么算】 ① 题目：1、‍换路定理指出：电感两端的电压是不能发生跃变的，只能连续变化。。 ② 用「瞬态电路/换路定律」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。","analysis":"【审题】判断：换路定理指出电感两端电压不能跃变，只能连续变化。错误——是电感电流不能跃变，电压可以跃变。【定律/公式】换路定则：电感电流 iL(0+)=iL(0−)、电容电压 uC(0+)=uC(0−) 不能跃变；电感电压、电容电流可以跃变。【步骤】① 因为换路定则约束的是电感电流和电容电压；② 因为电感电压 uL=L di/dt 可以跃变，所以题目说法错误；③ 因为把“电流”说成“电压”是概念错误，故本题错误。【答案】错误。【易错】×1 把电感电流与电压记混；×2 与电容电压不能跃变混淆；×3 不知换路定则内容。【口诀】换路定则记电流，电感电流不跃变；电容电压也连续，电压电流可跃变。","steps":["【秒懂考点】换路定律说法错误","【第一步】不能突变的是电感电流（不是电压）！","【第二步】正确说法：电感电流不能跃变","【答案】错误"]});
  window.STUDY_DATA.questions.push({"id":"see-j0060","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"瞬态电路/换路定律","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"2、RC串联电路如果在C两端再并联一个电阻，则时间常数会变大。","options":["正确","错误"],"answer":"错误","pitfalls":["错误"],"tags":["学校题库"],"source":"school","explainLevel":"subject-specific","hint":"【结论】错误 【考点】瞬态电路/换路定律 【一步步怎么算】 ① 题目：2、RC串联电路如果在C两端再并联一个电阻，则时间常数会变大。。 ② 用「瞬态电路/换路定律」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③","analysis":"【审题】判断：RC 串联在 C 两端再并联电阻，时间常数会变大。错误，并联电阻使等效电阻变小，τ=RC 变小。【定律/公式】RC 时间常数 τ=R_eq C；C 并联电阻后等效电阻减小，τ 减小。【步骤】① 因为电阻并联总阻小于任一分电阻；② 因为 τ=R_eq C，R_eq 变小则 τ 变小；③ 所以“时间常数会变大”错误。【答案】错误。【易错】×1 以为并联电阻 τ 变大；×2 不知 τ=RC 中 R 是等效电阻；×3 与串联电阻混淆。【口诀】并联电阻等效小，时间常数跟着小；串阻才会 τ 变大，判断说法是错误。","steps":["【秒懂考点】并联电阻使时间常数变小","【第一步】C再并电阻，等效电阻变小","【第二步】τ=RC，R变小τ变小，不是变大","【答案】错误"]});
  window.STUDY_DATA.questions.push({"id":"see-j0061","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"瞬态电路/换路定律","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"4、‌求解时间常数时，一定要使动态电路处于换路之前的状态。","options":["正确","错误"],"answer":"错误","pitfalls":["错误"],"tags":["学校题库"],"source":"school","explainLevel":"subject-specific","hint":"【结论】错误 【考点】瞬态电路/换路定律 【一步步怎么算】 ① 题目：4、‌求解时间常数时，一定要使动态电路处于换路之前的状态。。 ② 用「瞬态电路/换路定律」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代","analysis":"【审题】判断：求解时间常数时一定要使动态电路处于换路之前的状态。错误，时间常数由换路后的等效电阻决定。【定律/公式】时间常数 τ=R_eq C 或 L/R_eq，R_eq 是从储能元件两端看进去的换路后等效电阻。【步骤】① 因为时间常数描述换路后暂态过程快慢；② 因为要用换路后的电路结构求 R_eq，不是换路前；③ 所以该说法错误。【答案】错误。【易错】×1 以为用换路前状态；×2 不知 R_eq 的求法；×3 与初始值求法混淆。【口诀】时间常数看换路，换路之后求电阻；初始值才看换路前，判断说法是错误。","steps":["【秒懂考点】求时间常数应看换路后（把独立源置零）","【第一步】从储能元件两端看进去的等效电阻","【第二步】不是换路前状态","【答案】错误"]});
  window.STUDY_DATA.questions.push({"id":"see-j0062","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"瞬态电路/换路定律","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"5、‌动态电路在换路时一定产生过渡过程。","options":["正确","错误"],"answer":"错误","pitfalls":["错误"],"tags":["学校题库"],"source":"school","explainLevel":"subject-specific","hint":"【结论】正确 【考点】瞬态电路/换路定律 【一步步怎么算】 ① 题目：5、‌动态电路在换路时一定产生过渡过程。。 ② 用「瞬态电路/换路定律」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（5）计算","analysis":"【审题】判断：动态电路在换路时一定产生过渡过程。错误，只有储能元件状态改变时才有过渡。【定律/公式】换路后若储能元件初始值与稳态值相同，则无过渡过程；只有状态发生改变才产生暂态。【步骤】① 因为过渡过程源于储能元件能量不能跃变；② 因为若换路前后状态相同（如已达稳态再换路不变），则无过渡；③ 所以“一定产生”错误。【答案】错误。【易错】×1 以为换路必有暂态；×2 不知无过渡的条件；×3 与换路定则混淆。【口诀】换路未必生暂态，状态不变无过渡；能量跃变才有时，判断说法是错误。","steps":["【秒懂考点】换路不一定产生过渡过程","【第一步】若换路前后稳态值相同，就无过渡过程","【第二步】\"一定\"太绝对","【答案】错误"]});
  window.STUDY_DATA.questions.push({"id":"see-j0063","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"瞬态电路/换路定律","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"6、‍时间常数越小，电路的变化速度越慢。","options":["正确","错误"],"answer":"错误","pitfalls":["错误"],"tags":["学校题库"],"source":"school","explainLevel":"subject-specific","hint":"【结论】错误 【考点】瞬态电路/换路定律 【一步步怎么算】 ① 题目：6、‍时间常数越小，电路的变化速度越慢。。 ② 用「瞬态电路/换路定律」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（6）计算","analysis":"【审题】判断：时间常数越小，电路的变化速度越慢。错误，τ 越小变化越快。【定律/公式】暂态响应按 e^(−t/τ) 衰减，τ 越小衰减越快，达到稳态越快；5τ 视为过渡结束。【步骤】① 因为 τ 是变化快慢的时间尺度；② 因为 τ 小则指数衰减快，变化速度快；③ 所以“变化速度越慢”错误。【答案】错误。【易错】×1 把 τ 大小与快慢记反；×2 不知 e^(−t/τ) 含义；×3 与稳定时间混淆。【口诀】时间常数越小快，越大越慢拖时间；五倍 τ 后近稳态，判断说法是错误。","steps":["【秒懂考点】τ越小变化越快","【第一步】τ是充放电快慢的量度，越小越快","【第二步】题目说越慢，错误","【答案】错误"]});
  window.STUDY_DATA.questions.push({"id":"see-j0064","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"瞬态电路/换路定律","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"7、换路定律指出：电感两端的电压是不能发生跃变的，只能连续变化。","options":["正确","错误"],"answer":"错误","pitfalls":["错误"],"tags":["学校题库"],"source":"school","explainLevel":"subject-specific","hint":"【结论】错误 【考点】瞬态电路/换路定律 【一步步怎么算】 ① 题目：7、换路定律指出：电感两端的电压是不能发生跃变的，只能连续变化。。 ② 用「瞬态电路/换路定律」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ","analysis":"【审题】判断：换路定律指出电感两端电压不能跃变。与前面同题，错误，是电流不能跃变。【定律/公式】换路定则：iL 与 uC 不能跃变；电感电压、电容电流可以跃变。【步骤】① 因为换路定则约束电感电流连续；② 因为电感电压可以跃变，题目说法错误；③ 因为把电流说成电压是错误，故本题错误。【答案】错误。【易错】×1 电流电压记混；×2 与电容混淆；×3 不知换路定则。【口诀】电感电流不跃变，电容电压也连续；电压电流可跃变，判断说法是错误。","steps":["【秒懂考点】同74题，说法错误","【第一步】电感不突变的是电流，不是电压","【答案】错误"]});
  window.STUDY_DATA.questions.push({"id":"ee16","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电路定理","type":"judge","stem":"叠加定理可以用来计算线性电路中的功率。","options":["正确","错误"],"answer":"错误","pitfalls":["功率非线性"],"difficulty":2,"source":"highfreq","typeLabel":"判断","video":"v-ee","difficultyLabel":"强化","tags":["电路定理","ch-ee-3"],"explainLevel":"subject-specific","hint":"【结论】错误 【考点】电路定理 【一步步怎么算】 ① 题目：叠加定理可以用来计算线性电路中的功率。。 ② 用「电路定理」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω","analysis":"【审题】判断：叠加定理可以用来计算线性电路中的功率。错误，功率不能直接叠加。【定律/公式】叠加定理只适用于线性电压、电流；功率 P=I²R 或 UI 是二次量，不能用各分量功率直接相加。【步骤】① 因为叠加定理针对电压电流的线性关系；② 因为功率与电流电压是平方/乘积关系，不满足叠加性；③ 所以不能用叠加直接算功率，说法错误。【答案】错误。【易错】×1 以为功率也能叠加；×2 先叠加电流再平方与直接平方混淆；×3 不知功率是二次量。【口诀】叠加只对压和流，功率二次不能叠；先叠电流再平方，才是正解不翻车。","steps":["【秒懂考点】功率不能叠加，错误","【第一步】叠加定理只对电压、电流（线性量）成立","【第二步】功率是电流的平方（I²R），非线性，不能直接相加","【答案】错误"]});
  window.STUDY_DATA.questions.push({"id":"ee41","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电路定理","type":"judge","stem":"戴维南定理可将有源二端网络等效为电压源串联电阻（该说法正确）","options":["正确","错误"],"answer":"正确","pitfalls":["正确"],"difficulty":1,"source":"highfreq","typeLabel":"判断","video":"v-ee","difficultyLabel":"基础","tags":["电路定理","ch-ee-3"],"explainLevel":"subject-specific","hint":"【结论】错误 【考点】电路定理 【一步步怎么算】 ① 题目：戴维南定理可将有源二口网络等效为电压源串联电阻（该说法错误）。 ② 用「电路定理」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④","analysis":"【审题】判断：戴维南定理可将有源二端网络等效为电压源串联电阻。正确。【定律/公式】戴维南定理：线性有源二端网络等效为 Uoc 串 R0。【步骤】① 因为戴维南定理正是该等效结论；② 所以该说法正确；③ 因为诺顿才是电流源并电阻，故本题正确。【答案】正确。【易错】×1 与诺顿混淆；×2 以为是并联结构；×3 忽略“线性有源二端”前提。【口诀】戴维南压串阻，诺顿流并阻；等效对外不改变，判断说法是正确。","steps":["【秒懂考点】戴维南等效描述，正确","【第一步】有源二端网络=开路电压Uoc串等效内阻R0","【答案】正确"]});
  window.STUDY_DATA.questions.push({"id":"ne3003","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"相位关系","type":"judge","typeLabel":"判断","stem":"纯电容电路中，电流相位超前电压90°。","options":["正确","错误"],"answer":"正确","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["交流电路","相位"],"analysis":"【审题】判断：纯电容电路中电流相位超前电压 90°。正确。【定律/公式】纯电容：i 超前 u 90°（电压滞后电流 90°）。【步骤】① 因为 i=C du/dt，电流与电压变化率成正比，相位超前；② 所以电流超前电压 90°，说法正确；③ 因为纯电感是电压超前电流，故本题正确。【答案】正确。【易错】×1 与纯电感相位关系颠倒；×2 以为电压超前；×3 答同相。【口诀】纯容电流超前压，九十正交关系佳；纯感压超流九十，判断说法是正确。","steps":["【秒懂考点】电容电流超前90，正确","【第一步】i=Cdu/dt","【答案】正确"],"pitfalls":["电容超前"]});
  window.STUDY_DATA.questions.push({"id":"ne3103","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电容特性","type":"judge","typeLabel":"判断","stem":"电容在直流电路中相当于短路。","options":["正确","错误"],"answer":"错误","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["交流电路","电容"],"analysis":"【答案】错误。电容在直流稳态电路中相当于开路（隔直通交），因为充电完成后电流为零。电感才在直流稳态下相当于短路。\n\n判断：电容在直流电路中相当于开路。正确（稳态）。【定律/公式】直流稳态时电容充电完成，i=C du/dt=0，相当于开路。【步骤】① 因为直流稳态电容电压不变，电流为零；② 所以相当于开路，说法正确；③ 因为电感直流稳态相当于短路，故本题正确。【答案】正确。【易错】×1 与电感短路混淆；×2 以为电容导通直流；×3 忽略“稳态”条件（接通瞬间有充电流）。【口诀】电容隔直稳态开，电感直流像短路；稳定之后才如此，判断说法是正确。","steps":["【秒懂考点】直流电容开路，正确","【第一步】隔直通交","【答案】正确"],"pitfalls":["直流电容开路"]});
  window.STUDY_DATA.questions.push({"id":"ne3202","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电感相位","type":"judge","typeLabel":"判断","stem":"纯电感电路中，电压相位超前电流90°。","options":["正确","错误"],"answer":"正确","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["交流电路","相位"],"analysis":"【审题】判断：纯电感电路中电压相位超前电流 90°。正确。【定律/公式】纯电感：u 超前 i 90°（电流滞后电压 90°）。【步骤】① 因为 u=L di/dt，电压与电流变化率成正比，相位超前；② 所以电压超前电流 90°，说法正确；③ 因为纯电容是电流超前，故本题正确。【答案】正确。【易错】×1 与纯电容相位颠倒；×2 以为电流超前；×3 答同相。【口诀】纯感电压超前流，九十正交要记住；纯容电流才超前，判断说法是正确。","steps":["【秒懂考点】电感电压超前90°，正确","【第一步】u=Ldi/dt","【答案】正确"],"pitfalls":["电感超前90°"]});
  window.STUDY_DATA.questions.push({"id":"ne3307","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"功率因数","type":"judge","typeLabel":"判断","stem":"提高功率因数会降低电源利用率。","options":["正确","错误"],"answer":"错误","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["交流电路","功率因数"],"analysis":"【答案】错误。提高功率因数可以让电源输送更多有功功率，提高电源利用率，减少线路损耗。工厂都要装电容柜提高功率因数。\n\n判断：提高功率因数可以提高电源利用率。正确。【定律/公式】cosφ 提高后，同样 S=UI 下有功 P=S cosφ 增大，线路电流减小，电源利用率提高。【步骤】① 因为功率因数高则有功占比大；② 因为电流减小损耗降低，电源容量利用率提高；③ 所以该说法正确。【答案】正确。【易错】×1 以为只减小损耗与利用率无关；×2 与无功混淆；×3 不知 cosφ 含义。【口诀】功率因数提一提，有功占比升上去；电流变小损耗低，判断说法是正确。","steps":["【秒懂考点】提高功率因数提利用率，正确","【第一步】无功减小","【答案】正确"],"pitfalls":["并电容补偿"]});
  window.STUDY_DATA.questions.push({"id":"ne3503","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"有功功率","type":"judge","typeLabel":"判断","stem":"有功功率单位是伏特(V)。","options":["正确","错误"],"answer":"错误","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["交流电路","功率单位"],"analysis":"【答案】错误。有功功率单位是瓦特(W)，电压单位才是伏特(V)。别搞混单位。\n\n判断：有功功率单位是瓦特 W。正确。【定律/公式】有功 P 单位 W；无功 Q 单位 var；视在 S 单位 VA。【步骤】① 因为有功功率是实际消耗的功率，单位瓦特；② 所以该说法正确；③ 因为无功用乏、视在用伏安，故本题正确。【答案】正确。【易错】×1 与无功 var 混淆；×2 与视在 VA 混淆；×3 答焦耳（那是能量）。【口诀】有功单位瓦特 W，无功乏来视在 VA；能量焦耳要分清，判断说法是正确。","steps":["【秒懂考点】有功W，正确","【第一步】无功var、视在VA","【答案】正确"],"pitfalls":["有功W无功var视在VA"]});
  window.STUDY_DATA.questions.push({"id":"ne3603","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电容","type":"judge","typeLabel":"判断","stem":"电容在直流稳态电路中相当于开路。","options":["正确","错误"],"answer":"正确","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["交流电路","电容"],"analysis":"【审题】判断：电容在直流稳态电路中相当于开路。考查电容的隔直作用与直流稳态等效。【定律/公式】电容电流 i=C du/dt；直流稳态时电容两端电压恒定不变，du/dt=0，所以电流为零，相当于开路。【步骤】① 因为直流稳态下电容已充电完毕，电压不再变化；② 因为电压不变则电流为零，电容相当于开路，隔断直流；③ 因为电感在直流稳态相当于短路，与电容正好相反，所以该说法正确。【答案】正确。【易错】×1 与电感直流稳态短路混淆；×2 忽略“稳态”二字，接通瞬间电容有充电电流并不是开路；×3 以为电容能通过直流电流。【口诀】电容稳态像断开，隔直通交是本性；直流稳态无电流，判断说法是正确。","steps":["【秒懂考点】直流电容开路，正确","【第一步】隔直通交","【答案】正确"],"pitfalls":["稳态开路"]});
  window.STUDY_DATA.questions.push({"id":"nee75","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"时间常数意义","type":"judge","typeLabel":"判断","difficulty":2,"difficultyLabel":"强化","stem":"经过 3~5 个时间常数后，过渡过程基本结束。","options":["正确","错误"],"answer":"正确","analysis":"【审题】判断：经过 3~5 个时间常数后过渡过程基本结束。正确。【定律/公式】暂态按 e^(−t/τ) 衰减：3τ 约剩 5%，5τ 约剩 0.7%，工程上认为过渡结束。【步骤】① 因为指数衰减到 3~5τ 时已接近稳态；② 所以该说法正确；③ 因为 1τ 远未结束，故本题正确。【答案】正确。【易错】×1 以为 1τ 就结束；×2 以为要 10τ；×3 不知 e^(−t/τ) 数值。【口诀】三到五倍时间常，过渡过程基本完；五倍之后近稳态，判断说法是正确。","source":"2027考纲补充","tags":["时间常数意义","考纲补充"],"steps":["【秒懂考点】3~5τ结束，正确","【第一步】5τ=99.3%","【答案】正确"],"pitfalls":["3-5τ"]});
  window.STUDY_DATA.questions.push({"id":"nee92","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"交流测量","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"交流电压表测量的是最大值。","options":["正确","错误"],"answer":"错误","analysis":"【答案】错误。交流电压表、电流表测量的都是有效值。市电220V就是有效值，最大值约311V。\n\n判断：交流电压表测量的是有效值。正确。【定律/公式】交流电压表读数为有效值；万用表交流档也是有效值（平均值响应表按正弦有效值刻度）。【步骤】① 因为电气测量习惯用有效值表示；② 所以交流电压表测的是有效值，说法正确；③ 因为最大值需换算 Um=√2 U，故本题正确。【答案】正确。【易错】×1 以为测最大值；×2 与瞬时值混淆；×3 与平均值混淆。【口诀】交流电表读有效，最大乘以根号二；平均瞬时不读数，判断说法是正确。","source":"2027考纲补充","tags":["交流测量","考纲补充"],"steps":["【秒懂考点】测有效值，正确","【第一步】仪表刻度","【答案】正确"],"pitfalls":["有效值"]});
  window.STUDY_DATA.questions.push({"id":"ee49","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"judge","stem":"理想运放开环增益为无穷大。","options":["正确","错误"],"answer":"正确","pitfalls":["正确"],"difficulty":1,"source":"highfreq","typeLabel":"判断","video":"v-ee","difficultyLabel":"基础","tags":["运算放大器","ch-ee-4"],"explainLevel":"subject-specific","hint":"【结论】正确 【考点】运算放大器 【一步步怎么算】 ① 题目：理想运放开环增益为无穷大。。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符号","analysis":"【审题】判断：理想运放开环增益为无穷大。正确。【定律/公式】理想运放参数：开环增益 Auo=∞，输入电阻∞，输出电阻 0，带宽∞。【步骤】① 因为理想化假设开环差模增益无穷大；② 所以该说法正确；③ 因为这是理想运放基本假设，由此推出虚短虚断，故本题正确。【答案】正确。【易错】×1 以为开环增益有限；×2 与闭环增益混淆；×3 不知理想参数。【口诀】理想运放增益大，无穷开环是假设；虚短虚断由此来，判断说法是正确。","steps":["【秒懂考点】理想运放开环增益无穷大，正确","【第一步】由此推出虚短 u+=u-","【答案】正确"]});
  window.STUDY_DATA.questions.push({"id":"exam25-ee-j03","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"三极管","type":"judge","typeLabel":"判断","stem":"三极管有放大作用。","options":["正确","错误"],"answer":"正确","difficulty":1,"difficultyLabel":"基础","source":"school","tags":["2025真题","电工"],"analysis":"【审题】判断：三极管有放大作用。考查三极管的基本功能是否包含放大。【定律/公式】三极管在放大区满足 IC=βIB，小的基极电流可以控制大的集电极电流，这就是电流放大作用。【步骤】① 因为三极管放大区发射结正偏、集电结反偏，具备放大能力；② 因为基极电流 IB 微小变化会引起 IC 较大变化，体现放大作用；③ 因为放大是三极管最基本的功能之一（另一是开关），所以该说法正确。【答案】正确。【易错】×1 以为三极管只能做开关不能放大；×2 与二极管功能混淆，二极管没有放大作用；×3 以为只有饱和区截止区才能工作，忽略放大区。【口诀】三极管有放大功，贝塔倍数记心中；开关放大两用途，判断说法是正确。","steps":["【秒懂考点】三极管放大，正确","【第一步】放大区","【答案】正确"],"pitfalls":["放大作用"]});
  window.STUDY_DATA.questions.push({"id":"ne5305","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管单向导电","type":"judge","typeLabel":"判断","stem":"二极管具有单向导电性。","options":["正确","错误"],"answer":"正确","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["二极管","单向导电"],"analysis":"【审题】判断：二极管具有单向导电性。考查二极管核心特性表述是否正确。【定律/公式】二极管的 PN 结正向偏置时导通、反向偏置时截止，电流只能单向通过，这就是单向导电性。【步骤】① 因为二极管正偏时电阻小、电流大，处于导通状态；② 因为反偏时电阻大、电流极小，处于截止状态；③ 因为这种单方向导电的特性正是二极管最基本的特性，所以该说法正确。【答案】正确。【易错】×1 以为二极管双向都能导电；×2 与稳压管反向击穿混淆，那是特殊情况；×3 不理解单向导电的物理原因是 PN 结势垒。【口诀】二极管单向导电，正通反截是本性；整流检波靠它成，判断说法是正确。","steps":["【秒懂考点】单向导电，正确","【第一步】正通反截","【答案】正确"],"pitfalls":["单向导电"]});
  window.STUDY_DATA.questions.push({"id":"ne5503","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"桥式整流二极管数量","type":"judge","typeLabel":"判断","stem":"单相桥式整流电路用2个二极管。","options":["正确","错误"],"answer":"错误","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["整流电路","桥式"],"analysis":"【答案】错误。单相桥式整流需要4个二极管接成电桥形式。半波整流才用1个，全波整流中心抽头式用2个。\n\n判断：单相桥式整流电路用 4 个二极管。正确。【定律/公式】桥式整流由四只二极管组成桥式结构；半波用 1 只，全波中心抽头用 2 只。【步骤】① 因为桥式整流正负半周各两只管轮流导通；② 所以共用 4 个二极管，说法正确；③ 因为半波 1 管、全波 2 管，故本题正确。【答案】正确。【易错】×1 与半波 1 管混淆；×2 与全波 2 管混淆；×3 答 2 或 8。【口诀】桥式整流四只管，半波一只全波二；桥式输出全波形，判断说法是正确。","steps":["【秒懂考点】桥式4个，正确","【第一步】半波1","【答案】正确"],"pitfalls":["半波1桥式4"]});
  window.STUDY_DATA.questions.push({"id":"ne5603","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"滤波电容","type":"judge","typeLabel":"判断","stem":"直流电源滤波电容越大，输出纹波越小。","options":["正确","错误"],"answer":"正确","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["直流电源","滤波"],"analysis":"【审题】判断：直流电源滤波电容越大，输出纹波越小。正确。【定律/公式】电容滤波：C 越大，放电越慢，纹波越小，输出越平滑；但过大有冲击电流。【步骤】① 因为电容大储存电荷多，放电时间长；② 所以纹波减小，说法正确；③ 因为电容小放电快纹波大，故本题正确。【答案】正确。【易错】×1 以为电容越大纹波越大；×2 不知滤波原理；×3 忽略冲击电流问题。【口诀】滤波电容越大好，纹波越小输出稳；太大冲击电流高，判断说法是正确。","steps":["【秒懂考点】电容大纹波小，正确","【第一步】储能多","【答案】正确"],"pitfalls":["大电容纹波小"]});
  window.STUDY_DATA.questions.push({"id":"nee109","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"滤波","type":"judge","typeLabel":"判断","difficulty":2,"difficultyLabel":"强化","stem":"电容滤波后输出直流电压会升高。","options":["正确","错误"],"answer":"正确","analysis":"【审题】判断：电容滤波后输出直流电压会升高。正确。【定律/公式】电容滤波后空载电压约 1.41U2（峰值），带载约 1.2U2，高于无滤波的 0.9U2（全波）。【步骤】① 因为电容充电到峰值后缓慢放电，电压维持较高；② 所以输出直流电压比无滤波高，说法正确；③ 因为无滤波是 0.9U2，滤波后升到约 1.2U2，故本题正确。【答案】正确。【易错】×1 以为滤波只平滑不升压；×2 与稳压混淆；×3 不知 1.2U2 与 0.9U2 区别。【口诀】电容滤波电压升，一二倍于变压器；无滤只有零点九，判断说法是正确。","source":"2027考纲补充","tags":["滤波","考纲补充"],"steps":["【秒懂考点】电容滤波使输出电压升高，正确","【第一步：充放电】导通时充电、截止时放电，补上塌陷电压","【第二步：升高】输出不再掉到0，平均值升高","【第三步：数值】空载≈√2U₂≈1.414，带载≈1.2，都高于0.9","【答案】正确"],"pitfalls":["滤波垫高电压；1.2带载、√2空载"]});
  window.STUDY_DATA.questions.push({"id":"nee144","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"三极管","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"三极管是电压控制器件。","options":["正确","错误"],"answer":"错误","analysis":"【答案】错误。三极管是电流控制器件（基极电流控制集电极电流），场效应管FET才是电压控制器件。\n\n判断：三极管是电流控制器件。正确。【定律/公式】三极管 IC=βIB，基极电流控制集电极电流，属电流控制；场效应管才是电压控制。【步骤】① 因为 IB 控制 IC；② 所以是电流控制器件，说法正确；③ 因为场效应管是电压控制，故本题正确。【答案】正确。【易错】×1 与场效应管电压控制混淆；×2 以为是电压控制；×3 不知控制方式。【口诀】三极管是流控制，基流控制集流走；场管才是压控制，判断说法是正确。","source":"2027考纲补充","tags":["三极管","考纲补充"],"steps":["【秒懂考点】三极管是电流控制器件，正确","【第一步】用Ib控制Ic，Ic=βIb，控制量是电流","【第二步】对比：场效应管是电压控制","【第三步】描述正确","【答案】正确"],"pitfalls":["三极管电流控制、场效应管电压控制"]});
  window.STUDY_DATA.questions.push({"id":"ne6202","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-6","knowledgePoint":"三极管开关","type":"judge","typeLabel":"判断","stem":"三极管作为开关使用时，工作在饱和区和截止区。","options":["正确","错误"],"answer":"正确","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["三极管","开关"],"analysis":"【审题】判断：三极管作为开关使用时工作在饱和区和截止区。正确。【定律/公式】开关应用：截止=断开，饱和=接通，放大区不作开关用。【步骤】① 因为截止时 IC≈0 相当开关断开；② 因为饱和时 UCE≈0.2 V 相当开关闭合；③ 所以开关工作在饱和与截止区，说法正确。【答案】正确。【易错】×1 以为开关用放大区；×2 与线性放大混淆；×3 不知饱和截止含义。【口诀】开关饱和截止区，截止断开饱和通；放大区里才是放，判断说法是正确。","steps":["【秒懂考点】开关饱和/截止，正确","【第一步】饱和接通截止断开","【答案】正确"],"pitfalls":["开关饱和截止，放大区线性"]});
  window.STUDY_DATA.questions.push({"id":"nee162","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"电压比较器","type":"judge","typeLabel":"判断","difficulty":2,"difficultyLabel":"强化","stem":"电压比较器中，当 U+>U- 时输出高电平。","options":["正确","错误"],"answer":"正确","analysis":"【审题】判断：电压比较器中当 U+>U− 时输出高电平。正确。【定律/公式】比较器：U+>U− 输出正饱和（高电平）；U+<U− 输出负饱和（低电平）。【步骤】① 因为同相端电压高于反相端时输出跳到正轨；② 所以输出高电平，说法正确；③ 因为反相时输出低电平，故本题正确。【答案】正确。【易错】×1 记反输出电平；×2 与反相放大混淆；×3 不知比较器传输特性。【口诀】比较器 U+ 高于 U−，输出高电平跳起来；U+ 低来输出低，判断说法是正确。","source":"2027考纲补充","tags":["电压比较器","考纲补充"],"steps":["【秒懂考点】U+>U-输出高，正确","【第一步】U+大推正饱和","【答案】正确"],"pitfalls":["U+大→高，U-大→低"]});
  window.STUDY_DATA.questions.push({"id":"nee163","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"运放电源","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"运放通常需要正负双电源供电。","options":["正确","错误"],"answer":"正确","analysis":"【审题】判断：运放通常需要正负双电源供电。正确。【定律/公式】集成运放通常用对称双电源（如 ±12 V），便于输出双极性；单电源运放需偏置。【步骤】① 因为双电源使输出能正能负；② 所以通常需要正负双电源，说法正确；③ 因为单电源是特例需偏置，故本题正确。【答案】正确。【易错】×1 以为单电源就够；×2 不知双电源作用；×3 与数字电路单电源混淆。【口诀】运放常用双电源，正负对称输出全；单电源要加偏置，判断说法是正确。","source":"2027考纲补充","tags":["运放电源","考纲补充"],"steps":["【秒懂考点】运放通常双电源，正确","【第一步】正负电源才能输出正负电压","【答案】正确"],"pitfalls":["双电源才能输出正负；单电源加偏置"]});
  window.STUDY_DATA.questions.push({"id":"nee179","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"TTL门","type":"judge","typeLabel":"判断","difficulty":2,"difficultyLabel":"强化","stem":"TTL门电路输入悬空相当于低电平。","options":["正确","错误"],"answer":"错误","analysis":"【答案】错误。TTL与非门输入悬空相当于高电平（逻辑1）。CMOS门电路输入不能悬空，否则电平不确定还容易击穿。\n\n判断：TTL 门电路输入悬空相当于高电平。正确。【定律/公式】TTL 电路输入级多发射极晶体管，输入悬空时相当于接高电平（逻辑 1）；CMOS 悬空则不定。【步骤】① 因为 TTL 输入悬空时内部上拉作用使输入端为高电平；② 所以该说法正确；③ 因为 CMOS 输入悬空不定且易损坏，与 TTL 不同，故本题正确。【答案】正确。【易错】×1 与 CMOS 悬空不定混淆；×2 以为悬空是低电平；×3 以为悬空一定损坏。【口诀】TTL 悬空算高电平，CMOS 悬空不安宁；输入端要接确定，判断说法是正确。","source":"2027考纲补充","tags":["TTL门","考纲补充"],"steps":["【秒懂考点】TTL悬空=高，正确","【第一步】悬空发射极无电流","【第二步】实际不建议悬空","【答案】正确"],"pitfalls":["TTL悬空当高，不建议"]});
  window.STUDY_DATA.questions.push({"id":"nee200","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-7","knowledgePoint":"门电路","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"与非门是通用门，可实现任何逻辑功能。","options":["正确","错误"],"answer":"正确","analysis":"【审题】判断：与非门是通用门，可实现任何逻辑功能。正确。【定律/公式】与非门是万能门（功能完备），可构成与、或、非及任何组合逻辑；或非门同样通用。【步骤】① 因为与非门通过组合可实现所有逻辑函数；② 所以是通用门，说法正确；③ 因为与门、或门、非门单独都不是完备集，故本题正确。【答案】正确。【易错】×1 以为只有专门芯片才能实现所有功能；×2 与或非门通用性混淆（其实两者都通用）；×3 不知功能完备概念。【口诀】与非门是万能门，任何逻辑都能拼；或非同样可通用，判断说法是正确。","source":"2027考纲补充","tags":["门电路","考纲补充"],"steps":["【秒懂考点】与非是通用门，正确","【第一步】可搭非与或，实现任意逻辑","【答案】正确"],"pitfalls":["与非或非都是通用门"]});
  window.STUDY_DATA.questions.push({"id":"ne8306","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-8","knowledgePoint":"TTL与非门悬空","type":"judge","typeLabel":"判断","stem":"TTL与非门输入端悬空相当于输入低电平。","options":["正确","错误"],"answer":"错误","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["门电路","TTL"],"analysis":"【答案】错误。TTL与非门输入端悬空等效于接高电平。这是TTL电路的特点，实际使用中多余输入端可悬空或接高电平。\n\n判断：TTL 与非门输入端悬空相当于输入高电平。正确，与前面 TTL 悬空题同理。【定律/公式】TTL 输入悬空≈高电平（逻辑 1）。【步骤】① 因为 TTL 输入级结构使悬空等效高电平；② 所以该说法正确；③ 因为这是 TTL 特性，CMOS 不同，故本题正确。【答案】正确。【易错】×1 与 CMOS 混淆；×2 以为悬空是低；×3 以为悬空损坏。【口诀】TTL 悬空是高电平，与非门也一样行；CMOS 悬空要避免，判断说法是正确。","steps":["【秒懂考点】TTL悬空=高，正确","【第一步】CMOS不能","【答案】正确"],"pitfalls":["TTL悬空CMOS不悬空"]});
  window.STUDY_DATA.questions.push({"id":"ex03e","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"fill","typeLabel":"填空","difficulty":1,"difficultyLabel":"基础","stem":"U=10V，R=5Ω，I=______A","answer":"2","accept":["2"],"tags":["欧姆定律"],"source":"batch","pitfalls":["2"],"explainLevel":"subject-specific","hint":"【结论】2 【考点】电路基本概念 【一步步怎么算】 ① 题目：U=10V，R=5Ω，I=______A。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（10）计算。 ④ 注意","analysis":"【审题】填空：U=10 V、R=5 Ω，求 I=______ A。用欧姆定律 I=U/R。【定律/公式】欧姆定律：I=U/R=10/5=2 A。【步骤】① 因为电流等于电压除以电阻；② 因为 10÷5=2；③ 因为单位是 A，所以填 2。【答案】2。【易错】×1 做成 R/U=0.5；×2 做成 U×R=50；×3 单位写错或漏写。【口诀】十伏五欧电流二，欧姆定律 I 等 U 除 R；填空数字要准确，单位安培别忘加。","steps":["【秒懂考点】I=U/R","【第一步】I=10/5=2A","【答案】2"]});
  window.STUDY_DATA.questions.push({"id":"pf01","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"fill","typeLabel":"填空","difficulty":1,"difficultyLabel":"基础","stem":"欧姆定律 U=______","answer":"IR","accept":["IR","I*R","I·R"],"pitfalls":["IR"],"tags":["欧姆定律"],"source":"highfreq","score":5,"explainLevel":"subject-specific","hint":"【结论】IR 【考点】电路基本概念 【一步步怎么算】 ① 题目：欧姆定律 U=______。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与","analysis":"【审题】填空：欧姆定律 U=______。考查欧姆定律公式变形 U=IR。【定律/公式】欧姆定律：U=IR（电压=电流×电阻）；I=U/R；R=U/I。【步骤】① 因为欧姆定律基本式可写成 U=IR；② 因为电压等于电流乘电阻；③ 所以填 IR。【答案】IR。【易错】×1 填 U/R 或 U/I；×2 填 I/R；×3 与功率公式 P=UI 混淆。【口诀】欧姆定律 U 等 IR，电压电流电阻仨；变形 I 等 U 除 R，R 等 U 除 I 也要。","steps":["【秒懂考点】欧姆定律 U=IR","【第一步】电压=电流×电阻","【答案】IR"]});
  window.STUDY_DATA.questions.push({"id":"pf02","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"fill","typeLabel":"填空","difficulty":1,"difficultyLabel":"基础","stem":"电阻 R=10Ω，U=5V，则 I=______A","answer":"0.5","accept":["0.5",".5"],"pitfalls":["0.5"],"tags":["欧姆定律"],"source":"highfreq","score":5,"explainLevel":"subject-specific","hint":"【结论】0.5 【考点】电路基本概念 【一步步怎么算】 ① 题目：电阻 R=10Ω，U=5V，则 I=______A。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（10）计","analysis":"【审题】填空：电阻 R=10 Ω、U=5 V，则电流 I=______ A。用欧姆定律求电流，注意数值小于 1。【定律/公式】欧姆定律：I=U/R，电压除以电阻得到电流。【步骤】① 因为电流等于电压除以电阻，所以用 I=U/R；② 因为 U=5 V、R=10 Ω，所以 I=5/10=0.5 A；③ 因为若除反会得 2 A，若误乘会得 50，所以正确【答案】0.5。【易错】×1 分子分母颠倒算成 R/U=2 A；×2 误用乘法 U×R=50；×3 小数点丢失写成 5 或 0.05。【口诀】五伏十欧零点五，压除电阻电流出；小数点要写清楚，单位安培不能无。","steps":["【秒懂考点】I=U/R","【第一步】I=5/10=0.5A","【答案】0.5"]});
  window.STUDY_DATA.questions.push({"id":"pf03","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"fill","typeLabel":"填空","difficulty":1,"difficultyLabel":"基础","stem":"功率 P=UI=I²R=______","answer":"frac{U²}{R}","accept":["frac{U^2}{R}","frac{U2}{R}"],"pitfalls":["U²/R"],"tags":["功率"],"source":"highfreq","score":5,"explainLevel":"subject-specific","hint":"【结论】(U²)/(R) 【考点】电路基本概念 【一步步怎么算】 ① 题目：功率 P=UI=I²R=______。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注","analysis":"【审题】填空：功率 P=UI=I²R=______。考查功率公式第三形式 U²/R。【定律/公式】P=UI=I²R=U²/R。【步骤】① 因为由 U=IR 代入 P=UI 得 P=U²/R；② 因为三式等价；③ 所以填 U²/R 或 frac{U²}{R}。【答案】frac{U²}{R}。【易错】×1 填 U/I 或 I/U；×2 填 UI（重复）；×3 忘记平方。【口诀】功率三式 UI、I²R、U²R 分之一；等价互换要熟练，填空写上 U² 除以 R。","steps":["【秒懂考点】功率三种形式","【第一步】P=UI=I²R=U²/R","【第二步】已知电压电阻时用U²/R","【答案】U²/R"]});
  window.STUDY_DATA.questions.push({"id":"tr1","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电路基本概念","type":"fill","typeLabel":"填空","difficulty":1,"difficultyLabel":"基础","stem":"欧姆定律 I=______","answer":"frac{U}{R}","accept":["frac{U}{R}"],"tags":["欧姆"],"source":"batch","pitfalls":["I=U/R"],"explainLevel":"subject-specific","hint":"【结论】(U)/(R) 【考点】电路基本概念 【一步步怎么算】 ① 题目：欧姆定律 I=______。 ② 用「电路基本概念」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/","analysis":"【审题】填空：欧姆定律 I=______。考查欧姆定律求电流的标准形式，是电路计算最基础公式。【定律/公式】欧姆定律三种形式：U=IR、I=U/R、R=U/I。求电流用 I=U/R。【步骤】① 因为欧姆定律描述电压、电流、电阻关系，求电流时用电压除以电阻；② 因为 I=U/R，所以空格应填 U/R；③ 因为 IR 是求电压、U/I 是求电阻，所以不能填错形式。【答案】frac{U}{R}。【易错】×1 填成 IR 或 U·R，那是求电压的公式；×2 填成 R/U，分子分母颠倒；×3 与功率公式 P=UI 混淆。【口诀】电流等于压除阻，I 等 U 除 R；三式变形记牢固，填空写对不含糊。","steps":["【秒懂考点】欧姆定律 I=U/R","【第一步】电流=电压÷电阻","【答案】U/R"]});
  window.STUDY_DATA.questions.push({"id":"ex08e","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"fill","typeLabel":"填空","difficulty":2,"difficultyLabel":"强化","stem":"KVL：任一闭合回路电压代数和为 ______","answer":"0","accept":["0"],"tags":["KVL"],"source":"batch","pitfalls":["0"],"explainLevel":"subject-specific","hint":"【结论】0 【考点】直流电路分析 【一步步怎么算】 ① 题目：KVL：任一闭合回路电压代数和为 ______。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单","analysis":"【审题】填空：KVL 任一闭合回路电压代数和为 ______。考查 KVL 结论：0。【定律/公式】KVL：ΣU=0（回路电压代数和为零）。【步骤】① 因为 KVL 是能量守恒，绕行一周电位升降抵消；② 因为代数和为零；③ 所以填 0。【答案】0。【易错】×1 填 1 或无穷；×2 填“电源电动势”；×3 与 KCL 电流和混淆。【口诀】KVL 回路电压零，代数和来等于零；能量守恒是本质，填空写零不费劲。","steps":["【秒懂考点】KVL代数和为0","【第一步】绕一周电位回到原点","【答案】0"]});
  window.STUDY_DATA.questions.push({"id":"ex19e","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"fill","typeLabel":"填空","difficulty":1,"difficultyLabel":"基础","stem":"E=9V，r=0，R=3Ω，I=______A","answer":"3","accept":["3"],"tags":["欧姆定律"],"source":"batch","pitfalls":["3"],"explainLevel":"subject-specific","hint":"【结论】3 【考点】直流电路分析 【一步步怎么算】 ① 题目：E=9V，r=0，R=3Ω，I=______A。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（9）计算。 ④ ","analysis":"【审题】填空：E=9 V、r=0、R=3 Ω，求 I=______ A。全电路欧姆定律。【定律/公式】全电路欧姆定律：I=E/(R+r)=9/(3+0)=3 A。【步骤】① 因为总电动势除以总电阻；② 因为 9÷3=3；③ 所以填 3。【答案】3。【易错】×1 忘记加内阻 r（本题为 0 无影响）；×2 做成 E×R=27；×3 单位漏写。【口诀】全路欧姆 I 等 E 除 R 加 r，九伏三欧三安培；内阻为零更好算，填空写三没有错。","steps":["【秒懂考点】I=E/R（内阻0）","【第一步】I=9/3=3A","【答案】3"]});
  window.STUDY_DATA.questions.push({"id":"pf04","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"fill","typeLabel":"填空","difficulty":1,"difficultyLabel":"基础","stem":"两电阻 R₁=R₂=R 并联，等效电阻为 ______R","answer":"0.5","accept":["frac{1}{2}","0.5R","frac{R}{2}"],"pitfalls":["0.5"],"tags":["并联"],"source":"highfreq","score":5,"explainLevel":"subject-specific","hint":"【结论】0.5 【考点】直流电路分析 【一步步怎么算】 ① 题目：两电阻 R₁=R₂=R 并联，等效电阻为 ______R。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算","analysis":"【审题】填空：两电阻 R₁=R₂=R 并联，等效电阻为 ______R。相同电阻并联减半。【定律/公式】两相同电阻 R 并联：R并=R/2=0.5R。【步骤】① 因为 1/R并=1/R+1/R=2/R；② 因为 R并=R/2=0.5R；③ 所以填 0.5。【答案】0.5。【易错】×1 填 2（那是串联）；×2 填 1；×3 填 0.25。【口诀】两同相并除以二，零点五 R 是","steps":["【秒懂考点】两相同电阻并联","【第一步】R并=R×R/(R+R)=R/2=0.5R","【答案】0.5"]});
  window.STUDY_DATA.questions.push({"id":"pf05","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"直流电路分析","type":"fill","typeLabel":"填空","difficulty":2,"difficultyLabel":"强化","stem":"基尔霍夫电流定律（KCL）：任一节点电流的代数和为 ______","answer":"0","accept":["0","零"],"pitfalls":["0"],"tags":["KCL"],"source":"highfreq","score":5,"explainLevel":"subject-specific","hint":"【结论】0 【考点】直流电路分析 【一步步怎么算】 ① 题目：基尔霍夫电流定律（KCL）：任一节点电流的代数和为 ______。 ② 用「直流电路分析」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量","analysis":"【审题】填空：基尔霍夫电流定律（KCL）指出任一节点电流的代数和为 ______。考查 KCL 的标准表述。【定律/公式】KCL：任一时刻，对任一节点，流入电流之和等于流出电流之和，即电流代数和为零。【步骤】① 因为电荷在节点不能堆积也不能消失，所以流入必须等于流出；② 因为流入流出取相反符号相加后代数和为零，所以空格应填 0；③ 因为 KVL 才是回路电压代数和为零，两者不要混淆，所以本题【答案】0。【易错】×1 填成 1 或无穷大，不知道代数和的含义；×2 与 KVL 回路电压和混淆，答成电压相关；×3 填“相等”而不是数值 0，填空题要求数值。【口诀】KCL 节点电流零，代数和来等于零；电荷守恒是本质，填空写零最分明。","steps":["【秒懂考点】KCL代数和为0","【第一步】流入为正流出为负，相加为0","【答案】0"]});
  window.STUDY_DATA.questions.push({"id":"ex12e","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电路定理","type":"fill","typeLabel":"填空","difficulty":2,"difficultyLabel":"强化","stem":"诺顿等效是电流源______联电阻","answer":"并","accept":["并联","并"],"tags":["诺顿"],"source":"batch","pitfalls":["并"],"explainLevel":"subject-specific","hint":"【结论】并 【考点】电路定理 【一步步怎么算】 ① 题目：诺顿等效是电流源______联电阻。 ② 用「电路定理」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/A/Ω）与符","analysis":"【审题】填空：诺顿等效是电流源______联电阻。考查诺顿等效电路的结构。【定律/公式】诺顿定理：有源二端网络可等效为电流源与电阻并联；戴维南定理则是电压源与电阻串联。【步骤】① 因为诺顿等效用电流源表示短路电流，内阻并联在电流源两端；② 因为电流源并联电阻才能构成诺顿标准形式，所以空格填“并”；③ 因为戴维南是串联结构，填“串”就错了，所以正确【答案】并。【易错】×1 填成“串”，与戴维南等效结构混淆；×2 分不清诺顿与戴维南两种等效形式；×3 填成“混联”，标准形式只有串联或并联。【口诀】诺顿流源并电阻，戴维南压串阻；一字之差要分清，填空写并不糊涂。","steps":["【秒懂考点】诺顿电流源并联电阻","【第一步】电流源并内阻","【答案】并"]});
  window.STUDY_DATA.questions.push({"id":"pf06","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-3","knowledgePoint":"电路定理","type":"fill","typeLabel":"填空","difficulty":2,"difficultyLabel":"强化","stem":"戴维南等效电路由电压源与电阻______联组成","answer":"串","accept":["串联","串"],"pitfalls":["串"],"tags":["戴维南"],"source":"highfreq","score":5,"explainLevel":"subject-specific","hint":"【结论】串 【考点】电路定理 【一步步怎么算】 ① 题目：戴维南等效电路由电压源与电阻______联组成。 ② 用「电路定理」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/","analysis":"【审题】填空：戴维南等效电路由电压源与电阻______联组成。考查戴维南等效结构。【定律/公式】戴维南定理：线性有源二端网络等效为开路电压源与等效内阻串联。【步骤】① 因为戴维南等效对外表现为开路电压与内阻串联；② 因为电压源必须串联电阻才能模拟内阻压降，所以空格填“串”；③ 因为诺顿才是电流源并联电阻，填“并”就错了，所以正确【答案】串。【易错】×1 填成“并”，与诺顿等效混淆；×2 不理解为什么是串联而不是并联；×3 填成“混联”，不是标准表述。【口诀】戴维南压串阻，诺顿流并阻；结构特点要牢记，填空写串是正路。","steps":["【秒懂考点】戴维南电压源与电阻串联","【第一步】开路电压串等效内阻","【答案】串"]});
  window.STUDY_DATA.questions.push({"id":"ex15e","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"fill","typeLabel":"填空","difficulty":2,"difficultyLabel":"强化","stem":"硅二极管正向导通压降约 ______V","answer":"0.7","accept":["0.7","0.7V"],"tags":["二极管"],"source":"batch","pitfalls":["0.7"],"explainLevel":"subject-specific","hint":"【结论】0.7 【考点】运算放大器 【一步步怎么算】 ① 题目：硅二极管正向导通压降约 ______V。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。 ④ 注意单位（V/","analysis":"【审题】填空：硅二极管正向导通压降约 ______V。硅管 0.7 V。【定律/公式】硅管导通压降约 0.7 V（0.6~0.8 V）；锗 0.3 V。【步骤】① 因为硅 PN 结导通典型压降 0.7 V；② 因为锗是 0.3 V、理想是 0；③ 所以填 0.7。【答案】0.7。【易错】×1 填 0.3（锗管）；×2 填 0（理想）；×3 填 1.4（两管）。【口诀】硅管七伏填零点七，锗管三伏要分清；理想模型才是零，填空写对数就行。","steps":["【秒懂考点】硅管压降0.7V","【第一步】锗管0.3V","【答案】0.7"]});
  window.STUDY_DATA.questions.push({"id":"pf07","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"fill","typeLabel":"填空","difficulty":2,"difficultyLabel":"强化","stem":"理想运放虚短条件：u₊ 与 u₋ 的关系是 u₊ = ______","answer":"u-","accept":["u−","u_","u负"],"pitfalls":["u-"],"tags":["运放"],"source":"highfreq","score":5,"explainLevel":"subject-specific","hint":"【结论】u- 【考点】运算放大器 【一步步怎么算】 ① 题目：理想运放虚短条件：u₊ 与 u₋ 的关系是 u₊ = ______。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量","analysis":"【审题】填空：理想运放虚短条件 u₊ 与 u₋ 关系是 u₊ = ______。虚短即 u₊=u₋。【定律/公式】虚短：u₊=u₋（两输入端电位相等）。【步骤】① 因为理想运放开环增益∞，线性区两输入端电位近似相等；② 因为虚短定义就是 u₊=u₋；③ 所以填 u−。【答案】u-。【易错】×1 填 0（那是虚地）；×2 填 i−（那是虚断）；×3 填 uo。【口诀】虚短 u₊ 等于 u−，两输入端电位齐；虚断电流才是零，填空写 u− 不迟疑。","steps":["【秒懂考点】虚短 u+=u-","【第一步】两输入端电压相等","【答案】u-"]});
  window.STUDY_DATA.questions.push({"id":"pf08","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"fill","typeLabel":"填空","difficulty":2,"difficultyLabel":"强化","stem":"反相放大器放大倍数 A = -(______)","answer":"frac{Rf}{R1}","accept":["frac{Rf}{R1}","frac{Rf}{R₁}"],"pitfalls":["Rf/R1"],"tags":["运放"],"source":"highfreq","score":5,"explainLevel":"subject-specific","hint":"【结论】(Rf)/(R1) 【考点】运算放大器 【一步步怎么算】 ① 题目：反相放大器放大倍数 A = -(______)。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量计算。","analysis":"【审题】填空：反相放大器放大倍数 A=−(______)。反相增益是 Rf/R1。【定律/公式】反相放大：Au=−Rf/R1。【步骤】① 因为反相放大增益为负的反馈电阻与输入电阻之比；② 因为 A=−(Rf/R1)；③ 所以填 Rf/R1 或 frac{Rf}{R1}。【答案】frac{Rf}{R1}。【易错】×1 填 R1/Rf（颠倒）；×2 填 1+Rf/R1（同相）；×3 漏负号（题目已给负号）。【口诀】反相放大负阻比，Rf 除以 R1 记心里；括号里面填比值，负号题目已给出。","steps":["【秒懂考点】反相倍数 A=-Rf/R1","【第一步】负号表示反相","【答案】Rf/R1"]});
  window.STUDY_DATA.questions.push({"id":"tr7","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"运算放大器","type":"fill","typeLabel":"填空","difficulty":2,"difficultyLabel":"强化","stem":"同相放大增益 Au=1+Rf/______","answer":"R1","accept":["R1"],"tags":["运放"],"source":"batch","pitfalls":["分母R1"],"explainLevel":"subject-specific","hint":"【结论】R1 【考点】运算放大器 【一步步怎么算】 ① 题目：同相放大增益 Au=1+Rf/______。 ② 用「运算放大器」相关公式（欧姆 U=IR、运放 A=−Rf/R1、KCL/KVL 等）。 ③ 代入已知量（1）计算。 ④ 注意单","analysis":"【审题】填空：同相放大增益 Au=1+Rf/______。考查同相放大器增益公式的分母。【定律/公式】同相放大器：Au=1+Rf/R1，其中 Rf 是反馈电阻，R1 是反相端到地的电阻。【步骤】① 因为同相放大增益等于 1 加上 Rf 与 R1 之比；② 因为公式分母是接地电阻 R1，所以空格填 R1；③ 因为若填 Rf 就成了 Rf/Rf=1，公式不成立，所以正确【答案】R1。【易错】×1 填成 Rf，分子分母都是 Rf 导致增益错误；×2 与反相放大公式 −Rf/R1 混淆；×3 填成 R2 或其他符号，标准写法是 R1。【口诀】同相增益一加比，Rf 除以 R1 齐；分母就是 R1 电阻，填空写对不偏离。","steps":["【秒懂考点】同相增益 Au=1+Rf/R1","【定律/公式】同相放大器：Au=1+Rf/R1，其中 Rf 是反馈电阻，R1 是反相端到地的电阻。","【步骤】① 因为同相放大增益等于 1 加上 Rf 与 R1 之比；② 因为公式分母是接地电阻 R1，所以空格填 R1；③ 因为若填 Rf 就成了 Rf/Rf=1，公式不成立，所以正确答案是 R1。","【口诀】同相增益一加比，Rf 除以 R1 齐；分母就是 R1 电阻，填空写对不偏离。","【答案】R1"]});
  window.STUDY_DATA.questions.push({"id":"nee11","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"串联电阻","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"R₁=5Ω，R₂=15Ω 串联，等效电阻？","options":null,"answer":"20Ω","analysis":"【审题】计算：R₁=5 Ω、R₂=15 Ω 串联，求等效电阻。考查串联电阻相加。【定律/公式】串联电阻等效值：R=R1+R2。【步骤】① 因为串联电路中电流处处相等，各电阻电压按阻值分配，等效电阻等于各电阻之和；② 因为 R1=5 Ω、R2=15 Ω，所以 R=5+15=20 Ω；③ 因为并联才会小于任一分电阻，本题是串联，所以等效电阻为 20 Ω。【答案】20Ω。【易错】×1 误用并联公式算成约 3.75 Ω；×2 只答其中一个电阻 5 Ω 或 15 Ω；×3 误用乘法 5×15=75 Ω。【口诀】五欧十五串起来，相加二十是总阻；串联相加并积和，计算细心不出误。","source":"2027考纲补充","tags":["串联电阻","考纲补充"],"steps":["【秒懂考点】5+15=20","【第一步】串联","【答案】20Ω"],"pitfalls":["5+15=20"]});
  window.STUDY_DATA.questions.push({"id":"nee12","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"并联电阻","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"R₁=6Ω，R₂=3Ω 并联，等效电阻？","options":null,"answer":"2Ω","analysis":"【审题】计算：R₁=6 Ω、R₂=3 Ω 并联，求等效电阻。考查并联电阻公式。【定律/公式】并联电阻：R=R1R2/(R1+R2)=18/9=2 Ω。【步骤】① 因为并联电路各支路电压相等，等效电阻的倒数等于各电阻倒数之和；② 因为 R=6×3/(6+3)=18/9=2 Ω；③ 因为串联会得到 9 Ω，并联总阻一定小于最小分电阻，所以等效电阻为 2 Ω。【答案】2Ω。【易错】×1 误用串联相加得 9 Ω；×2 答较大或较小的单个电阻 6 Ω 或 3 Ω；×3 倒数和算成 1/2 后忘记取倒数。【口诀】六并三欧二欧整，积除以和要记清；串联九欧并两欧，对照计算最分明。","source":"2027考纲补充","tags":["并联电阻","考纲补充"],"steps":["【秒懂考点】18/9=2","【第一步】乘积除以和","【答案】2Ω"],"pitfalls":["18/9=2"]});
  window.STUDY_DATA.questions.push({"id":"nee15","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电功率","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"已知 U=10V，I=2A，求功率 P。","options":null,"answer":"20W","analysis":"【审题】计算：已知电压 U=10 V、电流 I=2 A，求功率 P。直接用电功率公式即可。【定律/公式】电功率公式 P=UI，也可以写成 P=I²R 或 P=U²/R，本题已知 U 和 I，用 P=UI 最方便。【步骤】① 因为功率等于电压与电流的乘积，所以选用 P=UI；② 因为 U=10 V、I=2 A，所以 P=10×2=20 W；③ 因为若误用 U/I 会得到电阻 5 Ω，误用 U+I 量纲不对，所以正确【答案】20W。【易错】×1 误用 U/I 算成 5，那是电阻不是功率；×2 误用 U+I=12，量纲不一致不能相加；×3 忘记写单位 W，只写数字 20。【口诀】功率电压乘电流，十伏两安二十瓦；P 等 UI 要记牢，单位瓦特不能差。","source":"2027考纲补充","tags":["电功率","考纲补充"],"steps":["【秒懂考点】P=10×2=20","【第一步】UI","【答案】20W"],"pitfalls":["10×2=20"]});
  window.STUDY_DATA.questions.push({"id":"nee16","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电功率","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"已知 I=2A，R=3Ω，求功率 P。","options":null,"answer":"12W","analysis":"【审题】计算：已知电流 I=2 A、电阻 R=3 Ω，求功率 P。选用 P=I²R。【定律/公式】电功率公式：P=I²R，适用于已知电流和电阻的情况。【步骤】① 因为已知电流和电阻，所以用 P=I²R；② 因为 I²=2²=4，再乘 R=3 Ω，所以 P=4×3=12 W；③ 因为若漏掉平方只算 IR=6，那是电压不是功率，所以正确【答案】12W。【易错】×1 漏掉平方，算成 I×R=6，得到的是电压；×2 用错公式 U²/R 但 U 未知；×3 单位写成 V 或 A 而不是 W。【口诀】已知电流用平方，二安平方乘三欧；十二瓦特算出来，公式选对不用愁。","source":"2027考纲补充","tags":["电功率","考纲补充"],"steps":["【秒懂考点】P=I²R=4×3=12","【第一步】I²=4","【答案】12W"],"pitfalls":["I²R"]});
  window.STUDY_DATA.questions.push({"id":"nee17","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电功率","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"已知 U=6V，R=2Ω，求功率 P。","options":null,"answer":"18W","analysis":"【审题】计算：已知 U=6 V、R=2 Ω，求功率 P。用 P=U²/R。【定律/公式】P=U²/R=36/2=18 W。【步骤】① 因为已知电压电阻，用 P=U²/R；② 因为 36/2=18 W；③ 所以功率 18 W。【答案】18W。【易错】×1 用 U/R=3 W（那是电流）；×2 漏平方得 3 W；×3 单位漏写。【口诀】已知压阻用 U 方，六伏平方三十六；除以二欧十八瓦，公式选择要对头。","source":"2027考纲补充","tags":["电功率","考纲补充"],"steps":["【秒懂考点】P=U²/R=36/2=18","【第一步】U²=36","【答案】18W"],"pitfalls":["U²/R"]});
  window.STUDY_DATA.questions.push({"id":"nee205","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电阻并联","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"R₁=30Ω，R₂=60Ω 并联，求等效电阻。","options":null,"answer":"20Ω","analysis":"【审题】计算：R₁=30 Ω、R₂=60 Ω 并联，求等效电阻。并联积除以和。【定律/公式】R=30×60/(30+60)=1800/90=20 Ω。【步骤】① 因为并联用积除以和；② 因为 1800/90=20 Ω；③ 所以等效电阻 20 Ω。【答案】20Ω。【易错】×1 串联相加得 90 Ω；×2 答 30 或 60；×3 倒数和未取倒。【口诀】三十六十并联起，积除以和二十欧；串联九十并二十，对照计算要记住。","source":"2027考纲补充","tags":["电阻并联","考纲补充"],"steps":["【秒懂考点】并联R=乘积/和","【第一步】30×60/90=20Ω","【第二步】20<30合理","【答案】20Ω"],"pitfalls":["乘积除以和，别串联90"]});
  window.STUDY_DATA.questions.push({"id":"nee217","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"三要素","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"u=311sin(314t+π/4)V，求有效值和初相。","options":null,"answer":"220V，π/4","analysis":"【审题】计算：u=311sin(314t+π/4) V，求有效值和初相。从表达式读三要素。【定律/公式】u=Um sin(ωt+ψ)：Um=311 V，有效值 U=Um/√2≈220 V，初相 ψ=π/4。【步骤】① 因为最大值 Um=311 V；② 因为 U=311/√2≈220 V；③ 因为初相是 π/4，所以【答案】220V，π/4。【易错】×1 把 311 当有效值；×2 初相读成 π/2 或 0；×3 有效值算成 311×√2。【口诀】三百一十一最大值，除以根二二百二；初相位是四分之派，三要素读出就完毕。","source":"2027考纲补充","tags":["三要素","考纲补充"],"steps":["【秒懂考点】有效值=幅值/√2，初相常数","【第一步】311/√2≈220","【第二步】初相π/4","【答案】220V，π/4"],"pitfalls":["311峰值对应220有效值"]});
  window.STUDY_DATA.questions.push({"id":"nee251","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电阻计算","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"R=44Ω 接 220V，求电流。","options":null,"answer":"5A","analysis":"【审题】计算：电阻 R=44 Ω 接在 220 V 电源上，求电流 I。用欧姆定律。【定律/公式】欧姆定律：I=U/R，电压除以电阻得到电流。【步骤】① 因为电流等于电压除以电阻，所以用 I=U/R；② 因为 U=220 V、R=44 Ω，所以 I=220/44=5 A；③ 因为若除反会得 0.2 A，若误乘会得很大数值，所以正确【答案】5A。【易错】×1 分子分母颠倒算成 R/U≈0.2 A；×2 误用乘法 U×R=9680；×3 单位漏写 A。【口诀】二百二伏四十四欧，相除正好五安培；欧姆定律 I 等 U 除 R，计算细心不白费。","source":"2027考纲补充","tags":["电阻计算","考纲补充"],"steps":["【秒懂考点】I=U/R","【第一步】220/44=5","【答案】5A"],"pitfalls":["220÷44=5"]});
  window.STUDY_DATA.questions.push({"id":"nee252","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"功率","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"10Ω 电阻通 2A 电流，功率？","options":null,"answer":"40W","analysis":"【审题】计算：10 Ω 电阻通过 2 A 电流，求功率 P。用 P=I²R。【定律/公式】功率公式 P=I²R，已知电流和电阻时最直接。【步骤】① 因为 P=I²R，电流要平方；② 因为 I²=4，4×10=40 W；③ 因为漏平方会得 20 W，那是电压值，所以正确【答案】40W。【易错】×1 漏掉平方算成 I×R=20，得到电压；×2 用错公式但数据不匹配；×3 单位写错。【口诀】二安平方四乘十，四十瓦特是功率；I 方乘 R 要记清，漏了平方差一倍。","source":"2027考纲补充","tags":["功率","考纲补充"],"steps":["【秒懂考点】P=I²R","【第一步】4×10=40","【答案】40W"],"pitfalls":["用I²R"]});
  window.STUDY_DATA.questions.push({"id":"nee253","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电能","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"100W 灯泡工作 5 小时耗电多少度？","options":null,"answer":"0.5 度","analysis":"【审题】计算：100 W 灯泡工作 5 小时耗电多少度。W=Pt，1 度=1 kW·h。【定律/公式】W=Pt=0.1 kW×5 h=0.5 kW·h=0.5 度。【步骤】① 因为 100 W=0.1 kW；② 因为 0.1×5=0.5 kW·h；③ 所以耗电 0.5 度。【答案】0.5 度。【易错】×1 不化 kW 得 500 度；×2 时间用错；×3 单位写成 W。【口诀】百瓦五时算电能，化成千瓦零点一；乘五正好半度电，千瓦时是度的名。","source":"2027考纲补充","tags":["电能","考纲补充"],"steps":["【秒懂考点】W=Pt，1度=1kWh","【第一步】0.1×5=0.5","【答案】0.5度"],"pitfalls":["先瓦换千瓦，100W=0.1kW"]});
