  window.STUDY_DATA.questions.push({"id":"nee291","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"数制转换","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"二进制 1101 转十进制。","options":null,"answer":"13","analysis":"【审题】计算：二进制数 1101 转换成十进制。按位权展开求和。【定律/公式】二进制转十进制：从右到左每位乘以 2 的位权次幂再相加。【步骤】① 因为二进制 1101 的各位权从右到左是 2⁰、2¹、2²、2³；② 因为 1×8+1×4+0×2+1×1=8+4+0+1=13；③ 因为漏算最低位会得 12，位权错会得其他数，所以正确【答案】13。【易错】×1 位权顺序搞反，从左到右当 2⁰ 开始；×2 漏掉最低位 1，算成 12；×3 与 1011 等其他二进制混淆。【口诀】幺幺零幺按权算，八四零一加十三；二转十来要细心，位权顺序不能乱。","source":"2027考纲补充","tags":["数制转换","考纲补充"],"steps":["【秒懂考点】1101=8+4+1","【第一步】=13","【答案】13"],"pitfalls":["1101=13"]});
  window.STUDY_DATA.questions.push({"id":"nee292","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"数制转换","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"十进制 25 转二进制。","options":null,"answer":"11001","analysis":"【审题】计算：十进制 25 转二进制。除 2 取余逆序或按权凑。【定律/公式】十转二：除 2 取余逆序；25=16+8+1=11001B。【步骤】① 因为 25÷2=12 余 1，12÷2=6 余 0，6÷2=3 余 0，3÷2=1 余 1，1÷2=0 余 1，余数逆序 11001；② 因为 16+8+1=25 对应 11001，验算正确；③ 所以二进制为 11001。【答案】11001。【易错】×1 余数写反成 10011；×2 漏位写成 1101；×3 用除 2 取商。【口诀】廿五转二幺幺零零幺，十六八一要凑齐；除二取余逆序写，验算一遍最保险。","source":"2027考纲补充","tags":["数制转换","考纲补充"],"steps":["【秒懂考点】25=16+8+1=11001","【第一步】验证=25","【答案】11001"],"pitfalls":["25是11001"]});
  window.STUDY_DATA.questions.push({"id":"nee301","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"欧姆定律","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"U=24V，R=8Ω，I=？","options":null,"answer":"3A","analysis":"【审题】计算：已知电压 U=24 V、电阻 R=8 Ω，求电流 I。直接套用欧姆定律即可。【定律/公式】欧姆定律：I=U/R，电流等于电压除以电阻。【步骤】① 因为电流等于电压除以电阻，所以用 I=U/R；② 因为 U=24 V、R=8 Ω，所以 I=24/8=3 A；③ 因为若除反会得 0.33 A，若误乘会得 192，所以正确【答案】3A。【易错】×1 分子分母颠倒算成 R/U=0.33 A；×2 误用乘法 U×R=192；×3 单位漏写 A 或写成 V。【口诀】二十四伏八欧姆，相除正好三安培；压上阻下不能反，欧姆定律最干脆。","source":"2027考纲补充","tags":["欧姆定律","考纲补充"],"steps":["【秒懂考点】I=24/8","【第一步】=3","【答案】3A"],"pitfalls":["24÷8=3"]});
  window.STUDY_DATA.questions.push({"id":"nee302","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-1","knowledgePoint":"电阻串并联","type":"calc","typeLabel":"计算","difficulty":1,"difficultyLabel":"基础","stem":"三个 9Ω 并联等效？","options":null,"answer":"3Ω","analysis":"【审题】计算：三个 9 Ω 电阻并联，求等效电阻。相同电阻并联除以个数。【定律/公式】n 个相同电阻 R 并联等效为 R/n，本题 n=3，R=9 Ω。【步骤】① 因为三个相同电阻并联，等效电阻等于单个电阻除以个数；② 因为 9/3=3 Ω；③ 因为若串联会得 27 Ω，并联总阻一定小于最小分电阻，所以正确【答案】3Ω。【易错】×1 误用串联相加得 27 Ω；×2 只除以 2 得 4.5 Ω，个数用错；×3 倒数和算成 1/3 后忘记取倒数。【口诀】三个九欧并联起，总阻三欧是正理；相同并联除个数，串联才是乘个数。","source":"2027考纲补充","tags":["电阻串并联","考纲补充"],"steps":["【秒懂考点】9/3=3Ω","【第一步】三相同并联","【答案】3Ω"],"pitfalls":["9÷3=3"]});
